(window.APP_LAW_DATA = window.APP_LAW_DATA || {})["K0040013"] = {"pcode":"K0040013","group":"emt","name":"道路交通安全規則","date_label":"修正日期","date":"民國 115 年 06 月 26 日","url":"https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=K0040013","article_count":185,"chapters":[{"title":"第 一 章 總則","articles":[{"no":"1","label":"第 1 條","lines":[[0,"本規則依道路交通管理處罰條例第九十二條第一項規定訂定之。"]]},{"no":"2","label":"第 2 條","lines":[[0,"本規則用詞，定義如下："],[2,"一、汽車：指在道路上不依軌道或電力架線而以原動機行駛之車輛（包括機車）。"],[2,"二、客車：指載乘人客四輪以上之汽車。"],[2,"三、貨車：指裝載貨物四輪以上之汽車。"],[2,"四、客貨兩用車：指兼載人客及貨物之汽車。"],[2,"五、代用客車：指不載貨時代替客車使用之貨車。"],[2,"六、幼童專用車：指專供載運二歲以上未滿七歲兒童之客車。"],[2,"七、特種車：指有特種設備供專門用途而異於一般汽車之車輛，包括吊車、救濟車、消防車、救護車、警備車、憲警巡邏車、工程車、教練車、身心障礙者用特製車、灑水車、郵車、垃圾車、清掃車、水肥車、囚車、殯儀館運靈車及經交通部核定之其他車輛。"],[2,"八、曳引車：指專供牽引其他車輛之汽車。"],[2,"九、拖車：指由汽車牽引，其本身並無動力之車輛；依其重量等級區分，總重量逾七百五十公斤者為重型拖車，七百五十公斤以下者為輕型拖車。"],[2,"十、全拖車：指具有前後輪，其前端附掛於汽車之拖車。"],[3,"十一、半拖車：指具有後輪，其前端附掛於曳引車第五輪之拖車。"],[3,"十二、拖架：指專供裝運十公尺以上超長物品並以物品本身連結曳引車之架形拖車。"],[3,"十三、聯結車：指汽車與重型拖車所組成之車輛。但不包括小型車附掛總重逾七百五十公斤至三千公斤以下拖車。"],[3,"十四、全聯結車：指一輛曳引車或一輛汽車與一輛或一輛以上重型全拖車所組成之車輛。"],[3,"十五、半聯結車：指一輛曳引車與一輛重型半拖車所組成之車輛。"],[3,"十六、車重：指車輛未載客貨及駕駛人之空車重量。"],[3,"十七、載重：指車輛允許載運客貨之重量。"],[3,"十八、總重：指車重與載重之全部重量。"],[3,"十九、總聯結重量：指曳引車及拖車之車重與載重之全部重量。"],[3,"二十、雙軸軸組：兩個車軸其相鄰車軸中心點之距離小於二點四公尺，且由廠商宣告所形成之車軸組合。"],[4,"二十一、參軸軸組：三個車軸其相鄰車軸中心點之距離小於二點四公尺，且由廠商宣告所形成之車軸組合。"],[4,"二十二、第五輪載重量：指曳引車轉盤所承受之重量。"],[4,"二十三、雙層公車：指具有上下兩層座位及通道，專供市區汽車客運業及公路汽車客運業作為公共汽車使用之客車。"],[4,"二十四、雙節式大客車：指由兩節剛性車廂相互鉸接組成，專供市區汽車客運業於主管機關核准路線作為公共汽車使用之客車。"],[4,"二十五、大眾捷運系統車輛：指大眾捷運法所定大眾捷運系統使用之專用動力車輛。"],[4,"二十六、古董車：指車齡逾三十五年經交通部委託之審驗機構審驗合格且限領用專用牌照之小客車及機車。"],[0,"前項第一款所指之汽車，如本規則同一條文或相關條文就機車另有規定者，係指除機車以外四輪以上之車輛。"]]},{"no":"3","label":"第 3 條","lines":[[0,"汽車依其使用性質，分為下列各類："],[2,"一、客車："],[3,"（一）大客車：座位在十座以上或總重量逾三千五百公斤之客車、座位在二十五座以上或總重量逾三千五百公斤之幼童專用車。其座位之計算包括駕駛人、幼童管理人及營業車之服務員在內。"],[3,"（二）小客車：座位在九座以下之客車或座位在二十四座以下之幼童專用車。其座位之計算包括駕駛人及幼童管理人在內。"],[2,"二、貨車："],[3,"（一）大貨車："],[301,"1.總重量逾三千五百公斤之貨車。"],[301,"2.自中華民國一百零九年九月四日起，新登檢領照總重量逾三千五百公斤至五千公斤且全長逾六公尺之貨車。"],[3,"（二）小貨車："],[301,"1.總重量在三千五百公斤以下之貨車。"],[301,"2.自中華民國一百零九年九月四日起，新登檢領照總重量逾三千五百公斤至五千公斤且全長六公尺以下之貨車。"],[2,"三、客貨兩用車："],[3,"（一）大客貨兩用車：總重量逾三千五百公斤，並核定載人座位，或全部座位在十座以上，並核定載重量之汽車。"],[3,"（二）小客貨兩用車：總重量在三千五百公斤以下，或全部座位在九座以下，並核定載人座位及載重量，其最後一排座椅固定後，後方實際之載貨空間達一立方公尺以上之汽車。"],[2,"四、代用客車："],[3,"（一）代用大客車：大貨車兼供代用客車者，為代用大客車，其載客人數包括駕駛人在內不得超過二十五人。"],[3,"（二）代用小客車：小貨車兼供代用客車者，為代用小客車，其載客人數包括駕駛人在內不得超過九人。"],[2,"五、特種車："],[3,"（一）大型特種車：總重量逾三千五百公斤，或全部座位在十座以上之特種車。"],[3,"（二）小型特種車：總重量在三千五百公斤以下，或全部座位在九座以下之特種車。"],[2,"六、機車："],[3,"（一）重型機車："],[301,"1.普通重型機車："],[252,"（1）汽缸總排氣量逾五十立方公分且在二百五十立方公分以下之二輪或三輪機車。"],[252,"（2）電動機車之馬達及控制器最大輸出馬力逾五馬力且在四十馬力（HP）以下之二輪或三輪機車。"],[301,"2.大型重型機車："],[252,"（1）汽缸總排氣量逾二百五十立方公分之二輪或三輪機車。"],[252,"（2）電動機車之馬達及控制器最大輸出馬力逾四十馬力（HP）之二輪或三輪機車。"],[3,"（二）輕型機車："],[301,"1.普通輕型機車："],[252,"（1）汽缸總排氣量在五十立方公分以下之二輪或三輪機車。"],[252,"（2）電動機車之馬達及控制器最大輸出馬力在五馬力（HP）以下、一點三四馬力（電動機功率一千瓦）以上或最大輸出馬力小於一點三四馬力（電動機功率小於一千瓦），且最大行駛速率逾每小時四十五公里之二輪或三輪機車。"],[301,"2.小型輕型機車：電動機車之馬達及控制器最大輸出馬力小於一點三四馬力（電動機功率小於一千瓦），且最大行駛速率在每小時四十五公里以下之二輪或三輪機車。"],[3,"（三）第一目重型機車包含具封閉式車室及方向盤式轉向系統之三輪機車（以下簡稱駕艙機車）。"],[3,"（四）前三目三輪機車以車輪為前一後二或前二後一對稱型式排列之機車為限。"]]},{"no":"4","label":"第 4 條","lines":[[0,"汽車依其使用目的，分為下列二類："],[2,"一、自用：機關、學校、團體、公司、行號或個人自用而非經營客貨運之車輛。"],[2,"二、營業：汽車運輸業以經營客貨運為目的之車輛。"]]},{"no":"5","label":"第 5 條","lines":[[0,"汽車駕駛人分類如下："],[2,"一、職業駕駛人：指以駕駛汽車為職業者。"],[2,"二、普通駕駛人：指以駕駛自用車而非駕駛汽車為職業者。"]]},{"no":"6","label":"第 6 條","lines":[[0,"慢車種類及名稱如下："],[2,"一、自行車："],[3,"（一）腳踏自行車。"],[3,"（二）電動輔助自行車：指經型式審驗合格，以人力為主，電力為輔，最大行駛速率在每小時二十五公里以下，且車重在四十公斤以下之二輪車輛。"],[3,"（三）微型電動二輪車：指經型式審驗合格，以電力為主，最大行駛速率在每小時二十五公里以下，且車重不含電池在四十公斤以下或車重含電池在六十公斤以下之二輪車輛。"],[2,"二、其他慢車："],[3,"（一）人力行駛車輛：指客、貨車、手拉（推）貨車等。包含以人力為主、電力為輔，最大行駛速率在每小時二十五公里以下，且行駛於指定路段之慢車。"],[3,"（二）獸力行駛車輛：指牛車、馬車等。"],[3,"（三）個人行動器具：指設計承載一人，以電力為主，最大行駛速率在每小時二十五公里以下之自平衡或立式器具。"]]},{"no":"7","label":"第 7 條","lines":[[0,"車輛所有人、駕駛人、行人或其他使用道路之行為人，違反本規則之規定者，依道路交通管理處罰條例之規定處罰；道路交通管理處罰條例未規定者，依社會秩序維護法、公路法、市區道路條例及其他有關法律之規定處罰。"]]}]},{"title":"第 二 章 汽車牌照","articles":[{"no":"8","label":"第 8 條","lines":[[0,"汽車牌照包括號牌、行車執照及拖車使用證，為行車之許可憑證，由汽車所有人向公路監理機關申請登記，依本條例第九條之一規定繳清其違反道路交通管理處罰條例第二章、第三章尚未結案之罰鍰及未繳納之公路使用養護安全管理費並檢驗合格後發給之。但拖車號牌及拖車使用證得由使用人申請之。"]]},{"no":"9","label":"第 9 條","lines":[[0,"汽車號牌之型式、顏色及編號，按其種類由交通部定之。"],[0,"前項汽車號牌之型式、顏色及編號變更時，公路監理機關應通知汽車所有人限期換領新型號牌，逾期未換領又未申請延期者，其牌照不得使用，經再通知逾期仍不換領號牌，其牌照應予註銷。"]]},{"no":"10","label":"第 10 條","lines":[[0,"汽車牌照不得偽造、變造或矇領，並不得借供他車使用或使用他車牌照行駛。"]]},{"no":"11","label":"第 11 條","lines":[[0,"汽車號牌懸掛位置，除原設有固定位置外，應依下列規定懸掛固定："],[2,"一、汽車號牌每車兩面，應正面懸掛於車輛前後端之明顯適當位置。"],[2,"二、曳引車號牌每車二面，應正面懸掛於車輛前後端之明顯適當位置。"],[2,"三、機車及拖車號牌每車一面，應正面懸掛於車輛後端之明顯適當位置。但汽缸總排氣量五百五十立方公分以上或電動機車之馬達及控制器最大輸出馬力五十四馬力（HP）以上之大型重型機車號牌每車二面，應正面懸掛於車輛前後端之明顯適當位置；其前方號牌並得以直式或橫式之懸掛或黏貼方式為之。"],[2,"四、汽車及曳引車臨時號牌每車二面，應黏貼於車輛前後端之適當位置，機車及拖車臨時號牌每車一面，應黏貼於車輛後端之明顯適當位置。"],[2,"五、汽車及曳引車試車號牌每車二面，應懸掛於車輛前後端明顯適當位置，機車及拖車試車號牌每車一面，應懸掛於車輛後端之明顯適當位置。"],[0,"汽車號牌不得變造損毀、塗抹或黏貼其他材料、加裝邊框或霓虹燈、裝置旋轉架、顛倒懸掛或以安裝其他器具之方式使不能辨認其牌號，並不得以他物遮蔽，如有污穢，致不能辨認其牌號時，應洗刷清楚。但因應電子收費需要加裝邊框而未遮蔽號牌字號與圖案標示者，不在此限。"],[0,"汽車號牌有裁剪或扭曲懸掛者，以損毀號牌論。"]]},{"no":"12","label":"第 12 條","lines":[[0,"汽車行車執照、拖車使用證應隨車攜帶，以備查驗。"]]},{"no":"13","label":"第 13 條","lines":[[0,"汽車號牌之一面或二面如遺失或損壞時，汽車所有人應向公路監理機關，重新申領牌照。但汽車號牌遺失者，應檢附警察機關車牌遺失證明單。"],[0,"汽車行車執照或拖車使用證如遺失或損壞時，應由汽車所有人或拖車使用人申請補發或換發。"]]},{"no":"14","label":"第 14 條","lines":[[0,"汽車行車執照、拖車使用證每三年換發一次，機車行車執照每二年換發一次，自原發照之日起算，期滿前後一個月內，須申請換領新照始得行駛。但自中華民國一百零二年一月一日起，下列車輛之證照免申請換發："],[2,"一、校車、幼童專用車及救護車以外之自用汽車行車執照。"],[2,"二、機車行車執照。"],[2,"三、自用拖車使用證。"],[0,"前項免申請換發證照之車輛，其已領有之證照有效期間屆滿後，仍屬有效，並得免換發之。"]]},{"no":"15","label":"第 15 條","lines":[[0,"汽車新領牌照應申請登記。"],[0,"汽車有下列情事之一者，應申請異動登記："],[2,"一、過戶。"],[2,"二、變更。"],[2,"三、停駛。"],[2,"四、復駛。"],[2,"五、報廢。"],[2,"六、繳銷牌照。"],[2,"七、註銷牌照。"],[0,"汽車辦理第一項、前項第一款及第四款登記時，得申請汽車主要駕駛人登記。"]]},{"no":"16","label":"第 16 條","lines":[[0,"汽車所有人依前條規定申請者，應填具申請書，並依下列規定提出證明文件："],[2,"一、以個人名義申請登記者，應繳驗國民身分證或軍人身分證或僑民居留證明。如繳驗證件不能清楚辨認者，並應繳驗有效之駕駛執照或全民健康保險卡或護照等第二身分證明文件。"],[2,"二、以機關、學校或團體名義申請登記者，除應有該機關、學校或團體正式證明文件外，並應提具財稅機關編配之統一編號。如其證明文件為影本者，應另繳驗統一編號編配通知書影本。"],[2,"三、以公司、行號名義申請登記者，應繳驗公司、行號主管機關核准登記之公文（公司含登記表）或公司、行號主管機關核發之登記證明書，並應提具財稅機關編配之統一編號，如係以公司、行號之聯絡處、辦事處或通信處名義登記者，除應憑總公司、行號之證明外，亦應提具總公司、行號之財稅機關編配之統一編號。但其繳驗之證明文件為影本者，另繳驗該公司、行號最近一期繳納營業稅證明文件影本。"],[2,"四、以執行業務者名義申請登記者，應繳驗該執行業務者負責人身分證影本及執業證明文件或所屬公會出具之證明，並提具統一編號編配通知書影本。"],[2,"五、個人經營計程車客運業及計程車運輸合作社社員，應繳驗國民身分證、有效計程車駕駛人執業登記證及該管公路主管機關核發之同意文件。"],[2,"六、申請汽車主要駕駛人登記，應繳驗主要駕駛人符合登記車種之有效駕駛執照正本。"],[0,"前項第一款至第四款，原汽車所有人委託汽車買賣業代辦過戶者，得憑各該款規定之證明文件影本及委託汽車買賣業代辦過戶之委託書或當地汽車商業同業公會開具之證明書申請登記，並另繳驗汽車買賣業之商業登記證明文件、汽車商業同業公會會員證及代辦人身分證，始得辦理。以當地汽車商業同業公會開具之證明書申請登記者，其商業登記證明文件得以影本審驗。"],[0,"前項委託汽車買賣業代辦過戶，如係辦理機車過戶者，其證明書並得由當地機車修理業職業工會開具。但其繳驗之工會會員證與商業登記證明文件上之負責人應屬同一人。"],[0,"前二項之汽車買賣業，應依法辦妥公司或行號登記，並經當地公路監理機關登記列管，且無偽造、變造證件或虛偽不實之情事者，方得辦理受託代辦過戶業務。"],[0,"汽車所有人委託汽車買賣業以外之他人代辦汽車過戶者，除繳驗第一項第一款規定之證明文件外，應另繳驗代辦人身分證與汽車所有人有效之駕駛執照或全民健康保險卡或護照等證明文件。但汽車所有人有效之駕駛執照或全民健康保險卡或護照等證明文件得以經法院或民間公證人認證文件代替之。"],[0,"從事汽車運輸業者，不得領用與其經營性質相同種類之自用車牌照。但因行政或修護需要者，公路監理機關得以其營業車輛每五十輛發給一付之比例，發給自用小型車牌照一付，十輛以上未滿五十輛者以一付計。"],[0,"自用大客車、自用大貨車、自用大客貨兩用車、自用小貨車或幼童專用車牌照，不得以個人名義申請登記。但有下列情形之一，經公路監理機關依附件一及附件一之一審核核准者，不在此限："],[2,"一、以直接從事生產，需裝載本身所需或生產之物品時，得申請領用自用大貨車、自用小貨車牌照。"],[2,"二、從事休閒遊憩露營活動得申請領用自用小貨車牌照，並以一付為限。"],[0,"申領身心障礙者專用車輛牌照，以個人名義領照使用之自用小客車、自用小客貨兩用車及自用小貨車為限，其審核規定如附件一之二。"],[0,"申領車廂為部分或全部無車頂之大客車牌照，以經主管機關核准行駛路線，並專供市區汽車客運業作為公共汽車使用之車輛為限。"]],"attachment":true},{"no":"16-1","label":"第 16-1 條","lines":[[0,"以個人名義申請機車新領牌照登記，如係委託機車商業同業公會會員代辦，得憑車主國民身分證影本及當地機車商業同業公會開具之證明書申請登記，並另繳驗代辦業者之商業登記證明文件、機車商業同業公會會員證及代辦人身分證正本，始得辦理。以當地機車商業同業公會開具之證明書申請者，其商業登記證明文件得以影本審驗。"]]},{"no":"17","label":"第 17 條","lines":[[0,"汽車所有人申請新領牌照登記應依下列規定繳驗車輛來歷憑證，經檢驗合格後發給牌照："],[2,"一、國內製造之車輛，應繳驗車輛出廠與貨物稅完（免）稅照證及統一發票。"],[2,"二、國內製造之車身，應繳驗車身出廠與貨物稅完（免）稅照證及車身之統一發票。"],[2,"三、進口之車輛："],[3,"（一）向貿易商或經銷商購買新車者，應繳驗海關進口與貨物稅完（免）稅證明書、出廠證明、貿易商或經銷商開立之統一發票。"],[3,"（二）購買免稅進口轉售車輛者，應繳驗海關進口與貨物稅完（免）稅證明書、補繳貨物稅之完稅照或免稅證明及讓渡書。"],[3,"（三）公司、行號、法人團體或個人輸入自行使用之車輛，應繳驗海關進口與貨物稅完（免）稅證明書及出廠證明。"],[2,"四、機關、學校、團體標售或拍賣者，應繳驗該機關、學校或團體正式證明文件，其原屬免稅車輛者，並應繳驗補繳貨物稅之完稅照。"],[2,"五、軍用車輛換領普通牌照者，應有軍車管理機關證明文件及補繳貨物稅之完稅照或免稅證明。"],[0,"國產及進口之車輛均應符合交通部規定之安全檢驗標準，並應經車輛型式安全檢測及審驗合格，取得安全審驗合格證明書，始得辦理登記、檢驗、領照。"],[0,"公路監理機關辦理車輛發照時，除應查驗前項車輛規格審查或審驗合格文件外，並應依相關規定登記檢驗合格後，始予發照。"]]},{"no":"17-1","label":"第 17-1 條","lines":[[0,"機車、小客車、小客貨兩用車及小貨車所有人申請新領牌照登記，應繳交車輛製造廠、代理商或進口商出具，經內政部認可，施加於車輛特定零組件之防竊辨識碼完工證明文件，始得辦理新登檢領照。"],[0,"前項實施日期、特定零組件項目、實施車種、防竊辨識碼技術及完工證明文件之申請與核發作業規定，由內政部訂定公告之。"]]},{"no":"18","label":"第 18 條","lines":[[0,"汽車在未領有正式牌照前，如有下列情形之一者，應申領臨時牌照："],[2,"一、駛往海關驗關繳稅。"],[2,"二、駛往公路監理機關接受新領牌照前檢驗。"],[2,"三、買賣試車時。"],[2,"四、因出售或進口由甲地駛往乙地時。"],[2,"五、准許過境之外國汽車。"]]},{"no":"19","label":"第 19 條","lines":[[0,"汽車臨時牌照使用期限，依下列規定："],[2,"一、依前條第一款至第三款申領者，均不得超過五日。但有正當理由申請再領者，各以一次為限。"],[2,"二、依前條第四款申領者，得視行程需要核定。但在同一省市不得超過十五日。"],[2,"三、准許過境之外國汽車，應由入境之公路監理機關核發臨時牌照，最多不得超過三個月，並於出境時繳回。"],[0,"臨時牌照使用期限屆滿後，應即將該牌照向公路監理機關繳銷之。"],[0,"領用臨時牌照之車輛，不得載運客貨收費營業。"]]},{"no":"20","label":"第 20 條","lines":[[0,"汽車買賣業、汽車製造業或汽車研究機構，因業務需要試行汽車時，得依附件二十四向公路監理機關申領試車牌照憑用，並應遵守下列規定："],[2,"一、不得載運客貨收費營業。"],[2,"二、應在指定路線或區域內行駛。"],[2,"三、按季或按年領用，期滿仍需續用時，應於期滿十日內向原發照機關換領新照。"],[2,"四、請領試車牌照時，應按規定費率繳納押牌費、租牌費。"],[2,"五、試車牌照領用期滿或不予繼續使用時，應將所領牌照繳還原發照機關。"],[2,"六、試車牌照應懸掛於指定車種類別。"],[0,"前項試車牌照屬於機車使用者，限由機車製造業及研究機構申領，並須遵守前項各款規定。"],[0,"依法領有公司、商業或工廠登記證明文件之業者或汽車研究機構，因研究、測試業務而有試行有條件自動化、高度自動化及完全自動化駕駛車輛需要，得依附件二十一規定申領試車牌照及行駛，且行駛時應有適當管制措施，並遵守相關道路交通安全之規定。"]],"attachment":true},{"no":"21","label":"第 21 條","lines":[[0,"汽車所有人具有同一型式之汽車在五輛以上或汽車修理廠備置新品引擎者，得向公路監理機關申領預備引擎使用證。"],[0,"預備引擎限換用於同一型式之汽車，換用時免辦變更登記手續。但須將預備引擎使用證連同行車執照隨車攜帶。"],[0,"汽車預備引擎應經公路監理機關檢驗合格登記後，發給使用證。"],[0,"汽車預備引擎使用證有效期限一年，期滿後如換領新證時，仍應依照前項規定檢驗。"]]},{"no":"22","label":"第 22 條","lines":[[0,"汽車過戶登記應由讓與人與受讓人共同填具汽車過戶登記書，向公路監理機關申請，並應繳驗下列證件。"],[2,"一、原領之汽車新領牌照登記書車主聯。"],[2,"二、行車執照。"],[0,"公路監理機關於審核各項應備證件相符後，即予辦理過戶登記，換發新行車執照。"]]},{"no":"23","label":"第 23 條","lines":[[0,"汽車車身式樣、輪胎隻數或尺寸、燃料種類、座位、噸位、引擎、車架、車身、頭燈等設備或使用性質、顏色、汽車所有人名稱、汽車主要駕駛人、地址等如有變更，均應向公路監理機關辦理登記。"],[0,"前項變更登記，除汽車所有人名稱、汽車主要駕駛人、地址等變更時，免予檢驗外，餘均須檢驗合格。"],[0,"引擎或車架變更，以型式及燃料種類相同者為限。"],[0,"第一項汽車設備規格之變更應符合附件十五之規定。"]],"attachment":true},{"no":"23-1","label":"第 23-1 條","lines":[[0,"汽車下列設備規格不得變更："],[2,"一、底盤設備："],[3,"（一）方向盤位置。"],[3,"（二）傳動系統設備：指汽車之排檔型式、驅動方式、變速箱及齒輪箱。"],[3,"（三）煞車作用設備：指煞車作用種類（總泵、分泵及油管）及防滑煞車系統。"],[3,"（四）懸吊系統：指支臂、三角架與連桿機構。"],[3,"（五）軸距規格。"],[2,"二、引擎設備：指引擎之機械或渦輪增壓系統、氮氣導入裝置設備。"],[2,"三、車身設備："],[3,"（一）車身外附加燈飾。"],[3,"（二）車燈噴色或貼膠紙。但黏貼電子收費裝置後符合規定者，不在此限。"],[2,"四、其他經主管機關核定之項目。"],[0,"機車下列設備規格不得變更："],[2,"一、引擎設備：指引擎之機械或渦輪增壓系統、氮氣導入裝置設備。"],[2,"二、車身設備：車燈噴色或貼膠紙。"],[2,"三、排氣管數量或其左右側安裝位置。"],[2,"四、其他經主管機關核定之項目。"]]},{"no":"24","label":"第 24 條","lines":[[0,"汽車變更登記，應由汽車所有人填具異動登記書，檢同行車執照及原領之汽車新領牌照登記書車主聯，向公路監理機關申請，如變更引擎或車身者，並應繳驗來歷證件。"],[0,"依第二十三條辦理汽車設備規格變更者，另應依附件十五規定繳驗相關證明文件。"],[0,"使用中車輛經依規定取得車輛安全審驗合格報告者，得向公路監理機關辦理使用液化石油氣為燃料（含單、雙燃料）、設置輪椅區或迴轉式座椅、車輛後懸部分大樑、附掛拖車、軸組荷重及總重量或總聯結重量變更登記檢驗。"],[0,"中華民國九十五年十月一日至一百零九年六月三十日新登檢領照之小貨車得另辦理載重變更登記檢驗。"],[0,"前二項作業規定由交通部定之。"],[0,"公路監理機關於審核各項應備證件相符後，即予辦理變更登記，並換發新行車執照，變更記錄如與行車執照上所載項目無關者，免換行車執照。"]],"attachment":true},{"no":"24-1","label":"第 24-1 條","lines":[[0,"計程車得設置車頂廣告看板架。"],[0,"計程車設置車頂廣告看板架者，應檢具下列證明文件，向公路監理機關申請檢驗及變更登記："],[2,"一、經交通部認可之專業機構審驗合格之車頂廣告看板架型式審驗報告。"],[2,"二、行車執照。"],[2,"三、汽車新領牌照登記書。"],[2,"四、異動登記書二份。"],[0,"安裝車頂廣告看板架者應投保責任保險，並應於保險到期前辦理續保手續。"],[0,"前項保險以每一型式產品為一投保單位，每一投保單位之最低保險金額應包含下列各條件："],[2,"一、每一個人身體傷亡新臺幣一百五十萬元。"],[2,"二、每一意外事故傷亡新臺幣四百五十萬元。"],[2,"三、每一意外事故財產損失新臺幣五十萬元。"],[2,"四、設置車頂廣告看板架審驗作業規定如附件十四。"]],"attachment":true},{"no":"25","label":"第 25 條","lines":[[0,"汽車因故停駛或依法令規定責令停駛時，應填具異動登記書向公路監理機關辦理停駛登記，並將號牌及行車執照繳存。"]]},{"no":"26","label":"第 26 條","lines":[[0,"汽車因故停駛期限最多不得超過一年，逾期即將牌照註銷。"],[0,"超過停駛期限註銷牌照之車輛，如須復駛時，應依規定向公路監理機關重新申領牌照。"]]},{"no":"27","label":"第 27 條","lines":[[0,"停駛車輛復駛時應填具異動登記書向原登記停駛之公路監理機關申請認可並予登記後，發還牌照。"]]},{"no":"28","label":"第 28 條","lines":[[0,"汽車因機件損壞停駛或停駛期間在三個月以上者，於復駛時，應經檢驗合格後，始得將牌照發還。"]]},{"no":"29","label":"第 29 條","lines":[[0,"汽車引擎、底盤、電系、車門損壞應即停駛修護，其不堪修護使用時，應申請報廢。"],[0,"公路監理機關實施定期檢驗或臨時檢驗發現汽車有前項情事經覆驗不合格時，應責令報廢。"]]},{"no":"30","label":"第 30 條","lines":[[0,"汽車報廢，應填具異動登記書，向公路監理機關辦理報廢登記，並同時將牌照繳還。"],[0,"廢棄車輛經由警察、環保機關（構）處理者，行政院環境保護署認可之環保機構應通知公路監理機關逕予以報廢登記；其通知作業規定，由交通部會商行政院環境保護署、內政部另定之。"],[0,"出廠已逾一定年限以上之汽車，經公路監理機關通知汽車所有人確認切結報廢者，由公路監理機關逕予報廢登記。"],[0,"報廢之汽車，不得再行申請登記檢驗領照使用。"]]},{"no":"31","label":"第 31 條","lines":[[0,"汽車因新領牌照、過戶或變更地址而非屬同一公路監理機關管轄者，應依照第十七條、第二十二條或第二十四條之規定向公路監理機關申請辦理，登記之公路監理機關於辦妥新領、過戶或變更登記後，除將新領牌照登記書、過戶登記書或異動登記書留存一聯備查外，應即將其車籍之電腦資料移轉管轄之公路監理機關列管。"]]},{"no":"32","label":"第 32 條","lines":[[0,"汽車牌照之登記主體已不存在及融資性租賃車輛租用人登記主體不存在或其領用資格喪失者，其繼承人、負責人、清算人、承受人或出租人應向公路監理機關申請異動登記。"],[0,"汽車牌照不需使用時，得向公路監理機關申請繳銷。"],[0,"汽車繳銷牌照後重行申領執照時，應繳驗已辦妥之異動登記書及原新領牌照登記書。"]]},{"no":"33","label":"第 33 條","lines":[[0,"前條第一項應申請異動登記之義務人未辦理異動登記者，公路監理機關得催告該義務人於十五日內辦理異動登記，逾期未辦理者，或繼承人未於被繼承人死亡後一年內辦理異動登記，或經有關機關（構）依法公告後仍無人認領之車輛，公路監理機關應逕行註銷該車輛牌照。"],[0,"前項繼承登記，義務人不能如期辦理者，得於期限屆滿前，以書面敘明理由申請延長六個月，並以一次為限。"],[0,"汽車牌照受註銷處分者，由公路監理機關逕予登記註銷，除第一項因未辦理繼承之異動登記之情形外，應以汽車牌照註銷處分書通知汽車所有人，並將資料提供警察機關及稅捐機關。"],[0,"汽車所有人於汽車失竊時，應檢附警察機關車輛失竊證明單並填具異動登記書，向管轄之公路監理機關申辦註銷牌照登記。"],[0,"經註銷牌照之汽車重行申領牌照時，應繳驗異動登記書或牌照註銷處分書及原領牌照登記書車主聯。如係失竊註銷牌照車輛，並應繳驗向司法或警察機關領回車輛之證明，註銷時原牌照未繳回者，並應同時追繳。"]]},{"no":"33-1","label":"第 33-1 條","lines":[[0,"計程車客運業之營業車輛，經動產擔保交易登記之附條件買賣出賣人或動產抵押權人取回，該出賣人或抵押權人應於十五日內將牌照繳回公路監理機關。"],[0,"出賣人或抵押權人未依前項規定繳回牌照者，經附條件買賣之買受人或動產抵押之債務人提出證明文件，公路監理機關得催告該出賣人或抵押權人於十五日內繳回牌照，逾期未繳回者，公路監理機關應逕行註銷該車輛牌照。"]]},{"no":"34","label":"第 34 條","lines":[[0,"汽車牌照登記書或過戶登記書如有遺失，應申請補發。"]]},{"no":"35","label":"第 35 條","lines":[[0,"汽車檢驗分為申請牌照檢驗、定期檢驗及臨時檢驗三種。"]]},{"no":"36","label":"第 36 條","lines":[[0,"汽車檢驗應按指定日期將車輛駛往公路監理機關檢驗場所或指定地點接受檢驗。"]]},{"no":"37","label":"第 37 條","lines":[[0,"汽車丈量量計方法，應依下列規定："],[2,"一、車長：自前保險桿至車尾最末端之長度。"],[2,"二、車寬：車身左右最大之寬度。"],[2,"三、車高：自地面至車身最高點之高度。"],[2,"四、輪距：左右輪胎中心線之距離，雙輪者以左右雙輪中心線之距離為準。"],[2,"五、軸距：前軸中心點與後軸中心點間之距離，多軸者，以前軸或前軸組中心點與最後軸中心點間之距離為準；半拖車以第五輪中心至最後軸中心點間之距離為準。"],[2,"六、最遠軸距：車輛最前軸中心點與最後軸中心點間之距離。"],[2,"七、後懸：最後軸中心點與車尾間之距離，但保險桿不計在內。"],[2,"八、段差：汽車車寬小於所附掛之拖車時，拖車單邊超出汽車部分之尺寸；其量度以兩車中心線為準。"]]},{"no":"38","label":"第 38 條","lines":[[0,"車輛尺度、軸重、總重、後懸及段差之限制應依下列規定："],[2,"一、尺度之限制："],[3,"（一）全長："],[301,"1.大客車不得超過十二點二公尺；雙節式大客車不得超過十八點七五公尺。"],[301,"2.大貨車不得超過十二公尺。"],[301,"3.全聯結車不得超過二十公尺。"],[301,"4.半聯結車不得超過十八公尺。"],[301,"5.小型車附掛之拖車不得超過七公尺。"],[301,"6.汽缸總排氣量五百五十立方公分以上或電動機車之馬達及控制器最大輸出馬力五十四馬力（HP）以上之機車不得超過四公尺；汽缸總排氣量未滿五百五十立方公分或電動機車之馬達及控制器最大輸出馬力未滿五十四馬力（HP）之機車不得超過二點五公尺。"],[3,"（二）全寬："],[301,"1.汽車全寬不得超過二點五公尺，其後輪胎外緣與車身內緣之距離，大型車不得超過十五公分，小型車不得超過十公分。"],[301,"2.機車除身心障礙者用特製車外："],[252,"（1）大型重型二輪、普通重型及普通輕型機車不得超過一點三公尺。"],[252,"（2）小型輕型機車不得超過一公尺。"],[252,"（3）大型重型三輪機車不得超過二公尺。"],[3,"（三）全高："],[301,"1.雙層公車不得超過四點四公尺。但上層車廂為全部無車頂者，或經公路主管機關核准可使用行駛高速公路及快速公路路線者，不得超過四公尺。"],[301,"2.自中華民國八十七年十二月一日起經車輛型式安全審驗之前單軸後單軸大客車不得超過三點六公尺。但自中華民國八十八年七月一日起，新登檢領照之前單軸後單軸大客車均不得超過三點六公尺。自中華民國九十六年七月一日起經車輛型式安全審驗之新型式大客車不得超過三點五公尺。但自中華民國九十七年一月一日起，新登檢領照之大客車均不得超過三點五公尺。"],[301,"3.具有混凝土輸送設備專供混凝土壓送作業之特種大貨車不得超過四公尺。"],[301,"4.其餘各類大型車不得超過三點八公尺。"],[301,"5.小型車不得超過全寬之一點五倍，其最高不得超過二點八五公尺。"],[301,"6.機車不得超過二公尺。"],[2,"二、軸組荷重之限制："],[3,"（一）單軸：軸荷重每組不得超過十公噸。"],[3,"（二）雙軸：軸荷重每組不得超過十四點五公噸。"],[3,"（三）經車輛型式安全審驗之車輛軸組荷重限制如下："],[301,"1.單軸：軸荷重每軸不得超過十公噸；驅動軸軸荷重每軸不得超過十一點五公噸。"],[301,"2.雙軸軸組：軸組荷重每組不得超過十七點五公噸。"],[301,"3.參軸軸組：軸組荷重每組不得超過二十二公噸。"],[2,"三、總重或總聯結重量之限制："],[3,"（一）前後均為單軸車輛總重量不得超過十五公噸。"],[3,"（二）前單軸後雙軸車輛總重量不得超過二十一公噸。"],[3,"（三）前雙軸後單軸車輛總重量不得超過二十公噸。"],[3,"（四）全聯結車：總聯結重量不得超過四十二公噸。"],[3,"（五）半聯結車：總聯結重量不得超過三十五公噸。"],[3,"（六）經車輛型式安全審驗之汽車，應符合附件十一之規定。但雙節式大客車總重量不得超過二十八公噸。"],[2,"四、後懸："],[3,"（一）客車不得超過軸距百分之六十。"],[3,"（二）貨車及客貨兩用車不得超過軸距百分之五十。"],[3,"（三）具有特種裝置之特種車不得超過軸距百分之六十六點六。但承載客貨部分不得超過軸距百分之五十。"],[2,"五、段差：小型車及其所附掛之拖車，段差不得超過十五公分。"],[0,"經內政部核定之消防車得使用前雙軸後雙軸式，且不受前項之限制。但仍應依下列規定："],[2,"一、尺度之限制："],[3,"（一）全長不得超過十五公尺。"],[3,"（二）全寬不得超過二點六公尺。"],[3,"（三）全高不得超過四點二公尺。"],[2,"二、軸組荷重之限制："],[3,"（一）單軸：軸荷重每組不得超過十二公噸。"],[3,"（二）雙軸軸組：軸荷重每組不得超過二十公噸。"],[3,"（三）3-4參軸軸組：軸組荷重每組不得超過二十二公噸。"],[2,"三、總重不得超過四十公噸。"],[2,"四、後懸不得超過軸距百分之六十六點六。但承載客貨部分不得超過軸距百分之五十。"]],"attachment":true},{"no":"39","label":"第 39 條","lines":[[0,"汽車申請牌照檢驗之項目及基準，依下列規定："],[2,"一、引擎或車身（架）號碼及拖車標識牌應與來歷憑證相符。除小型車附掛之拖車外，拖車標識牌及車身（架）號碼打刻應符合附件十七之規定。"],[2,"二、消音器作用正常，排氣管完好。"],[2,"三、方向盤應在左側。"],[2,"四、腳煞車、手煞車效能、平衡度合於規定。"],[2,"五、著地輪應為四輪以上，最前軸著地應為二輪。前輪側滑度合於規定。"],[2,"六、各種喇叭應合於規定且不得裝設可發出不同音調之喇叭。"],[2,"七、各種燈光應符合附件七規定。"],[2,"八、車輛尺度、顏色、車身式樣與紀錄相符，車身標識合於第四十二條之規定。"],[2,"九、車窗、擋風玻璃未黏貼不透明反光紙，計程車車窗玻璃除依規定標識車號外，並不得黏貼不透明之色紙或隔熱紙。自中華民國一百十五年二月二十八日起新登檢領照之車輛有黏貼隔熱紙者，除經交通部核可之車輛外，應依下列規定："],[3,"（一）前擋風玻璃應黏貼可見光透過率百分之七十以上之合格隔熱紙。但前擋風玻璃自邊框上緣起十五公分內之區域，不在此限。"],[3,"（二）前側窗應黏貼可見光透過率百分之四十以上之合格隔熱紙。"],[3,"（三）計程車及幼童專用車除應符合前二目規定外，後側窗及後（擋）窗均應黏貼可見光透過率百分之四十以上之合格隔熱紙。"],[3,"（四）前三目所稱合格隔熱紙係指符合附件二十五規定並有合格標識者。"],[2,"十、雨刮、照後鏡完備，平頭大型車有前照鏡。"],[3,"十一、座位符合第四十一條規定。各類車前排、貨車及小客車全部座位應裝置安全帶。自中華民國九十六年七月一日起經車輛型式安全審驗之新型式大客車及自中華民國九十七年一月一日起新登檢領照之大客車全部座位應裝置安全帶。"],[3,"十二、大客車、大貨車、曳引車、小型車附掛之廂式拖車、露營車及幼童專用車應備有合於規定之滅火器，其規定如附件五，使用之滅火器應為內政部登錄機構認可之車用滅火器，且大客車應於車輛後半段乘客取用方便之處，另設一具車用滅火器。雙節式大客車各節車廂及雙層公車各層車廂，應依前述規定分別設有對應數量之車用滅火器。"],[3,"十三、計程車執業登記證插座完好，位置合於規定。"],[3,"十四、曳引車、經核可附掛拖車之小型車及拖車除依照一般汽車檢驗規定外，其聯結設備應完善；拖車煞車效能平衡度合於規定；煞車燈、方向燈、號牌燈、車寬燈、倒車燈、尾燈、危險警告燈及反光標識良好，位置合於規定。"],[3,"十五、大貨車及拖車左右兩側之防止捲入裝置與後方之安全防護裝置（或保險槓）合於規定。自中華民國一百零九年九月四日起，新登檢領照總重量逾三千五百公斤至五千公斤且全長六公尺以下之小貨車，亦同。"],[3,"十六、車高三點五公尺以上之汽車傾斜穩定度合於規定。自中華民國九十六年七月一日起經車輛型式安全審驗車高三點四公尺以上之新型式大客車及自中華民國九十七年一月一日起新登檢領照車高三點四公尺以上之大客車，亦同。"],[3,"十七、車輛之車身變更打造全高為三點四公尺以上大客車或三點五公尺以上其他車輛或特種車者，應檢附汽車底盤製造廠之符合安全書面證明文件，特種設備應符合規定，並取得合法車身打造工廠之施工證明。"],[3,"十八、隨車有車輛故障標誌及自中華民國一百十二年七月一日起應有符合中華民國國家標準CNS15909高可見度服裝—試驗法及要求第二級以上或其他等同標準之反光服裝（背心）。"],[3,"十九、使用燃料為液化石油氣者，其各項裝備應符合附件十之規定；使用燃料為壓縮天然氣者，其各項裝備應符合附件十三之規定。"],[3,"二十、裝載砂石、土方之傾卸式大貨車、傾卸式半拖車及其貨廂應符合附件二十二規定。"],[4,"二十一、大客車尺度除全長、全寬、全高應符合前條規定外，其車身各部規格應符合附件六之規定；自中華民國九十三年七月一日起大客車其車身各部規格應符合附件六之一規定；雙節式大客車應符合附件六之三規定；雙層公車應符合附件六之四規定。"],[4,"二十二、使用自動排檔之小客車及小客貨兩用車，自中華民國八十八年一月一日起，國內產製者以出廠日為準，進口者以裝船日為準，應裝設未踩煞車踏板無法由停車檔排出檔位之自動排檔鎖定裝置。"],[4,"二十三、小型車附掛之拖車前後端尖角、側面突出物應合乎規定。"],[4,"二十四、總聯結重量及總重量在二十公噸以上之新登檢領照汽車，應裝設具有連續記錄汽車瞬間行駛速率及行車時間功能之行車紀錄器（以下簡稱行車紀錄器）。自中華民國九十年一月一日起新登檢領照之八公噸以上未滿二十公噸汽車、自中華民國九十六年七月一日起經車輛型式安全審驗及自中華民國九十七年一月一日起新登檢領照之八公噸以下營業大客車，亦同。並應檢附行車紀錄器經審驗合格之證明。"],[4,"二十五、應查驗罐槽車之罐槽體檢驗（查）合格之有效證明書。高壓罐槽車之罐槽體應依勞動部所定有關高壓容器檢查之法令辦理；常壓液態罐槽車之罐槽體應依常壓液態罐槽車罐槽體檢驗及管理辦法規定辦理。"],[4,"二十六、裝載砂石、土方之傾卸框式半拖車及裝載砂石、土方且總重量在二十公噸以上之傾卸框式大貨車，自中華民國九十年七月一日起新登檢領照，應裝設具有顯示車輛載重功能且合於規定之載重計。"],[4,"二十七、裝載砂石、土方之傾卸框式大貨車及半拖車，自中華民國九十年七月一日起新登檢領照，應裝設合於規定之轉彎及倒車警報裝置。自中華民國一百零七年一月一日起總聯結重量及總重量十二公噸以上大貨車、總聯結重量三點五公噸以上拖車及總重量五公噸以上大客車，亦同。"],[4,"二十八、幼童專用車及校車之車身左右兩側與後方車身標示之倒三角形黃色部分，自中華民國九十年七月一日起新登檢領照，應使用合於規定之反光識別材料。"],[4,"二十九、幼童專用車之車身各部規格，應符合附件十二之規定。"],[4,"三  十、自中華民國一百零三年一月一日起，各類車輛其所使用輪胎之胎面未磨損至中華民國國家標準CNS1431汽車用外胎（輪胎）標準或CNS4959卡客車用翻修輪胎標準所訂之任一胎面磨耗指示點。"],[4,"三十一、自中華民國一百零七年一月一日起新登檢領照之大客車與大貨車，應裝設合於規定之行車視野輔助系統。自中華民國一百零九年九月四日起，新登檢領照總重量逾三千五百公斤至五千公斤且全長六公尺以下之小貨車，亦同。"],[4,"三十二、自中華民國一百零八年一月一日起大客車電氣設備數量及位置應與安全審驗合格證明書紀錄相符。"]],"attachment":true},{"no":"39-1","label":"第 39-1 條","lines":[[0,"汽車定期檢驗之項目及基準，依下列規定："],[2,"一、引擎或車身（架）號碼及拖車標識牌與紀錄相符，號牌完好，並依規定懸掛。除小型車附掛之拖車外，拖車標識牌及車身（架）號碼打刻應符合附件十七之規定。"],[2,"二、消音器作用正常，排氣管完好。"],[2,"三、腳煞車、手煞車效能、平衡度合於規定。"],[2,"四、前輪側滑度合於規定。"],[2,"五、各種喇叭應合於規定且不得裝設可發出不同音調之喇叭。"],[2,"六、各種燈光完備，作用正常。依第二十三條規定辦理頭燈設備變更者，其燈光應符合附件十五之變更檢驗規定。"],[2,"七、車輛尺度、顏色、車身式樣與紀錄相符，車身標識完好合於第四十二條之規定，自中華民國九十四年一月一日起，大客車車重應與紀錄相符。"],[2,"八、車窗、擋風玻璃未黏貼不透明反光紙，計程車車窗玻璃除依規定標識車號外，並不得黏貼不透明之色紙或隔熱紙。自中華民國一百十五年二月二十八日起新登檢領照之車輛有黏貼隔熱紙者，除經交通部核可之車輛外，應依下列規定："],[3,"（一）前擋風玻璃應黏貼可見光透過率百分之七十以上之合格隔熱紙。但前擋風玻璃自邊框上緣起十五公分內之區域，不在此限。"],[3,"（二）前側窗應黏貼可見光透過率百分之四十以上之合格隔熱紙。"],[3,"（三）計程車及幼童專用車除應符合前二目規定外，後側窗及後（擋）窗均應黏貼可見光透過率百分之四十以上之合格隔熱紙。"],[3,"（四）前三目所稱合格隔熱紙係指符合附件二十五規定並有合格標識者。"],[2,"九、雨刮、照後鏡完備，平頭大型車有前照鏡。"],[2,"十、座位數應與行車執照登載核定數相符。中華民國八十年七月一日以後新登記領照之各類車前排、貨車及小客車全部座位安全帶完備。自中華民國九十六年二月一日起營業大客車全部座位應裝置安全帶。但中華民國九十六年十二月三十一日前登檢領照且不行駛高速公路、快速公路、快速道路或標高五百公尺以上山區道路之市區公車及一般公路客運車輛，除前排座位外，得免裝設。"],[3,"十一、大客車、大貨車、曳引車、小型車附掛之廂式拖車、露營車及幼童專用車應備有合於規定之滅火器，其規定如附件五，使用之滅火器應為內政部登錄機構認可之車用滅火器，且大客車應於車輛後半段乘客取用方便之處，另設一具車用滅火器。雙節式大客車各節車廂及雙層公車各層車廂，應依前述規定分別設有對應數量之車用滅火器。"],[3,"十二、計程車執業登記證插座完好，位置合於規定；應依規定裝設計費表者，其正面黏貼有效期限內之輪行檢定合格單。"],[3,"十三、曳引車、經核可附掛拖車之小型車及拖車除依照一般汽車檢驗規定外，其聯結設備應完善；拖車煞車效能平衡度合於規定；煞車燈、方向燈、號牌燈、車寬燈、倒車燈、尾燈、危險警告燈及反光標識良好，位置合於規定。"],[3,"十四、大貨車及拖車左右兩側之防止捲入裝置與後方之安全防護裝置（或保險槓）合於規定。自中華民國一百零九年九月四日起，新登檢領照總重量逾三千五百公斤至五千公斤且全長六公尺以下之小貨車，亦同。"],[3,"十五、使用燃料為液化石油氣者，應檢附一個月內經合格工廠檢測合格之紀錄表。使用燃料為壓縮天然氣者，應檢附一個月內經車輛專業技術研究機構依附件十三壓縮天然氣汽車燃料系統定期檢驗規定檢驗之壓縮天然氣燃料系統定期檢驗合格紀錄表。"],[3,"十六、裝載砂石、土方之傾卸式大貨車、傾卸式半拖車及其貨廂應符合附件二十二規定。"],[3,"十七、大客車尺度除全長、全寬、全高應符合第三十八條規定外，中華民國九十三年六月三十日以前新登記領照之大客車，其車身各部規格應符合附件六之二規定；中華民國九十三年七月一日以後新登記領照之大客車，其車身各部規格應符合附件六之一規定；雙節式大客車應符合附件六之三規定；雙層公車應符合附件六之四規定。"],[3,"十八、總聯結重量及總重量在二十公噸以上之新登檢領照汽車，自中華民國八十八年九月二十三日本規則修正發布施行日起，應裝設行車紀錄器；其為八公噸以上未滿二十公噸之新登檢領照汽車，自中華民國九十年一月一日起，亦同。自中華民國九十六年二月一日起營業大客車應裝設行車紀錄器。並應檢附行車紀錄器經定期檢測合格之證明。"],[3,"十九、應查驗罐槽車之罐槽體檢驗（查）合格之有效證明書。"],[3,"二十、裝載砂石、土方之傾卸框式半拖車及裝載砂石、土方且總重量在二十公噸以上之傾卸框式大貨車，應依規定裝設載重計，其實施日期由交通部另定之。"],[4,"二十一、裝載砂石、土方之傾卸框式大貨車及半拖車，自中華民國九十一年一月一日起，應裝設合於規定之轉彎及倒車警報裝置。總聯結重量及總重量十二公噸以上大貨車、總聯結重量三點五公噸以上拖車及總重量五公噸以上大客車，自中華民國一百零九年一月一日起，亦同。"],[4,"二十二、幼童專用車及校車之車身左右兩側與後方車身標示之倒三角形黃色部分，自中華民國九十一年一月一日起，應使用合於規定之反光識別材料。"],[4,"二十三、幼童專用車之車身各部規格，應符合附件十二之規定。"],[4,"二十四、營業大客車應檢附依法領有公司、商業或工廠登記證明文件之合法汽車修理業者出具四個月內保養紀錄表（卡），其保養檢查項目如附件十六。"],[4,"二十五、自中華民國一百零三年一月一日起，各類車輛其所使用輪胎之胎面未磨損至中華民國國家標準CNS1431汽車用外胎（輪胎）標準或CNS4959卡客車用翻修輪胎標準所訂之任一胎面磨耗指示點。"],[4,"二十六、中華民國一百零七年一月一日起，新登檢領照之大客車、大貨車及中華民國一百零九年九月四日起，新登檢領照總重量逾三千五百公斤至五千公斤且全長六公尺以下之小貨車，應裝設合於車輛安全檢測基準規定之行車視野輔助系統。中華民國一百零六年十二月三十一日以前新登檢領照之大客車、大貨車應裝設以下任一行車視野輔助系統："],[203,"（一）左右兩側視野鏡頭及可顯示車身兩側影像之車內螢幕。"],[203,"（二）於車輛右側裝設一個外部近側視鏡並於車輛右前側裝設雷達警示系統。"],[203,"（三）可顯示車輛四周影像之環景顯示系統。"],[4,"二十七、自中華民國一百零八年一月一日起，大客車電氣設備數量應與紀錄相符，初次登記或增加電氣設備時，應出具電氣設備經依法領有公司、商業或工廠登記證明文件之合法汽車（底盤）製造廠、汽車代理商、汽車車體（身）打造業或汽車修理業者出具之檢查紀錄。"]],"attachment":true},{"no":"39-2","label":"第 39-2 條","lines":[[0,"機車申請牌照檢驗項目及基準如下："],[2,"一、引擎或車身號碼與來歷憑證相符。"],[2,"二、前後煞車效能合於規定。"],[2,"三、前後輪左右偏差合於規定。"],[2,"四、各種喇叭合於規定且不得裝設可發出不同音調之喇叭。"],[2,"五、各種燈光與標誌應符合附件七規定。"],[2,"六、車輛型式、顏色與紀錄相符。"],[2,"七、左右兩側之照後鏡、擋泥板合於規定。"],[2,"八、各部機件齊全作用正常。"],[2,"九、不得加掛邊車。"],[2,"十、小型輕型機車車輛空重（含電池）應在七十公斤以下。"],[3,"十一、小型輕型機車之輪胎直徑應在三百公釐以上，四百二十公釐以下，輪胎寬度應在七十五公釐以上，一百公釐以下。"],[3,"十二、小型輕型機車之超速斷電功能應合於車速超過每小時四十五公里，電動機電源應能於三秒內自動暫停供電之規定。小型輕型機車之故障斷電功能應合於控制系統超速訊號輸入線短路或斷路，三秒內電動機電源應能自動斷電之規定。"],[3,"十三、車輛尺度應合於第三十八條規定。"],[3,"十四、輪胎之胎面未磨損至中華民國國家標準CNS4879機車用輪胎標準所定之任一胎面磨耗指示平臺。"],[0,"大型重型機車定期檢驗之項目及基準，依前項申請牌照檢驗規定辦理。"],[0,"古董車申請機車專用牌照檢驗或定期檢驗之項目及基準，依第一項申請牌照檢驗規定辦理。但車輛尺度、重量為原廠規格，或原廠設計無引擎或車身（架）號碼、照後鏡、輪胎、喇叭、擋泥板及各項燈光等設備，得免合於各該規定。"],[0,"駕艙機車申請牌照檢驗與定期檢驗項目及基準，依第一項申請牌照檢驗規定及下列規定辦理："],[2,"一、左右兩側之照後鏡、雨刮合於規定。"],[2,"二、車窗、擋風玻璃未黏貼不透明反光紙，有黏貼隔熱紙者，除經交通部核可之車輛外，應依下列規定："],[3,"（一）前擋風玻璃應黏貼可見光透過率百分之七十以上之合格隔熱紙。但前擋風玻璃自邊框上緣起十五公分內之區域，不在此限。"],[3,"（二）前側窗應黏貼可見光透過率百分之四十以上之合格隔熱紙。"],[3,"（三）前二目所稱合格隔熱紙係指符合附件二十五規定並有合格標識者。"],[2,"三、全部座位安全帶完備。"]],"attachment":true},{"no":"39-3","label":"第 39-3 條","lines":[[0,"汽車臨時檢驗之基準，依定期檢驗之規定；機車臨時檢驗之基準，依申請牌照檢驗之規定。"],[0,"汽車所有人除依規定接受車輛檢驗外，應依原廠規定時間自行實施保養及檢查。"],[0,"古董車申請機車之臨時檢驗，依前條第一項申請牌照檢驗規定辦理。但車輛尺度、重量為原廠規格，或原廠設計無引擎或車身（架）號碼、照後鏡、輪胎、喇叭、擋泥板及各項燈光等設備，得免合於各該規定。"]]},{"no":"39-4","label":"第 39-4 條","lines":[[0,"遊覽車客運業依汽車運輸業管理規則規定申請遊覽車車輛安全查驗者，應依第三十九條之一實施檢驗，並依下列規定完成查驗及繳交證明文件："],[2,"一、底盤安全檢修查驗，應由原底盤製造廠或其代理商或其指定汽車修理業者進行底盤全面安全檢修及繳驗交通部委託之車輛專業技術研究機構出具六個月內之審查證明書。"],[2,"二、車身重新打造查驗，應繳驗已取得大客車車身結構強度檢測基準審查報告之汽車車體（身）打造業者出具六個月內已重新打造車體之證明文件與統一發票。"]]},{"no":"39-5","label":"第 39-5 條","lines":[[0,"古董車申請汽車之專用牌照檢驗、定期檢驗或臨時檢驗之項目及基準，依下列規定："],[2,"一、申請專用牌照檢驗：引擎或車身（架）號碼應與來歷憑證相符。"],[2,"二、定期檢驗或臨時檢驗：引擎或車身（架）號碼與紀錄相符，號牌完好，並依規定懸掛。"],[2,"三、消音器作用正常，排氣管完好。"],[2,"四、方向盤應在左側。"],[2,"五、腳煞車、手煞車效能、平衡度合於規定。"],[2,"六、著地輪應為四輪，前軸著地應為二輪；前輪側滑度合於規定。"],[2,"七、各種喇叭應合於規定且不得裝設可發出不同音調之喇叭。"],[2,"八、頭燈：中華民國二十三年以後出廠之車輛應為二燈式以上且對稱裝設並具遠近燈切換設計，作動正常。"],[2,"九、尾燈：中華民國二十三年以後出廠之車輛應具備尾燈，中華民國四十八年以後出廠之車輛尾燈應為二燈式且對稱裝設。"],[2,"十、煞車燈：中華民國二十三年以後出廠之車輛應具備煞車燈，中華民國四十八年以後出廠之車輛煞車燈應為二燈式且對稱裝設。"],[3,"十一、方向燈：中華民國五十五年以後出廠之車輛應配有前後方向燈且作動正常。"],[3,"十二、車輛尺度、顏色、車身式樣與紀錄相符，車身標識合於第四十二條之規定。"],[3,"十三、應裝設車窗、擋風玻璃，未黏貼不透明反光紙。"],[3,"十四、雨刮：中華民國二十三年以後出廠之車輛應有雨刮開關設計，且作動正常。"],[3,"十五、照後鏡：中華民國六十四年以後出廠之車輛，至少需配備一個照後鏡於車輛左側。"],[3,"十六、安全帶：中華民國五十四年以後之車輛前排座位應配安全帶。如原廠未設有安全帶者，得變更裝設。"],[3,"十七、輪胎：中華民國二十一年以後之車輛應配置充氣式輪胎。另胎紋深度應符自中華民國一百零三年一月一日起，各類車輛其所使用輪胎之胎面未磨損至中華民國國家標準CNS1431汽車用外胎（輪胎）標準所訂之任一胎面磨耗指示點。"],[3,"十八、頭枕：中華民國六十一年以後之車輛應配置前座椅頭枕。"],[3,"十九、隨車應有車輛故障標誌。"],[0,"前項第一款、第七款至第十六款，除原廠設計即無配備者得免合於規定外，其餘均應完備且功能正常。"]]},{"no":"40","label":"第 40 條","lines":[[0,"汽車載重噸位之核定，應依下列規定："],[2,"一、車重  將空車過磅按實際重量登記。"],[2,"二、載重"],[3,"（一）原廠車輛說明書上未列載重量，僅列總重量者，應將總重量減去空車重量後核定載重量。"],[3,"（二）無總重量而僅有載重量說明書者，按載重量噸位核定。"],[3,"（三）有總重量及載重量者，按實際車身重量增減，使與總重量相符。"],[2,"三、總重  參照原廠說明書載明之總重量核定。但經交通部另行核定者，依其核定辦理。"]]},{"no":"41","label":"第 41 條","lines":[[0,"汽車座位立位之核定，應依下列規定："],[2,"一、小客車不得設立位，每一座位不得少於三十八公分寬、六十五公分深。但駕駛人座位之寬度不得少於六十公分。"],[2,"二、大客車每一座位不得少於四十公分寬、七十公分深；每一立位前後以二十五公分、左右以四十公分計算。但車內高度未達一百八十五公分、雙層公車之下層車內高度未達一百八十公分者或車廂為部分或全部無車頂之區域，不得設立位。"],[2,"三、幼童專用車不得設立位，其幼童座位應符合附件十二之規定。但駕駛人及幼童管理人之座位，應依第一款之規定為準。"],[2,"四、貨車駕駛室每一座位之寬度，不得少於三十八公分；駕駛人座位寬度不得少於六十公分，連駕駛人座位不得超過三個座位。但貨車駕駛室具前後二排座位且另有不同車身做為載貨空間使用者，小貨車連駕駛人座位不得超過七個座位，大貨車連駕駛人座位不得超過九個座位。"],[0,"前項第二款之大客車並應核定其總重量。"]],"attachment":true},{"no":"42","label":"第 42 條","lines":[[0,"車輛車身顏色及加漆標識，應依下列規定："],[2,"一、大客車、大貨車、小貨車、拖車、大型客貨兩用車及特種車，應於車廂兩邊顯明位置標示汽車所有人名稱，融資性租賃車輛應標示租用人名稱；其為平板式汽車或車廂兩邊無法標示者，得於兩邊車門。但以個人名義領照使用之車輛、車身兩邊無法標示之拖車及執行特殊任務有保密必要之公務車輛經所屬機關核可並敘明該車用途向車籍所在地公路監理機關申請於行車執照或牌照登記書上註記「免標示所有人名稱」者，得不須標示。"],[2,"二、大客車應於門旁標示牌照號碼及乘客人數，營業大客車應於車門旁標示出廠年份及依附件六之一標示大客車分類，並應於乘客人數下標示載重量及於車內駕駛座旁或上下車門顯明處標示駕駛人姓名、公司服務電話及該管公路主管機關申訴電話，車外尾部汽車牌照上方顯明處標示該管公路主管機關申訴電話；遊覽車於車內上下車門顯明處標示儲存有車輛設備規格及出廠年份等可聯結監理車輛資訊之數位化條碼或標識者，得免標示出廠年份。"],[2,"三、計程車應於兩側後門或後葉子板標示牌照號碼及公司行號、運輸合作社或個人名稱，後窗玻璃標示牌照號碼。但多元化計程車不在此限。計程車車身兩側及多元化計程車車身範圍（均不含車窗）於不影響辨識及視線安全下，得以平面漆繪或穩固黏貼方式張貼廣告，並應符合各目的事業主管機關及地方政府相關廣告物管理之法令規定辦理。申請設置輪椅區之計程車，另應依規定於車輛前、後、左及右方設有載運輪椅使用者車輛之識別標示。"],[2,"四、大貨車、小貨車及曳引車應於兩邊車門或顯著位置標示牌照號碼及總重量或總聯結重量。全拖車及拖架車身兩側顯明位置應標示總重量；半拖車車身兩側顯明位置應標示總聯結重量。大貨車、小貨車及拖車應於後方標示牌照號碼，其字體尺度、字樣及標示方式由交通部另定之。"],[2,"五、大型客貨兩用車應於兩邊車門或顯明位置標示牌照號碼、乘客人數及載重噸位。"],[2,"六、救護車漆白色並應於車身兩側標示紅十字。"],[2,"七、消防車漆大紅色。"],[2,"八、教練車車廂兩邊顯明位置標示駕訓班班名及斑馬紋，車身前後並應加掛標示有「教練車」之附牌或標示「教練車」之字樣。"],[2,"九、幼童專用車及專供載運學生之校車車身顏色及標識應符合相關目的事業主管機關之規定。"],[2,"十、汽車車身顏色不得與警用巡邏車相同。"],[3,"十一、新領牌照、汰舊換新及變更顏色之計程車，其車身顏色應使用台灣塗料工業同業公會塗料色卡編號一之十八號純黃顏色。"],[3,"十二、申請牌照與變更顏色之轎式、旅行式或廂式自用小客車及多元化計程車，車身顏色不得與前款計程車車身顏色相同。"],[3,"十三、汽車貨運業專辦搬家業務之車輛，車身顏色應使用純白顏色，並於車身兩側貨廂標示「專營搬家」字樣，字體不得小於二十五公分見方，且於擋風玻璃張貼「搬家貨運業執業證明」標識。"],[3,"十四、裝載砂石、土方之傾卸框式大貨車及半拖車，應於貨廂兩邊之前方標示貨廂內框尺寸，其字體尺度、字樣及標示方式由交通部另定之。"],[3,"十五、裝載砂石、土方之傾卸框式大貨車及半拖車，貨廂外框顏色應使用台灣塗料工業同業公會塗料色卡編號一之十九號黃顏色。其他傾卸框式大貨車及半拖車之貨廂外框顏色，不得使用該顏色。"],[3,"十六、使用燃料為壓縮天然氣者，應於車身前後汽車號牌附近顯明位置處標示「壓縮天然氣汽車」。"],[3,"十七、免徵使用牌照稅特種車之車身顏色及標識，應符合各該中央目的事業主管機關規定。"],[0,"計程車應於儀錶板上右側與右前座椅背設置執業登記證插座，並於右前座椅背標示牌照號碼；未經核定之標識及裝置不得設置。"],[0,"第一項各款標識材質應為防水漆料或粘貼牢固之材料，其顏色應依規定或為其標示處底色之明顯對比色，且應以正楷字體標明。字體尺度除另有規定者外，應依下列規定："],[2,"一、標示於車廂兩邊之汽車所有人，大型車每字至少二十五公分見方，小型車每字至少十六公分見方；標示於兩邊車門之汽車所有人，大型車每字至少八公分見方，小型車每字至少五公分見方。"],[2,"二、標示於車門或車廂兩邊之總聯結重量、總重量、載重之噸位、乘客人數、出廠年份、大客車分類及牌照號碼，大型車每字至少四公分見方，小型車每字至少三公分見方。"],[2,"三、標示於車內之駕駛人姓名、公司服務電話、公路主管機關申訴電話每字至少長四公分、寬二公分；標示於車外尾部之公路主管機關申訴電話每字至少長十公分、寬五公分。"]],"attachment":true},{"no":"43","label":"第 43 條","lines":[[0,"申請新領牌照之汽車，應於檢驗後將檢驗結果記錄於新領牌照登記書內。"]]},{"no":"44","label":"第 44 條","lines":[[0,"領有牌照之各類車輛，應依下列規定辦理定期檢驗："],[2,"一、自用小客車、自用小客貨兩用車、大型重型機車或駕艙機車，出廠年份未滿五年者，免予定期檢驗；五年以上未滿十年者，每年至少檢驗一次；十年以上者每年至少檢驗二次。"],[2,"二、租賃期一年以上租賃自用小客車或租賃自用小客貨兩用車，出廠年份未滿三年者免予定期檢驗；三年以上未滿六年者，每年至少檢驗一次；六年以上者每年至少檢驗二次。"],[2,"三、出廠年份逾十年之營業大客車或高壓罐槽車，每年至少檢驗三次。"],[2,"四、使用液化石油氣、壓縮天然氣為燃料之車輛、幼童專用車、其他自用車或其他營業車，出廠年份未滿五年者，每年至少檢驗一次；五年以上者每年至少檢驗二次。"],[2,"五、拖車每年至少定期檢驗一次。"],[0,"辦理前項定期檢驗者，應於指定日期前後一個月內向公路監理機關申請檢驗。但逾十年之營業大客車或高壓罐槽車，應於指定日期前一個月內為之。"],[0,"車輛所有人辦理定期檢驗，應繳驗下列證件："],[2,"一、行車執照或拖車使用證。"],[2,"二、個人經營計程車客運業營業車輛，並應持其本人有效計程車駕駛人執業登記證。"],[2,"三、營業車輛經所有人申請者，並應持新領牌照登記書。"],[0,"已領牌照之普通重型及輕型機車實施臨時檢驗。"]]},{"no":"45","label":"第 45 條","lines":[[0,"汽車或拖車有下列情形之一者，應申請實施臨時檢驗："],[2,"一、車身、引擎、底盤、電系或其他重要設備變更調換。"],[2,"二、因交通事故遭受重大損壞，經送廠修復。"],[2,"三、出廠十年以上，辦理轉讓過戶。"],[0,"機車出廠六年以上，辦理轉讓過戶者，應申請實施臨時檢驗。但自中華民國九十五年六月十五日起，機車出廠五年以上辦理轉讓過戶者，亦同。"],[0,"公路監理機關於必要時，得實施臨時檢驗。對於出廠十年以上或行駛有安全之虞之汽車及拖車，應按所轄管之汽車數量比例訂定年度計畫，實施臨時檢驗。"]]},{"no":"46","label":"第 46 條","lines":[[0,"檢驗不合格之汽車，責令於一個月內整修完善申請覆驗。"],[0,"前項檢驗不合格部分如為傳動、制動或轉向系統者，應即扣留其牌照，由公路監理機關發給當日有效之進廠修理證，憑以駛赴修理。"],[0,"汽車修復後得憑修理廠所領之試車牌照駛赴覆驗，修理廠未領有試車牌照者，得向公路監理機關申請發給覆驗證，以當日為有效期間。"]]},{"no":"47","label":"第 47 條","lines":[[0,"汽車之檢驗得委託公民營汽車製造廠、修理廠、加油站代辦，其辦法另定之。"]]},{"no":"48","label":"第 48 條","lines":[[0,"（刪除）"]]},{"no":"49","label":"第 49 條","lines":[[0,"汽車檢驗作業程序，由交通部另定之。"]]}]},{"title":"第 三 章 汽車駕駛人登記及考驗","articles":[{"no":"50","label":"第 50 條","lines":[[0,"汽車駕駛執照為駕駛汽車之許可憑證，由駕駛人向公路監理機關申請登記，考驗及格後發給之。汽車駕駛人經考驗及格，未領取駕駛執照前，不得駕駛汽車。"],[0,"汽車駕駛人受終身不得考領駕駛執照處分，得依道路交通管理處罰條例第六十七條之一規定，向公路監理機關申請汽車駕駛執照考驗。"],[0,"軍事專業駕駛人於退役後一年內，得憑軍事運輸主管機關發給之軍事專業駕駛證明，換發同等車類之普通或職業駕駛執照。"],[0,"前項軍事專業駕駛人於服役期間，因社會發生緊急事件或重大事故時，為應客貨運輸之需要，得經過適當訓練後憑軍事運輸主管機關繕造之名冊及核發之軍事專業駕駛證明，由公路監理機關專案換發同等車類之職業駕駛執照，並由軍事運輸主管機關統一集中保管，於執行緊急疏運支援任務時分發軍事專業駕駛人攜帶備查，於任務結束時繳還；並俟於軍事專業駕駛人退伍時發給作為民間駕駛之用。"],[0,"持有外國政府、大陸地區、香港或澳門所發有效之正式駕駛執照（證）並取得經許可停留或居留六個月以上之證明（件）者，得於入境之翌日起依平等互惠原則免考換發同等車類之普通駕駛執照。但持有該有效之正式駕駛執照者而具有中華民國國籍時，得免考換發同等車類之普通駕駛執照。"],[0,"汽車駕駛人辦理前項換發手續時，應先經體格檢查合格，並檢同下列文件，向公路監理機關申請："],[2,"一、汽車駕駛執照申請書。"],[2,"二、具中華民國國籍在臺灣地區設有戶籍之我國國民，應檢附國民身分證或軍人身分證。"],[2,"三、臺灣地區無戶籍之國民、外國人、大陸地區人民、香港或澳門居民，應檢附經許可停留或居留六個月以上之證明（件）。"],[2,"四、大陸地區所發駕駛證，應經行政院設立或指定機構或委託之民間團體驗證。"],[2,"五、香港或澳門所發駕駛執照，應經行政院於香港或澳門設立或指定機構或委託之民間團體驗證。"],[2,"六、其他國家或地區所發駕駛執照，應經我駐外使領館、代表處、辦事處，或經外國駐華使領館、經外國政府或地區授權並經我國外交部同意辦理文件證明業務之外國駐華機構之驗證。"],[2,"七、前款之駕駛執照為英文以外之外文者，應附中文譯本，並經我駐外使領館、代表處、辦事處或國內公證人驗證，或經外國駐華使領館、經外國政府或地區授權並經我外交部同意辦理文件證明業務之外國駐華機構之驗證。"]]},{"no":"51","label":"第 51 條","lines":[[0,"汽車駕駛執照之型式、顏色及編號，按其種類由交通部定之。"],[0,"國際駕駛執照之型式、顏色及許可駕駛之車類，依國際道路交通公約之規定。"]]},{"no":"52","label":"第 52 條","lines":[[0,"汽車駕駛執照自發照之日起每滿六年換發一次，汽車駕駛人應於有效期間屆滿前後一個月內向公路監理機關申請換發新照。但年滿六十歲之職業駕駛人經依第六十四條之一規定體格檢查判定合格者，換發有效期限一年之新照，或於原領職業駕駛執照以每年加註方式延長有效期間，至年滿六十五歲止。"],[0,"逾六十五歲之職業駕駛人，前一年內未受吊扣駕駛執照處分且依第六十四條之一規定體格檢查判定合格者，得換發有效期間一年之小型車職業駕駛執照，或於小型車職業駕駛執照以每年加註方式延長有效期間，至年滿六十八歲止。"],[0,"依前二項規定以加註方式延長有效期間之駕駛執照，仍應依第一項前段規定辦理駕駛執照之換發。"],[0,"汽車駕駛人受終身不得考領駕駛執照限制重新申請考驗合格後領有一年有效期間駕駛執照，其換發新照之有效期間，另依受終身不得考領駕駛執照限制重新申請考驗辦法規定辦理。"],[0,"臺灣地區無戶籍之國民、外國人、大陸地區人民、香港或澳門居民考領換領我國汽車駕駛執照之有效期間及換發，依第一項規定辦理。但於汽車駕駛執照有效期間屆滿時，應檢附第五十條第六項規定之經許可停留或居留證明文件，始得申請換發新照。"],[0,"中華民國九十六年六月一日前領有輕型機車駕駛執照者，得換發為普通輕型機車駕駛執照。"],[0,"自中華民國一百零二年七月一日起，新領或已領有之各類普通駕駛執照，免再依第一項前段規定期間申請換發；其已領有之駕駛執照有效期間屆滿後，仍屬有效，並得免換發之；外國人取得外僑永久居留證者，亦同。但本規則對汽車駕駛人另有規定其駕駛執照有效期間及申請換發新照規定時，應依規定辦理之。"],[0,"除前項免再依規定申請換發之情形外，汽車駕駛執照逾期未換發新照者，不得駕駛汽車。"]]},{"no":"52-1","label":"第 52-1 條","lines":[[0,"逾六十八歲小型車職業駕駛人及汽車運輸業所屬逾六十五歲大型車職業駕駛人，前一年內未受吊扣駕駛執照處分且依第六十四條之一規定體格檢查判定合格者，經檢附通過汽車駕駛人認知功能測驗或無患有失智症證明文件，得換發有效期間一年之職業駕駛執照，或於職業駕駛執照以每年加註方式延長有效期間，小型車職業駕駛執照至年滿七十歲止；大型車職業駕駛執照至年滿六十八歲止。"],[0,"職業駕駛人依前項規定換發職業駕駛執照後，駕駛汽車違反本規則、依本條例第三十三條第六項授權訂定之管制規則，因而肇事致人受傷未受吊銷駕駛執照處分者，應於公路監理機關通知後兩個月內，依前項規定重新辦理體格檢查判定合格及檢附無患有失智症證明文件後，始得繼續領有該職業駕駛執照。"],[0,"第一項規定之汽車駕駛人認知功能測驗由公立醫院、衛生機關為之，或由公路監理機關指定之醫院、診所、團體或人員為之。汽車駕駛人認知功能測驗依附件十九規定。"],[0,"中華民國一百零九年七月一日前已年滿六十五歲未滿六十八歲之大型車職業駕駛人，因屆齡換領同等車類普通駕駛執照，得依第一項規定換發新職業駕駛執照；未繳回職業駕駛執照致註銷而領有普通駕駛執照，須補考職業駕駛執照應考之科目後，始得依第一項規定領取有效期限一年之大型車職業駕駛執照。"]],"attachment":true},{"no":"52-2","label":"第 52-2 條","lines":[[0,"自中華民國一百零六年七月一日起，除第三項另有規定外，新領或未滿七十五歲駕駛人已領有之普通駕駛執照有效期間至年滿七十五歲止，其後應每滿三年換發一次，駕駛人應於有效期間屆滿前後一個月內，經第六十四條規定體格檢查合格，並檢附通過第五十二條之一所定汽車駕駛人認知功能測驗或檢附無患有中度以上失智症證明文件，向公路監理機關申請換發新照，或於駕駛執照以加註方式延長有效期間。但年滿七十五歲駕駛人首次換照，得於有效期間屆滿前一個月至屆滿後三年內辦理；未換發新照而受違規記點或吊扣駕駛執照處分，應於公路監理機關通知後三個月內辦理換照。"],[0,"中華民國一百零六年七月一日前已年滿七十五歲之駕駛人，其已領有之駕駛執照有效期間屆滿後，仍屬有效，並得免換發之。但自中華民國一百零六年七月一日起受違規記點或吊扣駕駛執照處分者，應於公路監理機關通知後三個月內，依前項規定辦理換照。"],[0,"自中華民國一百十五年五月三十一日起，新領或未滿七十歲駕駛人已領有之普通駕駛執照有效期間至年滿七十歲止，其後應依規定換發有效期間至七十五歲之駕駛執照；中華民國一百十五年五月三十一日，已年滿七十歲未滿七十五歲駕駛人，應依規定換發有效期間至七十五歲之駕駛執照。其換照規定如下："],[2,"一、年滿七十歲駕駛人，應於駕駛執照有效期間屆滿前一個月至屆滿後二年內，經第六十四條規定體格檢查合格，並完成道路交通安全講習後，向公路監理機關申請換發新照，或於駕駛執照以加註方式延長有效期間，換發有效期間至七十五歲之駕駛執照。"],[2,"二、中華民國一百十五年五月三十一日，已年滿七十歲未滿七十五歲駕駛人，應於二年內依前款規定辦理換照，未辦理者視為逾期，不得駕車。但二年內年滿七十五歲應依第四項規定辦理換照者，不適用第一項但書前段之規定。"],[2,"三、未換發新照而受違規記點或吊扣駕駛執照處分，應於公路監理機關通知後三個月內辦理換照。"],[0,"中華民國一百十五年五月三十一日起，年滿七十五歲駕駛人，依第一項規定辦理換照者，其換照規定如下："],[2,"一、應完成道路交通安全講習後，始得依第一項規定辦理換照。但有前項第一款及第二款情形而未曾辦理換照者，不適用第一項但書前段之規定。"],[2,"二、自中華民國一百十五年十二月三十一日起，年滿七十五歲後有違規致肇事紀錄者，應經立案之駕駛訓練機構駕駛訓練結業後，始得依第一項規定辦理換照。"],[0,"年滿七十歲之駕駛人，依本規則其他規定僅得核發或換發未滿本條規定有效期間之駕駛執照時，仍應符合第一項、第三項及前項所定條件辦理換照。"],[0,"年滿七十五歲申請汽車駕駛執照考驗者，應符合第六十四條規定，並檢附通過第五十二條之一所定認知功能測驗或無患有中度以上失智症證明文件，始得向公路監理機關申請考驗，及格後核發三年有效期間之駕駛執照。"]]},{"no":"52-3","label":"第 52-3 條","lines":[[0,"患有癲癇疾病符合第六十四條第一項第一款第六目之1但書規定者，得申請機車或普通小型車駕駛執照考驗，其駕駛執照並自發照之日起每滿二年換發一次。"],[0,"前項駕駛人應於駕駛執照有效期限屆滿前後一個月內，檢具最近三個月內由醫療院所之神經內科、神經外科或兒科且曾參加神經相關專業訓練醫師（以下簡稱醫療院所醫師）出具最近二年內未癲癇發作並加註專科醫師證照號碼之診斷證明書，向公路監理機關申請換發駕駛執照，或於原領駕駛執照以加註方式延長有效期間；其以加註延長者，並應依第五十二條第一項前段規定辦理駕駛執照之換發。"]]},{"no":"52-4","label":"第 52-4 條","lines":[[0,"自中華民國一百十三年十月三十一日起，汽車駕駛人違反本條例規定受吊銷駕駛執照處分者，依規定接受道路交通安全講習，並重新申請考驗合格及繳清違規罰鍰後，由公路監理機關核發有效期間二年之駕駛執照，並自發照之日起，於六年期間內，每滿二年換發一次。"],[0,"自中華民國一百十三年十月三十一日起，汽車駕駛人違反本條例規定受吊扣駕駛執照處分，其原領有駕駛執照之有效期間，至受吊扣處分期間屆滿之日止，並應依規定接受道路交通安全講習及繳清違規罰鍰後，由公路監理機關依下列規定換發駕駛執照："],[2,"一、受吊扣駕駛執照一年以上者，換發有效期間三年之駕駛執照，並自發照之日起，於六年期間內，每滿三年換發一次。"],[2,"二、受吊扣駕駛執照未達一年者，換發有效期間六年之駕駛執照。"],[0,"前二項汽車駕駛人應於駕駛執照有效期間屆滿前後一個月內，向公路監理機關申請換發新照；未依規定申請換發者，除屬第二項第二款之情形外，於重行申請換發時起，該六年期間續行計算。"],[0,"第一項及第二項汽車駕駛人於駕駛執照有效期間內，再受吊銷或吊扣駕駛執照處分者，應再依前三項規定辦理，且六年期間另重新起算。但規定換發駕駛執照之有效期間逾原照者，仍依原效期換發。"],[0,"汽車駕駛人依本條規定持照六年期滿，未再受吊銷或吊扣駕駛執照處分者，適用其原得領有駕駛執照之規定辦理換發新照。"],[0,"汽車駕駛人依本規則其他規定僅得領有未逾本條規定有效期間之駕駛執照者，依其原適用之規定。但有第一項或第二項規定情形，仍應依該二項規定接受道路交通安全講習及繳清違規罰鍰後，始得核發或換發新照。"],[0,"汽車駕駛人於第一項或第二項規定之六年期間內，取得同級車類職業駕駛執照或高一級車類駕駛執照時，其有效日期應依原駕駛執照之期限辦理。"]]},{"no":"53","label":"第 53 條","lines":[[0,"汽車駕駛執照分為下列各類："],[2,"一、小型車普通駕駛執照。"],[2,"二、大貨車普通駕駛執照。"],[2,"三、大客車普通駕駛執照。"],[2,"四、聯結車普通駕駛執照。"],[2,"五、小型車職業駕駛執照。"],[2,"六、大貨車職業駕駛執照。"],[2,"七、大客車職業駕駛執照。"],[2,"八、聯結車職業駕駛執照。"],[2,"九、國際駕駛執照。"],[2,"十、輕型機車駕駛執照。"],[3,"十一、小型輕型機車駕駛執照。"],[3,"十二、普通輕型機車駕駛執照。"],[3,"十三、重型機車駕駛執照。"],[3,"十四、普通重型機車駕駛執照。"],[3,"十五、大型重型機車駕駛執照。"],[0,"駕駛駕艙機車者，應領有小型車以上駕駛執照。"]]},{"no":"54","label":"第 54 條","lines":[[0,"職業汽車駕駛人之駕駛執照，應自發照之日起，每滿三年審驗一次，並於審驗日期前後一個月內向公路監理機關申請審驗，審驗時並應檢附經第六十四條規定體格檢查合格證明。審驗不合格者，扣繳其駕駛執照，俟審驗合格後發還之。但年滿六十歲職業汽車駕駛人駕駛執照審驗時，應檢附經第六十四條之一規定體格檢查合格證明，並應每年審驗一次。"],[0,"駕駛人因患病、出國、服兵役、駕照被吊扣、羈押、服刑或受保安、感訓處分之執行，不能按時審驗者，得於病癒、回國、退役、駕照吊扣期滿、撤銷羈押、出獄或保安、感訓處分執行完畢六個月內持原照及有關證明向公路監理機關申請審驗。"],[0,"職業汽車駕駛人得憑因逾期審驗被註銷之職業駕駛執照，申請換發同等車類之普通駕駛執照。但在未換發普通駕駛執照前，不得駕駛汽車。"]]},{"no":"55","label":"第 55 條","lines":[[0,"國際駕駛執照之換領及簽證，依下列規定："],[2,"一、已領有駕駛執照之汽車駕駛人於有效期間內，得憑原駕駛執照向公路監理機關申請換領同等車類之國際駕駛執照。"],[2,"二、換領國際駕駛執照，應填具異動登記書，並繳驗第五十條第六項第二款至第四款規定之身分證明文件及原駕駛執照。"],[2,"三、持有互惠國所發有效之國際駕駛執照，在我國境內作三十天以內之短期停留者，准予免辦簽證駕駛汽車；如停留超過三十天者，仍應向公路監理機關辦理簽證。"],[2,"四、國際駕駛執照之簽證最長為一年，若原照或停居留證明（件）有效期間未滿一年者，以先屆滿之日期為準，逾期不得駕駛汽車。"],[0,"汽車駕駛人依前項第一款規定申請換領國際駕駛執照，同時申請換發新照者，得不受第五十二條第一項應於有效期間屆滿前一個月內向公路監理機關申請換發新照規定之限制。"]]},{"no":"55-1","label":"第 55-1 條","lines":[[0,"外國政府或地區所發有效之正式駕駛執照，得依平等互惠原則在我國使用，並准予在我國境內駕駛同等車類之汽車。"],[0,"前項互惠原則、使用方式、駕駛車類、有效期間及施行日期等事項，交通部應公告及刊登政府公報或新聞紙。"]]},{"no":"55-2","label":"第 55-2 條","lines":[[0,"汽車駕駛人違反本條例規定，駕駛執照受吊銷、註銷或不得考領駕駛執照處分，或受吊扣處分尚未執行完畢者，不得依第五十條第五項、第五十五條第一項第三款、第四款或第五十五條之一規定，持外國政府、大陸地區、香港或澳門所發有效之正式駕駛執照（證）或國際駕駛執照，駕車或換發普通駕駛執照。"]]},{"no":"56","label":"第 56 條","lines":[[0,"學習小型汽車駕駛，應向公路監理機關申領學習駕駛證，學習大型車汽車駕駛，應領有小型車駕駛執照。但汽車駕駛人違反本條例規定受吊銷駕駛執照處分，並參加駕駛訓練機構道路駕駛訓練者，應依其所參加訓練班之車類，申領該車類學習駕駛證。"]]},{"no":"57","label":"第 57 條","lines":[[0,"申請汽車學習駕駛證者，須年滿十八歲，並須體格檢查及體能測驗合格。"],[0,"參加駕駛訓練機構辦理機車道路駕駛訓練者，得依前項規定向公路監理機關申領機車學習駕駛證；申請機車學習駕駛證，免辦體能測驗。"]]},{"no":"58","label":"第 58 條","lines":[[0,"學習汽車駕駛，以在駕駛學習場內學習駕駛為原則。在學習路線駕駛時，應依公路或市區道路主管機關指定之道路及時間內為之，並應由領有學習車類駕照之汽車駕駛人在旁指導監護。"],[0,"汽車駕駛執照路考考驗之道路路線或路段，由公路監理機關指定後，送請公路主管或市區道路主管機關備查；該路線或路段並得為學習路線。"],[0,"駕駛訓練機構辦理機車駕駛訓練，依前二項規定辦理。"]]},{"no":"59","label":"第 59 條","lines":[[0,"學習駕駛證之學習駕車有效期間，自領證之日起以一年為限。"]]},{"no":"60","label":"第 60 條","lines":[[0,"申請汽車駕駛執照考驗者，應具有下列資格："],[2,"一、年齡："],[3,"（一）考領普通駕駛執照、輕型或普通重型機車駕駛執照須年滿十八歲，最高年齡不受限制。"],[3,"（二）考領大型重型機車駕駛執照須年滿二十歲，最高年齡不受限制。"],[3,"（三）考領職業駕駛執照須年滿二十歲，最高年齡不得超過六十五歲。但依第五十二條之一第四項規定辦理者，最高年齡不得超過六十八歲。"],[2,"二、經歷："],[3,"（一）應考輕型或普通重型機車駕駛執照者，無經歷之限制。"],[3,"（二）應考大型重型機車駕駛執照者，須領有普通重型機車駕駛執照一年以上之經歷，並經立案之駕駛訓練機構駕駛訓練結業。"],[3,"（三）應考小型車普通駕駛執照者，須有學習駕駛三個月以上之經歷。"],[3,"（四）應考小型車職業駕執照者，須有學習駕駛六個月以上之經歷。"],[3,"（五）應考大貨車普通駕駛執照者，須領有小型車普通駕駛執照一年以上之經歷。"],[3,"（六）應考大貨車職業駕駛執照者，須領有小型車職業駕駛執照一年以上之經歷。"],[3,"（七）應考大客車普通駕駛執照者，須領有大貨車普通駕駛執照一年以上之經歷；或領有小型車普通駕駛執照二年以上之經歷，並經立案之駕駛訓練機構小型車逕升大客車駕駛訓練結業者。"],[3,"（八）應考大客車職業駕駛執照者，須領有大貨車職業駕駛執照一年以上之經歷；或領有小型車職業駕駛執照二年以上之經歷，並經立案之駕駛訓練機構小型車逕升大客車駕駛訓練結業者。"],[3,"（九）應考聯結車普通駕駛執照者，須領有大客車普通駕駛執照一年以上或領有大貨車普通駕駛執照二年以上之經歷。"],[3,"（十）應考聯結車職業駕駛執照者，須領有大客車職業駕駛執照一年以上或領有大貨車職業駕駛執照二年以上之經歷。"],[4,"（十一）應考小型車附掛總重逾七百五十公斤至三千公斤以下拖車駕駛資格者，須領有小型車駕駛執照一年以上之經歷或領有大貨車或大客車駕駛執照，並經立案之駕駛訓練機構駕駛訓練結業。"],[0,"前項第二款各目之經歷，如經公立或立案之私立駕駛訓練機構依規定訓練結業者，得由交通部按照其登記領照之教練車數量予以核定，不受其限制，並准集體報考。"],[0,"領有普通駕駛執照滿三個月之駕駛人，得報考同級車類之職業駕駛執照，除應具備報考之資格外，並應補考職業駕駛執照應考之科目。"],[0,"汽車駕駛人受終身不得考領駕駛執照處分，重新申請考驗合格後領有或換發一年有效期間之駕駛執照及其受終身吊銷駕駛執照處分前之經歷，不予採計。"],[0,"汽車駕駛人違反本條例規定受吊銷駕駛執照處分，於不得考領駕駛執照期間屆滿後，得報考其受吊銷處分前曾領有同等或較低等級車類之普通或職業駕駛執照，不受第一項第二款所定經歷限制。但不得考領駕駛執照期間合計達三年以上者，應經公立或立案之私立駕駛訓練機構依規定完成該等級車類訓練結業後，始得申請駕駛執照考驗。"],[0,"前項汽車駕駛人重新申請考驗合格後領有駕駛執照者，於申請汽車駕駛執照之晉級考驗時，應受第一項第二款所定經歷限制，且其受吊銷駕駛執照處分前之經歷，不予採計。"]]},{"no":"61","label":"第 61 條","lines":[[0,"汽車駕駛人取得高一級車類之駕駛資格者，應換發駕駛執照，並准其駕駛較低級車類之車輛，其規定如下："],[2,"一、已領有聯結車駕駛執照者，得駕駛大客車（含雙節式大客車）、大貨車、代用大客車、大客貨兩用車、曳引車、小型車（含小型車附掛拖車）、輕型機車。自中華民國九十六年二月一日起已領有大貨車駕駛執照二年以上之經歷申請考驗取得聯結車駕駛執照者，不得駕駛大客車、代用大客車、大客貨兩用車。"],[2,"二、已領有大客車駕駛執照者，得駕駛大貨車、代用大客車、大客貨兩用車、曳引車、小型車、輕型機車。但不得駕駛雙節式大客車。"],[2,"三、已領有大貨車駕駛執照者，得駕駛小型車、輕型機車。"],[2,"四、已領有小型車駕駛執照者，得駕駛輕型機車。"],[2,"五、已領有大型重型機車駕駛執照者，得駕駛普通重型機車、輕型機車。"],[2,"六、已領有普通重型機車駕駛執照者，得駕駛輕型機車。"],[2,"七、已領有重型機車駕駛執照者，得駕駛普通重型機車、輕型機車。"],[2,"八、已領有普通輕型機車駕駛執照者，得駕駛小型輕型機車。"],[2,"九、已領有輕型機車駕駛執照者，得駕駛普通輕型機車、小型輕型機車。"],[0,"中華民國一百十二年六月三十日起新考領之汽車駕駛執照不得駕駛輕型機車。"],[0,"已領有大客車、大貨車或小型車駕駛執照者，得駕駛小型車附掛輕型拖車。"],[0,"已領有大客車、大貨車或小型車駕駛執照，經小型車附掛總重逾七百五十公斤至三千公斤以下拖車駕駛資格考驗合格者，得駕駛小型車附掛總重逾七百五十公斤至三千公斤以下拖車。"],[0,"原領有職業駕駛執照之駕駛人，取得高一級車類之普通駕駛執照資格滿三個月者，得換領同級車類之職業駕駛執照。"],[0,"機車駕駛執照於吊扣期間或經吊銷後，不得持汽車駕駛執照駕駛輕型機車。"]]},{"no":"61-1","label":"第 61-1 條","lines":[[0,"駕駛人取得駕駛執照駕車之行車條件，除前條規定外，包括下列規定："],[2,"一、汽車駕駛人應依駕駛執照所載之持照條件駕車。"],[2,"二、僅領有小型輕型機車駕駛執照者，不得駕駛普通輕型機車。"],[2,"三、僅領有重型機車駕駛執照者，不得駕駛大型重型機車。"],[2,"四、僅領有限制駕駛未滿汽缸總排氣量五百五十立方公分之大型重型機車駕駛執照者，不得駕駛汽缸總排氣量五百五十立方公分以上或電動機車之馬達及控制器最大輸出馬力五十四馬力（HP）以上之大型重型機車。"],[2,"五、受終身不得考領駕駛執照處分，重新申請考驗合格後領有或換發一年有效期間駕駛執照逾期，不得使用駕車。"],[2,"六、領有大客車以上職業駕駛執照駕駛遊覽車，應符合汽車運輸業管理規則第八十六條所定之經歷及專業訓練條件。"],[2,"七、領有大客車、大貨車或小型車駕駛執照者，未經考驗合格不得駕駛小型車附掛總重逾七百五十公斤至三千公斤以下拖車。"],[2,"八、僅領有機車駕駛執照者，不得駕駛駕艙機車。"],[2,"九、汽車運輸業所屬逾六十五歲大型車職業駕駛人駕駛大型營業車輛，除遊覽車客運業、汽車貨運業及汽車貨櫃貨運業依汽車運輸業管理規則第十九條之七第三項規定申經核准者外，限於上午六時至下午六時之時段行駛。"],[0,"前條及前項第一款至第八款為道路交通管理處罰條例第二十一條第四項所稱之持照條件。"],[0,"大型車職業駕駛人未依第一項第九款規定駕車，視為領有普通駕駛執照，駕駛營業汽車營業。"],[0,"領有得駕駛汽缸排氣量五百五十立方公分以上之大型重型機車駕駛執照一年以上及小型車以上之駕駛執照者，始得駕駛汽缸排氣量五百五十立方公分以上之大型重型機車，依交通部公告規定之路段及時段行駛高速公路。"],[0,"駕駛大眾捷運系統車輛者，應領有小型車以上職業駕駛執照。"]]},{"no":"62","label":"第 62 條","lines":[[0,"有下列各款情事之一者，不得參加汽車駕駛執照考驗："],[2,"一、受終身不得考領駕駛執照之處分。"],[2,"二、受吊銷駕駛執照處分尚未屆滿限制報考期限。"],[2,"三、受吊扣駕駛執照之處分尚未期滿。"],[2,"四、已領有同等級駕駛執照。"],[2,"五、曾依本條例第三十五條規定吊銷駕駛執照，未依本條例第六十七條規定完成酒駕防制教育或酒癮治療。"],[0,"汽車駕駛人受吊扣、吊銷駕駛執照處分尚未確定執行前，不得參加汽車駕駛執照之晉級考驗，如參加考驗取得高一級之駕駛執照資格者，該項資格於受執行吊扣或吊銷駕駛執照之處分時，一併吊扣或吊銷，但持有機車駕駛執照報考小型汽車駕駛執照者，不在此限。"]]},{"no":"63","label":"第 63 條","lines":[[0,"申請汽車駕駛執照考驗者，均應先經體格檢查及體能測驗合格，並檢同下列文件向公路監理機關報名："],[2,"一、汽車駕駛執照申請書。"],[2,"二、本人最近二年內拍攝之一吋光面素色背景脫帽五官清晰正面半身彩色相片三張，並不得使用合成相片。"],[2,"三、具中華民國國籍在臺灣地區設有戶籍之我國國民，應檢附國民身分證、僑民居留證明或其他有效之駕駛執照。"],[2,"四、臺灣地區無戶籍之國民、外國人、大陸地區人民、香港或澳門居民，應檢附經許可停留或居留六個月以上之證明（件）。"],[2,"五、駕駛經歷證件。"],[2,"六、曾依本條例第三十五條規定吊銷駕駛執照者，應檢附本條例第六十七條規定完成酒駕防制教育或酒癮治療之證明（件）。"],[0,"申請輕型或普通重型機車駕駛執照考驗者，免辦體能測驗。"]]},{"no":"64","label":"第 64 條","lines":[[0,"汽車駕駛人除身心障礙者及年滿六十歲職業駕駛者外，其體格檢查及體能測驗合格基準依下列規定："],[2,"一、體格檢查："],[3,"（一）視力：兩眼祼視力達零點六以上，且每眼各達零點五以上，或矯正後兩眼視力達零點八以上，且每眼各達零點六以上。"],[3,"（二）辨色力：能辨別紅、黃、綠色。"],[3,"（三）聽力：能辨別音響。"],[3,"（四）四肢：四肢健全無缺損。"],[3,"（五）活動能力：全身及四肢關節活動靈敏。"],[3,"（六）無下列疾病情形："],[301,"1.癲癇。但檢具醫療院所醫師出具最近二年以上未發作診斷證明書者，不在此限。"],[301,"2.有客觀事實足以認定其身心狀況影響汽車駕駛之虞，經專科醫師診斷認定者。"],[301,"3.其他足以影響汽車駕駛之疾病。"],[3,"（七）其他：無酒精、麻醉劑及興奮劑中毒。"],[2,"二、體能測驗："],[3,"（一）視野左右兩眼各達一百五十度以上。但年滿六十歲之駕駛人，視野應各達一百二十度以上。"],[3,"（二）夜視無夜盲症。"],[0,"前項體格檢查及體能測驗應由公立醫院或衛生機關或公路監理機關指定醫院為之，或由附設有檢查設備及檢定合格醫事人員之公路監理機關或指定之診所、團體為之，但申請學習駕駛證時已經體格檢查合格者，一年內免再檢查。"],[0,"身心障礙者報考汽車、機車駕駛執照之規定，由交通部另定之。"]]},{"no":"64-1","label":"第 64-1 條","lines":[[0,"年滿六十歲職業駕駛人，應每年至中央衛生主管機關評鑑合格醫院作體格檢查一次，其合格基準除依第六十四條規定外，並經醫師判定符合下列合格基準："],[2,"一、血壓：收縮壓未達一百六十毫米汞柱（mm／Hg）；舒張壓未達一百毫米汞柱（mm／Hg）。"],[2,"二、胸部X光大片檢查：合於健康基準。"],[2,"三、心電圖檢查：合於健康基準或輕微異常不影響健康安全。"],[2,"四、無下列任一疾病："],[3,"（一）患有高血壓，經臨床診斷不足以勝任緊急事故應變，經休息三十分鐘後，平均血壓之收縮壓達一百六十毫米汞柱（mm／Hg）或舒張壓達一百毫米汞柱（mm／Hg）。"],[3,"（二）患有糖尿病且血糖無法控制良好。"],[3,"（三）患有冠狀動脈疾病及其他心臟疾病，經臨床診斷不足以勝任緊急事故應變。"],[3,"（四）患有癲癇、腦中風、眩暈症、重症肌無力等身體障礙致不堪勝任工作。"],[3,"（五）患有呼吸道疾病史者肺功能用力肺活量（FVC）或一秒最大呼氣量（FEV1／FVC）低於百分之六十之預測值。"],[3,"（六）有客觀事實足以認定其身心狀況不能處理日常事務、有明顯傷害他人或自己之虞或有傷害行為，經專科醫師診斷認定者。"],[3,"（七）患有慢性酒精中毒及藥物依賴成癮。"],[3,"（八）患有經常性打呼合併白天嗜睡者，白天嗜睡指數大於十二。但接受多功能睡眠檢查評估治療有效者，不在此限。"],[3,"（九）其他：患有法定傳染病未經治癒且須強制隔離治療，或患有其他疾病致不堪勝任工作。"],[0,"逾六十八歲之小型車職業駕駛人及汽車運輸業所屬逾六十五歲之大型車職業駕駛人並應符合下列體格檢查之合格基準："],[2,"一、睡眠品質（PSQI）問卷評估：小於五分以下者為合格；不在此範圍值內但接受多功能睡眠生理檢查評估治療有效者，亦可評為合格。"],[2,"二、運動心電圖檢查：合於健康基準或輕微異常不影響健康安全。"],[2,"三、尿液檢驗、血液檢驗、生化檢驗：合於健康基準或輕微異常不影響健康安全。"]]},{"no":"65","label":"第 65 條","lines":[[0,"申請汽車駕駛執照考驗者，其應考科目為筆試及路考。"],[0,"筆試不及格者，不得參加路考，但依第六十九條核准在原訓練機構辦理考驗者，其結業學員得先參加路考，及格後再行筆試。"],[0,"筆試包括交通規則及機械常識，報考普通駕駛執照者，免考機械常識。各科考驗成績最高分均為一百分，其及格基準為交通規則八十五分，機械常識六十分，路考七十分。"],[0,"路考之評分基準表由交通部另定之。"],[0,"第一項筆試得以口試代替，聽覺功能障礙、聲音功能或語言功能障礙應考人並得以手語代替。"],[0,"前項口試及手語之通譯人員應由公路監理機關指定之公正人士為之。"],[0,"依第七十六條第一項第五款及第八款規定繳回汽車駕駛執照者，除依身心障礙者報考汽車駕駛執照之規定辦理外，其考驗之規定如下："],[2,"一、體格基準有下列情形之一者，得免考驗，逕予核發新照，不受第一項規定之限制："],[3,"（一）視覺功能障礙，其優眼視力裸視達零點六以上或矯正後達零點八以上或視野達一百五十度以上。"],[3,"（二）聽覺功能障礙，其優耳聽力損失在九十分貝以上。"],[3,"（三）聲音功能或語言功能障礙，其聲音功能或語言功能喪失，完全無法以聲音與人溝通（即重度障礙）。"],[3,"（四）最近二年以上未有癲癇發作，經醫療院所醫師出具診斷證明書。"],[2,"二、體格基準有下列情形之一者，得免予筆試："],[3,"（一）雙手手指缺損且其中一手手指或手掌未全缺。"],[3,"（二）四肢中欠缺任何一肢，經加裝輔助器具後操作方向盤自如。"],[3,"（三）軀幹及四肢未欠缺，惟受先天性及後天性之病害致功能障礙者（如四肢不全麻痺、軀幹功能障礙致站立或步行困難者等）經加裝輔助器具後，能自力行走。"]]},{"no":"65-1","label":"第 65-1 條","lines":[[0,"自中華民國一百零六年五月一日起，申請小型車駕駛執照考驗之路考，應實施場考及道路駕駛考驗，場考不及格者，不得參加道路駕駛考驗。"],[0,"申請小型車駕駛執照考驗者，依前項規定實施道路駕駛考驗時，應由考驗員在旁考核下，依第五十八條第二項指定之道路路線或路段上駕駛考驗用車進行考驗，並應遵守第四章汽車行駛管理各項規定、服從考驗員之重新、接續、終止考驗指示及考驗規定，其考驗規定如附件二十。"]],"attachment":true},{"no":"66","label":"第 66 條","lines":[[0,"考驗用車除考領機車駕駛執照及普通小型車駕駛執照之場考，得以自備車應考外，餘由公路監理機關供應，並按下列各款收取考驗車使用費："],[2,"一、聯結車按十公升高級柴油之市價收費。"],[2,"二、大客車、大貨車按八公升高級柴油之市價收費。"],[2,"三、小型車路考之場考及道路駕駛考驗各按四公升九五無鉛汽油之市價收費。但小型車經交通部指定考驗特定項目者，另加二公升九五無鉛汽油之市價收費。"],[2,"四、機車按一公升九五無鉛汽油之市價收費。"],[0,"身心障礙者報考小型車駕駛執照時，不受前項之限制，得自備經公路監理機關檢驗合格之自動排擋車輛或特製車應考。"],[0,"執行小型車道路駕駛考驗之考驗用車，應加掛標示「道路駕駛考驗中」之標識牌並投保，其標識牌式樣及保險內容如附件二十。"]],"attachment":true},{"no":"67","label":"第 67 條","lines":[[0,"申請汽車駕駛執照筆試、路考，經考驗不合格申請再考驗者，距上次考驗之時間不得少於七日。"],[0,"申請汽車駕駛執照考驗路考未及格者，得於下次申請考驗時免考筆試，其免考期限為一年；小型車場考及格而道路駕駛考驗未及格者，於下次申請考驗時免考場考，其免考期限亦同。"]]},{"no":"68","label":"第 68 條","lines":[[0,"（刪除）"]]},{"no":"69","label":"第 69 條","lines":[[0,"政府設立之汽車技術人員訓練機構及私立之汽車駕駛人員訓練機構，其師資、設備、教學及教材符合交通部所定基準者，其結業學員得由公路監理機關報請該管公路主管機關核准在原訓練機構使用其車輛辦理考驗。"]]},{"no":"70","label":"第 70 條","lines":[[0,"申請汽車駕駛執照考驗，不依規定或利用不正當手段報名參加應考者，其考試資格應予取銷，已考領駕駛執照者無效，由公路監理機關註銷並追繳之。"],[0,"託人代考者，取銷報考人之考試資格，報考人及代考人如已領有駕駛執照者，由公路監理機關吊銷其駕駛執照，並註銷之。"],[0,"報考人及代考人均自查獲之日起五年內不得再行報考。"]]},{"no":"71","label":"第 71 條","lines":[[0,"（刪除）"]]},{"no":"72","label":"第 72 條","lines":[[0,"（刪除）"]]},{"no":"73","label":"第 73 條","lines":[[0,"（刪除）"]]},{"no":"74","label":"第 74 條","lines":[[0,"（刪除）"]]},{"no":"75","label":"第 75 條","lines":[[0,"汽車駕駛人申請變更、換照、補照、登記，規定如下："],[2,"一、汽車駕駛人之姓名、國民身分證統一編號、外來人口統一證號、出生年、月、日、住址有變更者應填具異動登記書，檢同身分證或戶口名簿、停留或居留證明，向公路監理機關申請。"],[2,"二、變更姓名、國民身分證統一編號、外來人口統一證號、出生年、月、日者，應將原照註銷，換發新照；變更住址，就原照背面地址欄簽註之。"],[2,"三、汽車駕駛執照遺失或損毀時，應填具異動登記書，並繳驗第五十條第六項第二款至第四款規定之身分證明文件或有效之汽車駕駛執照向公路監理機關申請補發或換發。"]]},{"no":"75-1","label":"第 75-1 條","lines":[[0,"汽車駕駛人依前條規定申請補發或換發駕駛執照之有效期間規定如下："],[2,"一、除取得外僑永久居留證外之外國人、大陸地區人民、香港或澳門居民或臺灣地區無戶籍之國民考領換領我國汽車駕駛執照者，換發或補發有效期間六年之新照。"],[2,"二、受終身不得考領駕駛執照處分重新申請考驗合格領有一年有效期間者，依原效期補發或換發。"],[2,"三、未滿六十歲之職業駕駛人依原效期補發或換發。但依規定審驗合格者，補發或換發最多六年有效期間之駕駛執照。"],[2,"四、年滿六十歲以上之職業駕駛人，依其原效期補發或換發。但經依規定體格檢查判定合格者，得補發或換發最多一年有效期間之新照。"]]},{"no":"76","label":"第 76 條","lines":[[0,"有下列各款情形之一者，駕駛人或關係人應迅速將駕駛執照繳回當地公路監理機關："],[2,"一、執照受吊銷、註銷或吊扣處分。"],[2,"二、執照失效或過期。"],[2,"三、汽車駕駛人死亡。"],[2,"四、職業駕駛人年滿六十五歲。但依第五十二條第二項及第五十二條之一第一項規定換發小型車職業駕駛執照者年滿七十歲；換發大型車職業駕駛執照者年滿六十八歲。"],[2,"五、汽車駕駛人之體格及體能變化已不合於第六十四條及第六十四條之一規定合格基準之一。"],[2,"六、年滿六十八歲小型車及汽車運輸業所屬逾六十五歲大型車職業駕駛人不依第五十二條之一第二項規定辦理。"],[2,"七、受違規記點或吊扣駕駛執照處分之年滿七十歲駕駛人，不依第五十二條之二第一項至第四項規定辦理。"],[2,"八、依第五十二條之三規定取得駕駛執照之駕駛人，有癲癇發作情形或未依該規定辦理定期換照。"],[0,"前項第四款至第八款汽車駕駛人不得駕駛汽車；未將執照繳回者，由公路監理機關逕行公告註銷並追繳之。職業汽車駕駛人得憑其因逾法定年齡而失效之職業駕駛執照，申請換發同等車類之普通駕駛執照。但在未換發普通駕駛執照前，不得駕駛汽車。"]]},{"no":"76-1","label":"第 76-1 條","lines":[[0,"汽車駕駛人得自願申請註銷駕駛執照或改領較低等級駕駛執照。但受吊扣駕駛執照處分者，於吊扣期滿後始得申請。"],[0,"汽車駕駛人依前項規定自願註銷或改領較低等級駕駛執照後，有再駕駛原等級車輛需求者，應依規定重新考領取得原等級車類駕駛執照。"]]}]},{"title":"第 四 章 汽車裝載行駛","articles":[{"no":"77","label":"第 77 條","lines":[[0,"汽車裝載時，除機車依第八十八條規定外，應依下列規定："],[2,"一、裝置容易滲漏、飛散、氣味惡臭之貨物，能防止其發洩者，應嚴密封固，裝置適當。"],[2,"二、載運人客、貨物必須穩妥，車門、車廂應能關閉良好，物品應捆紮牢固，堆放平穩，不得突出車身兩側。"],[2,"三、貨車駕駛室或小客車之前座乘人不得超過規定之人數。"],[2,"四、車廂以外不得載客。"],[2,"五、後車廂之貨物上不得附載人員。"],[2,"六、框式貨車後車廂不得載人。"],[2,"七、特種車除因其專門用途使用時必須附載之人員物品外，不得用以裝載客貨行駛。"],[2,"八、小型汽車應依核定附掛拖車，且附掛之拖車應僅限於裝載露營、休閒遊憩、防疫及救災用具使用，且其車門應能關閉良好，物品應捆紮牢固，堆放平穩，不得突出車身兩側，行駛中不得附載人員及其側面車窗不得向外開啟。"],[2,"九、裝載貨物行經設有地磅處所，應依標誌、標線、號誌指示，或交通勤務警察或依法令執行交通稽查任務人員之指揮停車過磅。"],[2,"十、小型汽車置放架，其使用應依下列規定："],[3,"（一）置放架及裝載物應固定妥適。如裝置於車輛後側，其長度不應超過後側車身外五十公分；如裝置於車頂，其含置放架之車輛全高應依第三十八條第一項之規定。"],[3,"（二）置放架及裝載物不得遮蔽車輛之號牌與車輛後方燈光，不得突出車身兩側。"]]},{"no":"78","label":"第 78 條","lines":[[0,"客車之載運，應依下列規定："],[2,"一、載運乘客不得超過核定之人數。但公共汽車於尖峰時刻載重未超過核定重量者，不在此限。"],[2,"二、公共汽車開啟或關閉車門應注意上下乘客安全。"],[2,"三、計程車不得任意拒載乘客或故意繞道行駛。"],[2,"四、計程車在設有停車上客處標誌之路段，應在指定之上客處搭載乘客，不得沿途攬載。"]]},{"no":"79","label":"第 79 條","lines":[[0,"貨車之裝載，應依下列規定："],[2,"一、裝載貨物不得超過核定之總重量或行駛橋樑規定之載重限制。"],[2,"二、依第二十四條第四項規定變更載重登記之小貨車，不得超過登記之載重限制。"],[2,"三、裝載物必須在底板分配平均，不得前伸超過車頭以外，體積或長度非框式車廂所能容納者，伸後長度最多不得超過車輛全長百分之三十，並應在後端懸掛危險標識，日間用三角紅旗，夜間用紅燈或反光標識。廂式貨車裝載貨物不得超出車廂以外。"],[2,"四、裝載貨物寬度不得超過車身。"],[2,"五、裝載貨物高度自地面算起，大型車不得超過四公尺，小型車不得超過二點八五公尺。"],[2,"六、以大貨車裝載貨櫃者，除應有聯鎖裝置外，不得超出車身以外。"],[2,"七、不符合規定之傾卸框式大貨車不得裝載砂石、土方。"],[0,"除前項第三款之情形外，車身欄板應扣牢。"]]},{"no":"80","label":"第 80 條","lines":[[0,"貨車裝載整體物品有下列情形之一者，應填具申請書，繪製裝載圖，向起運地或車籍所在地公路監理機關申請核發臨時通行證，憑證行駛："],[2,"一、裝載整體物品之長度、高度、寬度超過前條之規定者。"],[2,"二、裝載整體物品之軸重、總重量或總聯結重量超過第三十八條第一項第二款、第三款限制者。"],[0,"前項裝載整體物品行駛於高速公路之汽車，其長度超過第三十八條第一項第一款規定，重量超過前項第二款規定，寬度超過三點二五公尺，高度超過四點二公尺者，接受申請之公路監理機關應先洽經高速公路管理機關認可後，始得核發通行證。"],[0,"同一事業機構或公司行號，經常以同一汽車裝載同一性質規格之物品時，得依前二項規定申請核發六個月以內之臨時通行證。"],[0,"裝載第一項、第二項物品，應於車輛前後端懸掛危險標識；日間用三角紅旗，夜間用紅燈或紅色反光標識，紅旗每邊之長度，不得少於三十公分。"],[0,"如公路監理機關或警察機關對該項物品之裝載行駛有特別規定者，應遵守其規定。"],[0,"裝載第一項、第二項物品之汽車，行駛路線經過不同之省（市）時，其臨時通行證之核發，應經該管公路主管機關之同意，經過高速公路時，除有特殊狀況外，應行駛外側車道，並禁止變換車道。"]]},{"no":"80-1","label":"第 80-1 條","lines":[[0,"政府機關（構）、公營事業、公用事業專供治安、防疫、環保、公共輸變電架線工程、探採工程及道路、橋樑、隧道之修建養護，或鐵路、大眾捷運系統營運機構專供軌道、橋樑、隧道之修建養護等用途之特殊規格車輛，得經主管機關報經交通部核定，比照前條規定向公路監理機關申請核發臨時通行證，憑證行駛。"]]},{"no":"80-2","label":"第 80-2 條","lines":[[0,"專供營建工程不具載貨空間及方向盤在左側之特殊規格特種車輛，且尺度逾第三十八條第一項第一款、軸重逾第三十八條第一項第二款、總重量逾附件十一規定、或軸組型態為前單軸後參軸或前雙軸後參軸者，得比照第八十條及檢附下列文件向公路監理機關申請核發臨時通行證，憑證行駛："],[2,"一、繳驗公司或行號登記證明文件及檢附特殊規格特種車輛來歷憑證、諸元規格資料、加註尺度之照片。"],[2,"二、檢附依法領有公司、商業或工廠登記證明文件之合法汽車修理業者出具四個月內保養紀錄表，其保養檢查項目如附件十八。"],[0,"前項特殊規格特種車輛顯有損壞道路、橋梁之虞者，不得核發臨時通行證。"],[0,"第一項特殊規格特種車輛行駛於道路時，除應依臨時通行證所核定之路線、時間、速限行駛外，並應遵守下列規定："],[2,"一、遵守道路交通標誌、標線、號誌之指示、警告、禁制規定，並服從執行交通勤務之警察或依法令執行指揮交通及交通稽查任務人員（以下簡稱交通指揮人員）之指揮。"],[2,"二、駕駛人應攜帶臨時通行證。"],[2,"三、在同向二車道以上之道路，應行駛於最外側車道。"],[2,"四、應裝置符合規定之帶狀反光標識、輪廓邊界標識燈、照後鏡、照地鏡及防止捲入裝置；於日間並應開啟頭燈及輪廓邊界標識燈。"],[2,"五、軸組型態為前單軸後參軸、前雙軸後參軸車輛，應配備標識前導及後衛之車輛隨行。"],[2,"六、應遵守本章汽車行駛管理各項規定。"]],"attachment":true},{"no":"81","label":"第 81 條","lines":[[0,"聯結車輛之裝載，應依下列規定："],[2,"一、半聯結車裝載之總聯結重量，不得超過曳引車及半拖車核定之總聯結重量。"],[2,"二、全聯結車裝載之總聯結重量，不得超過兼供曳引大貨車核定之總聯結重量。"],[2,"三、全拖車裝載之總重量不得超過核定之總重量及兼供曳引大貨車裝載之總重量。"],[2,"四、兼供曳引大貨車裝載之總重量不得超過核定之總重量。"],[2,"五、裝載之貨物及貨櫃不得伸出車尾以外，裝載貨櫃時，並應與拖車固定聯結。"],[2,"六、不符合規定之傾卸框式半拖車不得裝載砂石、土方。"]]},{"no":"82","label":"第 82 條","lines":[[0,"曳引車牽引拖架時，應依下列規定："],[2,"一、裝載物之長度未達十公尺以上者，禁止使用拖架。"],[2,"二、裝載後全長不得超過十八公尺。"],[2,"三、裝載物品之長度自曳引車第五輪中心線至裝載物品前端間之距離不得超過一公尺；自拖架輪軸中心線至裝載物品後端間之距離不得超過三公尺。"],[2,"四、裝載物品後不得超過曳引車核定之總聯結重量及拖架核定之總重量。"],[0,"拖架裝載整體物品超過前項第二款、第四款之規定者，應依照貨車裝載整體物品之規定向公路監理機關申請核發臨時通行證，憑證行駛。"]]},{"no":"83","label":"第 83 條","lines":[[0,"非屬汽車範圍之動力機械，指下列各款之一之機械："],[2,"一、不經曳引而能以原動機行駛之工程重機械。"],[2,"二、屬裝配起重機械專供起重用途且無載貨容量之起重機車或其他自力推動機械。"],[2,"三、配衡型堆高機。"],[2,"四、其他特定用途設計製造，不經曳引而能以原動機行駛之機械。"],[0,"前項第二款及第三款裝有輪式輪胎之動力機械應先向公路監理機關申請登記領用牌證，並比照第八十條之規定申請核發臨時通行證後，方得憑證行駛道路。"],[0,"動力機械申請登記領用牌證，依其總重量及規格分類如下："],[2,"一、普通動力機械：總重量四十二公噸以下且其全長、全寬及全高尺度符合第三十八條規定大貨車尺度限制之動力機械。"],[2,"二、重型動力機械：總重量逾四十二公噸且在七十五公噸以下，或四十二公噸以下其全長、全寬及全高尺度逾第三十八條規定大貨車尺度限制之動力機械。"],[2,"三、大型重型動力機械：總重量逾七十五公噸之動力機械。"],[0,"進口第一項第二款裝有輪式輪胎之動力機械，其方向盤應在左側。但於中華民國一百零四年十二月三十一日以前進口者，不在此限。"],[0,"依前項但書規定，自中華民國一百年四月十五日起，各年得進口製造未逾十五年方向盤非在左側之動力機械總量，依下列規定："],[2,"一、一百年：一千一百輛。"],[2,"二、一百零一年：九百輛。"],[2,"三、一百零二年：七百輛。"],[2,"四、一百零三年：五百輛。"],[2,"五、一百零四年：三百輛。"]]},{"no":"83-1","label":"第 83-1 條","lines":[[0,"動力機械應依下列規定向公路監理機關申請登記領用牌證："],[2,"一、繳驗公司或行號登記證明文件及檢附動力機械來歷憑證、諸元規格資料、加註尺度之照片。"],[2,"二、前條第一項第二款動力機械應符合下列規定："],[3,"（一）以裝有輪胎且方向盤在左側及確實無法使用車輛載運者為限。但於中華民國一百零四年十二月三十一日以前進口者，其方向盤得非在左側。"],[3,"（二）裝置符合規定之帶狀反光標識、輪廓邊界標識燈、照後鏡、照地鏡及防止捲入裝置。"],[3,"（三）屬職業安全衛生法規定之危險性機械者，應檢附勞動檢查機構核發之檢查合格證明。"],[2,"三、前條第一項第三款配衡型堆高機應符合下列規定："],[3,"（一）以專門從事營運起重運搬或安裝，並依法登記設立且營業登記項目為機械安裝業或起重工程業為限。"],[3,"（二）檢附有貨叉可收折裝置、四路行車紀錄器（配有紅外線超廣角夜視鏡頭，具防震、防塵功能且其解析度達HD以上畫質）、三邊盲區偵測雷達且感應距離達五公尺、方向與倒車語音警示器、三邊紅光線條警示燈、箭頭紅光指示燈、頭燈、行駛警示燈及反光貼紙之證明文件。"],[3,"（三）檢附取得勞動部認可之檢定機構或經國內認證組織認證之檢測實驗室核發之檢測合格證書。"],[0,"動力機械轉讓時，應由受讓人向公路監理機關申請變更登記。"],[0,"動力機械應依前條第二項及下列規定申請核發臨時通行證："],[2,"一、已向公路監理機關申請登記領用牌證者為限。"],[2,"二、應檢附依法領有公司、商業或工廠登記證明文件之合法汽車修理業者出具四個月內保養紀錄表，其保養檢查項目如附件十八；屬配衡型堆高機者，其保養檢查項目如附件十八之一。"],[2,"三、應檢附第一項第二款第三目或第一項第三款第三目規定之檢查合格證明或檢測合格證書。"],[2,"四、顯有損壞道路、橋梁之虞者，不得核發臨時通行證。"],[2,"五、配衡型堆高機申請行駛之道路距離以三公里以下為限。"],[0,"動力機械牌證之型式、顏色、編號及種類由交通部會商相關機關訂定之。"]],"attachment":true},{"no":"83-2","label":"第 83-2 條","lines":[[0,"動力機械行駛於道路時，其駕駛人必須領有小型車以上之駕駛執照。但自中華民國九十六年一月一日起，總重量逾三點五公噸之動力機械，其駕駛人應領有大貨車以上之駕駛執照；自中華民國一百零一年一月一日起，重型及大型重型之動力機械，其駕駛人應領有聯結車駕駛執照。"],[0,"動力機械行駛於道路時，除應依臨時通行證所核定之路線、時間、速限行駛外，並應遵守下列規定："],[2,"一、遵守道路交通標誌、標線、號誌之指示、警告、禁制規定，並服從交通指揮人員之指揮。"],[2,"二、動力機械牌證應懸掛固定於前後端之明顯適當位置；駕駛人並應攜帶臨時通行證。"],[2,"三、配衡型堆高機貨叉應收折。"],[2,"四、在同向二車道以上之道路，應行駛於最外側車道，並不得直接左轉。"],[2,"五、不得運載貨物及牽引拖曳，並不得搭載駕駛艙座位以外之人員。"],[2,"六、日間並應開啟頭燈及輪廓邊界標識燈；配衡型堆高機並應全時開啟行車紀錄器、方向與倒車語音警示器、三邊盲區感應雷達、三邊紅光線條警示燈、箭頭紅光指示燈、頭燈及行駛警示燈。"],[2,"七、屬第八十三條第一項第二款大型重型動力機械或方向盤非在左側之重型動力機械，應配備標識前導及後衛之車輛隨行。方向盤非在左側之普通動力機械，自中華民國一百二十五年一月一日起，亦同。"],[2,"八、應遵守本章汽車行駛管理各項規定。"]]},{"no":"83-3","label":"第 83-3 條","lines":[[0,"非屬汽車、動力機械及個人行動器具範圍之動力載具、動力運動休閒器材或其他相類之動力器具，不得於道路上行駛或使用。"]]},{"no":"84","label":"第 84 條","lines":[[0,"車輛裝載危險物品應遵守下列事項："],[2,"一、廠商貨主運送危險物品，應備具危險物品道路運送計畫書及安全資料表向起運地或車籍所在地公路監理機關申請核發臨時通行證，該臨時通行證應隨車攜帶之，其交由貨運業者運輸者，應會同申請，並責令駕駛人依規定之運輸路線及時間行駛。"],[2,"二、車頭及車尾應懸掛布質三角紅旗之危險標識，每邊不得少於三十公分。"],[2,"三、裝載危險物品車輛之左、右兩側及後方應懸掛或黏貼危險物品標誌及標示牌，其內容及應列要項如附件八。危險物品標誌及標示牌應以反光材料製作，運輸過程中並應不致產生變形、磨損、褪色及剝落等現象而能辨識清楚。"],[2,"四、裝載危險物品罐槽車之罐槽體，應依主管機關規定檢驗合格，並隨車攜帶有效之檢驗（查）合格證明書。"],[2,"五、運送危險物品之駕駛人或隨車護送人員應經專業訓練，並隨車攜帶有效之訓練證明書。"],[2,"六、裝載危險物品車輛應隨車攜帶未逾時效之滅火器，攜帶之數量比照第三十九條第一項第十二款有關大貨車攜帶滅火器之規定。"],[2,"七、應參照安全資料表及危險物品之性質，隨車攜帶適當之個人防護裝備。"],[2,"八、裝載危險物品應隨車攜帶所裝載物品之安全資料表，其格式及填載應依勞動部訂定之危害性化學品標示及通識規則之規定，且隨車不得攜帶非所裝載危險物品之安全資料表。"],[2,"九、行駛中罐槽體之管口、人孔及封蓋，以及裝載容器之管口及封蓋應密封、鎖緊。"],[2,"十、裝載之危險物品，應以嚴密堅固之容器裝置，且依危險物品之特性，採直立或平放，並應綑紮穩妥，不得使其發生移動。"],[3,"十一、危險物品不得與不相容之其他危險物品或貨物同車裝運；裝載爆炸物，不得同時裝載爆管、雷管等引爆物。"],[3,"十二、危險物品運送途中，遇惡劣天候時，應停放適當地點，不得繼續行駛。"],[3,"十三、裝卸時，除應依照危險物品之特性採取必要之安全措施外，並應小心謹慎，不得撞擊、磨擦或用力拋放。"],[3,"十四、裝載危險物品，應注意溫度、濕度、氣壓、通風等，以免引起危險。"],[3,"十五、裝載危險物品車輛停駛時，應停放於空曠陰涼場所，與其他車輛隔離，禁止非作業人員接近。並嚴禁在橋樑、隧道、火場一百公尺範圍內停車。"],[3,"十六、裝載危險物品如發現外洩、滲漏或發生變化，應即停車妥善處理，如發生事故或災變並應迅即通知貨主及警察機關派遣人員與器材至事故災變現場處理，以及通報相關主管機關。並於車輛前後端各三十公尺至一百公尺處豎立車輛故障標誌。"],[3,"十七、行經高速公路及快速公路時，除另有規定外，應行駛外側車道，並禁止變換車道。但行經公告之交流道區前後路段，得暫時利用緊鄰外側車道之車道超越前車。"],[0,"裝載危險物品車輛，行駛路線經高速公路時，接受申請之公路監理機關應依高速公路管理機關認可之路段、時段核發臨時通行證並以副本分送高速公路管理機關及公路警察機關。"],[0,"前二項所稱危險物品，係指歸屬於中華民國國家標準CNS 6864危險物運輸標示之危險物品、有害事業廢棄物、依毒性及關注化學物質管理法公告之第一類至第三類毒性化學物質、具有危害性之關注化學物質。"],[0,"輕型機車不得裝載危險物品，重型機車裝載液化石油氣之淨重未逾六十公斤及罐槽車以外之貨車裝載危險物品之淨重未逾下列數量者，得不適用第一項第一款至第七款規定："],[2,"一、氣體：五十公斤。"],[2,"二、液體：一百公斤。"],[2,"三、固體：二百公斤。"],[0,"車輛裝載第三項規定之危險物品，除應符合本條規定外，並應符合各目的事業主管機關所定相關法令及檢附各目的事業主管核准證明文件，始得向公路監理機關申請核發臨時通行證。"],[0,"危險物品道路運送計畫書及車輛裝載危險物品臨時通行證格式如附件三及四。"]],"attachment":true},{"no":"85","label":"第 85 條","lines":[[0,"汽車非經公路監理機關核准，不得擅自附掛拖車行駛。但故障車輛應以救濟車或適當車輛牽引，牽引裝置應牢固，兩車前後相隔距離不得超過五公尺，牽引車前端，故障車後端及牽引裝置應懸掛危險標識。"]]},{"no":"86","label":"第 86 條","lines":[[0,"貨車必須附載隨車作業人員者，除駕駛人外，應依下列規定，並須隨時注意行車安全。"],[2,"一、大貨車不得超過四人，小貨車不得超過二人。"],[2,"二、工程或公用事業機構人員，佩帶有服務單位之證章或其他明顯識別之標記者，搭乘大貨車不得超過二十人，小貨車不得超過八人。"],[2,"三、漁民攜帶大型捕魚工具，非客車所能容納者，搭載大貨車不得超過十六人，小貨車不得超過八人。"],[2,"四、大貨車載運劇團道具附載演員不得超過十六人，小貨車不得超過八人。"],[2,"五、大貨車載運魚苗附載拍水人員不得超過十二人。"],[2,"六、大貨車載運棺柩附載人員不得超過十六人。"],[2,"七、大貨車載運神轎附載人員不得超過十六人。"],[0,"前項附載人員連同裝載物不得超過核定之總重量，如貨車為廂型貨車時，應在車廂之內。框型貨車其裝載總高度已達三公尺之貨物上不得附載人員。"]]},{"no":"87","label":"第 87 條","lines":[[0,"客貨兩用車，應依下列規定："],[2,"一、載客與載貨空間應裝設固定式或隨車配附非固定式之間隔裝置，載貨空間之車窗應裝設固定式金屬欄杆。"],[2,"二、載人不得超過核定之人數，載貨不得超過核定之載重量，兼載客、貨時其載貨與載客空間，應完整裝置固定間隔，並不得超過核定之總重量。"],[0,"代用客車，應依下列規定："],[2,"一、代用大客車車身應為金屬或木製之固定廂式，車身設門及固定扶梯，加設立位者，應裝拉桿。"],[2,"二、代用小客車車身得為金屬或木製之固定廂式，後車門得加裝踏板，不須裝扶梯。但不得設立位。"],[2,"三、駕駛室與後車廂應隔開，代用客車如其中間或後車廂左右兩邊開有車窗者，應加裝金屬欄杆。"],[2,"四、車身內兩側設置固定翻動式座椅。"],[2,"五、載人不得超過核定之座位及立位人數，兼載客、貨時，不得超過核定之總重量。"],[0,"原經交通部車型審查通過之國內量產中之小客貨兩用車，自中華民國八十八年一月一日起出廠者，應符合第一項第一款及第三條第三款第二目後段之規定。"]]},{"no":"88","label":"第 88 條","lines":[[0,"機車附載人員或物品，應依下列規定："],[2,"一、載物者，小型輕型不得超過二十公斤；普通輕型不得超過五十公斤；重型不得超過八十公斤，高度不得超過駕駛人肩部，寬度不得超過把手外緣十公分，長度自座位後部起不得向前超伸，伸出車尾部分，自後輪軸起不得超過半公尺；具封閉式貨箱之電動三輪重型機車不得超過二百公斤，裝載貨物不得超出貨箱以外。"],[2,"二、小型輕型機車不得附載人員，重型及普通輕型機車在駕駛人後設有固定座位者，得附載一人。"],[2,"三、附載座人後，不得另載物品。但零星物品不影響駕駛人及附載人員之安全者，不在此限。"],[2,"四、附載座人不得側坐。"],[2,"五、駕駛人及附載座人均應戴安全帽。"],[2,"六、裝載容易滲漏、飛散、氣味惡臭之貨物，能防止其發洩者，應嚴密封固，裝置適當。"],[2,"七、附載座人、載運貨物必須穩妥，物品應捆紮牢固，堆放平穩。"],[0,"除駕艙機車外之機車駕駛人及附載座人應依下列規定配戴安全帽："],[2,"一、安全帽應為乘坐機車用之安全帽，經經濟部標準檢驗局檢驗合格，並於帽體貼有商品檢驗標識。"],[2,"二、帽體及相關配件必須齊全，並無毀損、鬆脫或變更之情事。"],[2,"三、配帶時安全帽應正面朝前及位置正確，於顎下繫緊扣環，安全帽並應適合頭形，穩固戴在頭上，不致上下左右晃動，且不可遮蔽視線。"],[0,"駕艙機車駕駛人及乘客應繫妥安全帶；其繫妥方式準用汽車駕駛人及乘客繫安全帶實施及宣導辦法相關規定。"]]},{"no":"89","label":"第 89 條","lines":[[0,"行車前應注意之事項，依下列規定："],[2,"一、方向盤、煞車、輪胎、燈光、雨刮、喇叭、照後鏡及依規定應裝設之行車紀錄器、載重計、轉彎及倒車警報裝置、行車視野輔助系統等須詳細檢查確實有效。"],[2,"二、行車執照、駕駛執照及其他依法令規定必須隨車攜帶之證件，均應攜帶。"],[2,"三、隨車工具須準備齊全。"],[2,"四、兒童須乘座於小客車之後座。"],[2,"五、駕駛人、前座、小型車後座及大客車車廂為部分或全部無車頂區域之乘客均應繫妥安全帶。"],[2,"六、起駛前應關閉汽車駕駛人視線範圍內之娛樂性顯示設備。但提供行車輔助顯示，不在此限。"],[2,"七、起駛前應顯示方向燈，注意前後左右有無障礙或車輛行人，並應讓行進中之車輛行人優先通行。"],[0,"前項第一款應裝設行車紀錄器之汽車，未依規定裝設或經檢查未能正確運作或未使用紀錄卡或未按時更換紀錄卡時，不得行駛。前段紀錄卡應妥善保存一年備查。"],[0,"第一項第一款應裝設載重計或轉彎、倒車警報裝置之車輛，未依規定裝設或經檢查未能正確運作或載重計其鉛封破損不完整時，不得行駛。"]]},{"no":"90","label":"第 90 條","lines":[[0,"駕駛人駕駛汽車，除應遵守道路交通標誌、標線、號誌之指示，並服從交通指揮人員之指揮外，並應遵守下列規定："],[2,"一、禁止操作或觀看娛樂性顯示設備。"],[2,"二、禁止操作行車輔助顯示設備。"],[2,"三、禁止以手持方式使用行動電話、電腦或其他相類功能裝置進行撥接、通話、數據通訊或其他有礙駕駛安全之行為。"],[0,"警備車、消防車及救護車之駕駛人，依法執行任務所必要或其他法令許可者，得不受前項第三款之限制。"]]},{"no":"91","label":"第 91 條","lines":[[0,"行車遇有轉向、減速暫停、讓車、倒車、變換車道等情況時所用之燈光及駕駛人之手勢，應依下列規定："],[2,"一、右轉彎時，應先顯示車輛前後之右邊方向燈光，或由駕駛人表示左臂向上，手掌向右微曲之手勢。"],[2,"二、左轉彎時，應先顯示車輛前後之左邊方向燈光，或由駕駛人表示左臂平伸，手掌向下之手勢。"],[2,"三、減速暫停時，應顯示燈光，或由駕駛人表示左臂向下垂伸，手掌向後之手勢。"],[2,"四、允讓後車超越時，應顯示右邊方向燈光，或由駕駛人表示左臂向下四五度垂伸，手掌向前並前後擺動之手勢。"],[2,"五、倒車時，應顯示倒車燈光，或由駕駛人表示左臂平伸，手掌向後並前後擺動之手勢。"],[2,"六、變換車道時，應先顯示欲變換車道方向之燈光或手勢。"],[0,"汽車行駛時，不得任意以迫近、驟然變換車道或其他不當方式，迫使他車讓道。"]]},{"no":"92","label":"第 92 條","lines":[[0,"汽車除有下列情事之一者外，不得按鳴喇叭："],[2,"一、行近急彎，上坡道頂端視距不良者。"],[2,"二、在郊外道路同一車道上行車欲超越前行車時。"],[2,"三、遇有緊急或危險情況時。"],[0,"前項按鳴喇叭，應以單響為原則，並不得連續按鳴三次，每次時間不得超過半秒鐘。"]]},{"no":"93","label":"第 93 條","lines":[[0,"行車速度，依速限標誌或標線之規定，無速限標誌或標線者，應依下列規定："],[2,"一、行車時速不得超過五十公里。但在設有快慢車道分隔線之慢車道，時速不得超過四十公里，未劃設車道線、行車分向線或分向限制線之道路，時速不得超過三十公里。"],[2,"二、行經設有彎道、坡路、狹路、狹橋、隧道、學校、醫院標誌之路段、道路施工路段、泥濘或積水道路、無號誌之交岔路口及其他人車擁擠處所，或因雨霧致視線不清或道路發生臨時障礙，均應減速慢行，作隨時停車之準備。"],[2,"三、應依減速慢行之標誌、標線或號誌指示行駛。"],[0,"消防車、救護車、警備車、工程救險車及毒性化學物質災害事故應變車執行任務時，得不受前項行車速度之限制，且於開啟警示燈及警鳴器執行緊急任務時，得不受標誌、標線及號誌指示之限制。"]]},{"no":"94","label":"第 94 條","lines":[[0,"汽車在同一車道行駛時，除擬超越前車外，後車與前車之間應保持隨時可以煞停之距離，不得任意以迫近或其他方式，迫使前車讓道。"],[0,"汽車除遇突發狀況必須減速外，不得任意驟然減速、煞車或於車道中暫停。前車如須減速暫停，駕駛人應預先顯示燈光或手勢告知後車，後車駕駛人應隨時注意前車之行動。"],[0,"汽車行駛時，駕駛人應注意車前狀況及兩車並行之間隔，並隨時採取必要之安全措施，不得在道路上蛇行，或以其他危險方式駕車。"],[0,"汽車行駛於大眾捷運系統車輛共用通行之車道時，聞或見大眾捷運系統車輛臨近之聲號或燈光時，應即依規定變換車道，避讓其優先通行，並不得在後跟隨迫近。但道路主管機關另有規定者，不在此限。"]]},{"no":"95","label":"第 95 條","lines":[[0,"汽車除行駛於單行道或指定行駛於左側車道外，在未劃分向線或分向限制線之道路，應靠右行駛。但遇有特殊情況必須行駛左側道路時，除應減速慢行外，並注意前方來車及行人。"],[0,"四輪以上汽車、大型重型機車及駕艙機車在劃有快慢車道分隔線之道路行駛，除起駛、準備轉彎、準備停車或臨時停車，不得行駛慢車道。但設有快慢車道分隔島之道路不在此限。"]]},{"no":"96","label":"第 96 條","lines":[[0,"汽車在單行道行駛時，應在快車道上按遵行方向順序行駛，劃有路面邊線者，除起駛、準備停車或臨時停車外，不得駛出路面邊線。"]]},{"no":"97","label":"第 97 條","lines":[[0,"汽車在未劃設慢車道之雙向二車道行駛時，應依下列規定："],[2,"一、均應在遵行車道內行駛。"],[2,"二、在劃有分向限制線之路段，不得駛入來車之車道內。"],[2,"三、在劃有行車分向線之路段，超車時得駛越，但不能並行競駛。"],[2,"四、除準備停車或臨時停車外，不得駛出路面邊線。"],[0,"汽車在設有慢車道之雙向二車道，除應依前項各款規定行駛外，於快慢車道間變換車道時，應顯示方向燈，讓直行車先行，並注意安全距離。"]]},{"no":"98","label":"第 98 條","lines":[[0,"汽車在同向二車道以上之道路（車道數計算，不含車種專用車道、機車優先道及慢車道），除應依標誌或標線之指示行駛外，並應遵守下列規定："],[2,"一、大型汽車在同向三車道以上之道路，除準備左轉彎外，不得在內側車道行駛。"],[2,"二、小型汽車內外側車道均可行駛，行駛速度較慢時，應在外側車道行駛，但不得任意變換車道行駛。"],[2,"三、執行任務中之消防車、救護車、警備車、工程救險車，內外側車道均可行駛。"],[2,"四、由同向二車道進入一車道，應讓直行車道之車輛先行，無直行車道者，外車道之車輛應讓內車道之車輛先行。但在交通壅塞時，內、外側車道車輛應互為禮讓，逐車交互輪流行駛，並保持安全距離及間隔。"],[2,"五、除準備停車或臨時停車外，不得駛出路面邊線或跨越兩條車道行駛。"],[2,"六、變換車道時，應讓直行車先行，並注意安全距離。"],[0,"設有左右轉彎專用車道之交岔路口，直行車不得占用轉彎專用車道。"],[0,"汽車在調撥車道或雙向車道數不同之道路，除依第一項各款規定行駛外，並應依道路交通標誌、標線、號誌之指示行駛。"]]},{"no":"99","label":"第 99 條","lines":[[0,"機車行駛之車道，應依標誌或標線之規定行駛；無標誌或標線者，依下列規定行駛："],[2,"一、在未劃分快慢車道之道路，應在最外側二車道行駛；單行道應在最左、右側車道行駛。"],[2,"二、在已劃分快慢車道之道路，雙向道路應在最外側快車道及慢車道行駛；單行道道路應在慢車道及與慢車道相鄰之快車道行駛。"],[2,"三、變換車道時，應讓直行車先行，並注意安全距離。"],[2,"四、由同向二車道進入一車道，應讓直行車道之車輛先行，無直行車道者，外車道之車輛應讓內車道之車輛先行。但在交通壅塞時，內、外側車道車輛應互為禮讓，逐車交互輪流行駛，並保持安全距離及間隔。"],[2,"五、除起駛、準備停車或臨時停車外，不得駛出路面邊線。"],[2,"六、不得在人行道行駛。"],[0,"機車行駛至交岔路口，其轉彎，應依標誌或標線之規定行駛；無標誌或標線者，應依第一百零二條及下列規定行駛："],[2,"一、內側車道設有禁行機車標誌或標線者，應依兩段方式進行左轉，不得由內側或其他車道左轉。"],[2,"二、在三快車道以上單行道道路，行駛於右側車道或慢車道者，應以兩段方式進行左轉彎；行駛於左側車道或慢車道者，應以兩段方式進行右轉彎。"],[0,"機車不得在道路上蛇行，或僅以後輪著地或以其他危險方式駕車，亦不得拆除消音器或以其他方式造成噪音。"],[0,"執行任務之警備或巡邏機車，得不受第一項、第二項及第九十九條之一之限制；並得行駛快速公路、市區快速道路，不受標誌或標線之限制，但應開啟警示燈。"]]},{"no":"99-1","label":"第 99-1 條","lines":[[0,"大型重型機車及駕艙機車，比照小型汽車適用其行駛規定。但另設有標誌、標線或號誌特別管制者，應依其指示行駛。"]]},{"no":"100","label":"第 100 條","lines":[[0,"汽車交會時，應依下列規定："],[2,"一、在未劃有分向標線之道路，或鐵路平交道，或不良之道路交會時，應減速慢行。"],[2,"二、在山路交會時，靠山壁車輛應讓道路外緣車優先通過。"],[2,"三、在峻狹坡路交會時，下坡車應停車讓上坡車先行駛過。但上坡車尚在坡下而下坡車已駛至坡道中途者，上坡車應讓下坡車駛過後，再行上坡。"],[2,"四、雙向車道上之單車道橋樑，設有號誌或行車管制人員者，應依其指示行駛；未設號誌或行車管制人員者，如同時有車輛自兩端行近橋口時，應先暫停並視情況，由一方亮停車燈或以手勢表示允讓後，他方始得行駛通過。"],[2,"五、會車相互之間隔不得少於半公尺。"],[2,"六、夜間會車應用近光燈。"],[2,"七、單車道之橋樑及隧道不得交會。"]]},{"no":"101","label":"第 101 條","lines":[[0,"汽車超車時，應依下列規定："],[2,"一、行經設有彎道、陡坡、狹橋、隧道、交岔路口標誌之路段或鐵路平交道、道路施工地段，不得超車。"],[2,"二、在設有學校、醫院標誌或其他設有禁止超車標誌、標線之處所、地段或對面有來車交會或前行車連貫二輛以上者，不得超車。"],[2,"三、欲超越同一車道之前車時，須先按鳴喇叭二單響或變換燈光一次，不得連續密集按鳴喇叭或變換燈光迫使前車允讓。"],[2,"四、前行車駕駛人聞後行車按鳴喇叭或見後行車顯示超車燈光時，如車前路況無障礙，應即減速靠邊或表示允讓，並注意後行車超越時之行駛狀況。"],[2,"五、前行車減速靠邊或以手勢或亮右方向燈表示允讓後，後行車始得超越。超越時應顯示左方向燈並於前車左側保持半公尺以上之間隔超過，行至安全距離後，再顯示右方向燈駛入原行路線。"],[0,"汽車遇幼童專用車、校車、身心障礙者用特製車、教練車或執行道路駕駛考驗之考驗用車時，應予禮讓。"],[0,"汽車聞有消防車、救護車、警備車、工程救險車、毒性化學物質災害事故應變車等執行緊急任務車輛之警號時，應依下列規定避讓行駛："],[2,"一、聞有執行緊急任務車輛之警號時，不論來自何方，均應立即避讓，並不得在後跟隨急駛、併駛或超越，亦不得駛過在救火時放置於路上之消防水帶。"],[2,"二、在同向或雙向僅有一車道之路段，應即減速慢行向右緊靠道路右側避讓，並暫時停車於適當地點，供執行緊急任務車輛超越。"],[2,"三、在同向二車道以上路段，與執行緊急任務車輛同車道之前車，應即向相鄰車道或路側避讓，相鄰車道之車輛應減速配合避讓，並作隨時停車之準備。"],[2,"四、執行緊急任務車輛得利用相鄰二車道間之車道線行駛，而在車道線左右兩側車道之車輛，應即減速慢行分向左右兩側車道避讓，並作隨時停車之準備。"],[2,"五、執行緊急任務車輛行經交岔路口時，已進入路口之車輛應駛離至不妨害執行緊急任務車輛行進動線之地點；同向以外未進入路口車輛應減速暫停，不得搶快進入路口，以避讓執行緊急任務車輛先行。"]]},{"no":"102","label":"第 102 條","lines":[[0,"汽車行駛至交岔路口，其行進、轉彎，應依下列規定："],[2,"一、應遵守燈光號誌或交通指揮人員之指揮，遇有交通指揮人員指揮與燈光號誌並用時，以交通指揮人員之指揮為準。"],[2,"二、行至無號誌或號誌故障而無交通指揮人員指揮之交岔路口，支線道車應暫停讓幹線道車先行。未設標誌、標線或號誌劃分幹、支線道者，少線道車應暫停讓多線道車先行；車道數相同時，轉彎車應暫停讓直行車先行；同為直行車或轉彎車者，左方車應暫停讓右方車先行。但在交通壅塞時，應於停止線前暫停與他方雙向車輛互為禮讓，交互輪流行駛。"],[2,"三、由同向二車道進入一車道，應讓直行車道之車輛先行，無直行車道者，外車道之車輛應讓內車道之車輛先行。但在交通壅塞時，內、外側車道車輛應互為禮讓，逐車交互輪流行駛，並保持安全距離及間隔。"],[2,"四、右轉彎時，應距交岔路口三十公尺前顯示方向燈或手勢，換入外側車道、右轉車道或慢車道，駛至路口後再行右轉。但由慢車道右轉彎時應於距交岔路口三十至六十公尺處，換入慢車道。"],[2,"五、左轉彎時，應距交岔路口三十公尺前顯示方向燈或手勢，換入內側車道或左轉車道，行至交岔路口中心處左轉，並不得占用來車道搶先左轉。"],[2,"六、設有劃分島劃分快慢車道之道路，在慢車道上行駛之車輛不得左轉，在快車道行駛之車輛不得右轉彎。但另設有標誌、標線或號誌管制者，應依其指示行駛。"],[2,"七、轉彎車應讓直行車先行。"],[2,"八、對向行駛之左右轉車輛已轉彎須進入同一車道時，右轉彎車輛應讓左轉彎車輛先行，如進入二以上之車道者，右轉彎車輛應進入外側車道，左轉彎車輛應進入內側車道。"],[2,"九、行至無號誌之圓環路口時，應讓已進入圓環車道之車輛先行。"],[2,"十、行經多車道之圓環，應讓內側車道之車輛先行。"],[3,"十一、交岔路口因特殊需要另設有標誌、標線者，並應依其指示行車。"],[3,"十二、行至有號誌之交岔路口，遇紅燈應依車道連貫暫停，不得逕行插入車道間，致交通擁塞，妨礙其他車輛通行。"],[3,"十三、行至有號誌之交岔路口，遇有前行或轉彎之車道交通擁塞時，應在路口停止線前暫停，不得逕行駛入交岔路口內，致號誌轉換後，仍未能通過妨礙其他車輛通行。"],[0,"前項第二款之車道數，以進入交岔路口之車道計算，含快車道、慢車道、左、右轉車道、車種專用車道、機車優先道及調撥車道。"],[0,"同向有二以上之車道者，左側車道為內側車道，右側車道為外側車道。"]]},{"no":"103","label":"第 103 條","lines":[[0,"汽車行近未設行車管制號誌之行人穿越道前，應減速慢行。"],[0,"汽車行近行人穿越道，遇有行人穿越、攜帶白手杖或導盲犬之視覺功能障礙者時，無論有無交通指揮人員指揮或號誌指示，均應暫停讓行人、視覺功能障礙者先行通過。"],[0,"汽車行近未劃設行人穿越道之交岔路口，遇有行人、攜帶白手杖或導盲犬之視覺功能障礙者穿越道路時，無論有無交通指揮人員指揮或號誌指示，均應暫停讓行人、視覺功能障礙者先行通過。"],[0,"汽車行駛於行人優先區，應依速限減速慢行，不得危及行人安全或阻礙行人通行，並應暫停讓行人先行通過。"]]},{"no":"104","label":"第 104 條","lines":[[0,"汽車行駛中，駕駛人看到鐵路平交道標誌或標線後，應即將速度減低至時速十五公里以下，接近平交道時，應依下列規定："],[2,"一、鐵路平交道設有遮斷器或看守人員管理者，如警鈴已響、閃光號誌已顯示或遮斷器已開始放下或看守人員表示停止時，應即暫停，俟遮斷器開放或看守人員表示通行後，始得通過。如遮斷器未放下或看守人員未表示停止時，仍應看、聽鐵路兩方無火車駛來，始得通過。"],[2,"二、鐵路平交道設有警鈴及閃光號誌者，警鈴已響，閃光號誌已顯示，駕駛人應暫停俟火車通過後，看、聽鐵路兩方確無火車駛來，始得通過。如警鈴未響，閃光號誌未顯示，仍應看、聽鐵路兩方無火車駛來，始得通過。"],[2,"三、鐵路平交道上無看守人員管理或無遮斷器、警鈴、閃光號誌之設備者駕駛人應在軌道外三至六公尺前暫停、看、聽鐵路兩方無火車來時，始得通過。"],[0,"汽車駛至鐵路平交道前，如前面有車輛時，應俟前車駛離鐵路平交道適當距離而後車能安全通過後，始得通過。"]]},{"no":"104-1","label":"第 104-1 條","lines":[[0,"汽車行駛至有大眾捷運系統車輛共用通行之交岔路口，除應依標誌、標線或號誌之指示行駛外，並應遵守下列規定："],[2,"一、行至設有聲光號誌之交岔路口，警鈴已響，閃光號誌已顯示，駕駛人應暫停俟大眾捷運系統車輛通過後，看、聽兩方無大眾捷運系統車輛駛來，始得通過。"],[2,"二、行至聲光號誌故障而無交通指揮人員指揮之交岔路口時，駕駛人應暫停、看、聽兩方無大眾捷運系統車輛駛來，始得通過。"]]},{"no":"105","label":"第 105 條","lines":[[0,"汽車行駛於高速公路、快速公路或設站管制之道路，應遵守其管制之規定。"]]},{"no":"106","label":"第 106 條","lines":[[0,"汽車迴車時，應依下列規定："],[2,"一、在設有彎道、坡路、狹路、狹橋、隧道標誌之路段或鐵路平交道不得迴車。"],[2,"二、在設有禁止迴車標誌或劃有分向限制線，禁止超車線、禁止變換車道線之路段，不得迴車。"],[2,"三、禁止左轉路段，不得迴車。"],[2,"四、行經圓環路口，除設有專用迴車道者外，應繞圓環迴車。"],[2,"五、汽車迴車前，應暫停並顯示左轉燈光或手勢，看清無來往車輛，並注意行人通過，始得迴轉。"],[2,"六、聯結車不得迴轉。"]]},{"no":"107","label":"第 107 條","lines":[[0,"汽車行經坡道，上坡時不得蛇行前進，下坡時不得將引擎熄火，空檔滑行。"]]},{"no":"108","label":"第 108 條","lines":[[0,"汽車行經渡口時，應依下列規定："],[2,"一、除有特別規定外，應按指定碼頭及到達先後次序過渡，不得爭先搶渡。"],[2,"二、待渡車輛，須靠路邊右側停放，順序排列。"],[2,"三、待渡車輛駕駛人員，應坐於駕駛室內，受渡口管理人員之調度，嚴守秩序。"],[2,"四、客車過渡，乘客一律下車。"],[2,"五、貨車過渡，其總重量超過渡船規定之重量者，須將逾重物品卸下，分別渡過。"]]},{"no":"109","label":"第 109 條","lines":[[0,"汽車行駛時，應依下列規定使用燈光："],[2,"一、夜間應開亮頭燈。"],[2,"二、行經隧道、調撥車道應開亮頭燈。"],[2,"三、遇濃霧、雨、雪、天色昏暗或視線不清時，應開亮頭燈。"],[2,"四、非遇雨、霧時，不得使用霧燈。"],[2,"五、行經公路主管機關或警察機關公告之山區或特殊路線之路段，涵洞或車行地下道，應依標誌指示使用燈光。"],[2,"六、夜間會車時，或同向前方一百公尺內有車輛行駛，除第一百零一條第三款之情形外，應使用近光燈。"],[0,"汽車駕駛人，應依下列規定使用方向燈："],[2,"一、起駛前應顯示方向燈。"],[2,"二、左（右）轉彎時，應先顯示車輛前後之左（右）邊方向燈光；變換車道時，應先顯示欲變換車道方向之燈光，並應顯示至完成轉彎或變換車道之行為。"],[2,"三、超越同一車道之前車時應顯示左方向燈並至與前車左側保持半公尺以上之間隔超過，行至安全距離後，再顯示右方向燈駛入原行路線。"]]},{"no":"110","label":"第 110 條","lines":[[0,"汽車倒車時，應依下列規定："],[2,"一、在設有彎道、狹路、坡路、狹橋、圓環、隧道、單行道標誌之路段或鐵路平交道、快車道、大眾捷運系統車輛共用通行交岔路口且為大眾捷運系統車輛導引路線上等危險地帶，不得倒車。但因讓車、停車或起駛有倒車必要者，不在此限。"],[2,"二、應顯示倒車燈光或手勢後，謹慎緩慢後倒，並應注意其他車輛及行人。"],[2,"三、大型汽車須派人在車後指引，如無人在車後指引時，應先測明車後有足夠之地位，並促使行人及車輛避讓。"]]},{"no":"111","label":"第 111 條","lines":[[0,"汽車臨時停車時，應依下列規定："],[2,"一、橋樑、隧道、圓環、障礙物對面、鐵路平交道、人行道、行人穿越道、快車道等處，不得臨時停車。"],[2,"二、交岔路口、公共汽車招呼站十公尺內、消防栓、消防車出入口五公尺內不得臨時停車。"],[2,"三、設有禁止臨時停車標誌、標線處所不得臨時停車。"],[2,"四、道路交通標誌前不得臨時停車。"],[2,"五、不得併排臨時停車。"],[0,"汽車臨時停車時，應依車輛順行方向緊靠道路邊緣，其前後輪胎外側距離緣石或路面邊緣不得逾六十公分。但大型車不得逾一公尺。"],[0,"大型重型機車及機車臨時停車時，應依車輛順行方向緊靠道路邊緣停放，其前輪或後輪外側距離緣石或路面邊緣不得逾四十公分。"]]},{"no":"112","label":"第 112 條","lines":[[0,"汽車停車時，應依下列規定："],[2,"一、禁止臨時停車處所不得停車。"],[2,"二、在設有彎道、險坡、狹路標誌之路段、槽化線、交通島或道路修理地段不得停車。"],[2,"三、機場、車站、碼頭、學校、娛樂、展覽、競技、市場或其他公共場所出、入口及消防栓之前，不得停車。"],[2,"四、設有禁止停車標誌、標線之處所不得停車。"],[2,"五、在設有身心障礙者專用停車標誌處所，非身心障礙者用車不得停放。"],[2,"六、汽車所有人、汽車買賣業或汽車修理業不得在道路上停放待售或承修之車輛。"],[2,"七、路邊劃有停放車輛線之處所不得停車營業。"],[2,"八、自用汽車不得於營業汽車招呼站停車。"],[2,"九、顯有妨礙其他人、車通行處所，不得停車。"],[2,"十、不得併排停車。"],[3,"十一、於坡道不得已停車時應切實注意防止車輛滑行。"],[3,"十二、停於路邊之車輛，遇視線不清時，或在夜間無燈光設備或照明不清之道路，均應顯示停車燈光或反光標識。"],[3,"十三、在停車場內或路邊准停車處所停車時，應依規定停放，不得紊亂。"],[3,"十四、一個小型車停車格位得停放一輛以上之大型重型機車。"],[3,"十五、駕艙機車得停放於小型車停車格位。"],[0,"汽車之停車時間、位置、方式及車種，如公路主管機關、市區道路主管機關或警察機關有特別規定時，應依其規定。"],[0,"汽車停車時應依車輛順行方向緊靠道路邊緣，其前後輪胎外側距離緣石或路面邊緣不得逾四十公分。"],[0,"大型重型機車及機車停車時，應依車輛順行方向緊靠道路邊緣平行、垂直或斜向停放，其前輪或後輪外側距離緣石或路面邊緣不得逾三十公分。但公路主管機關、市區道路主管機關或警察機關另有特別規定時，應依其規定。"],[0,"汽車發生故障不能行駛，應即設法移置於無礙交通之處，在未移置前或移置後均應依下列規定豎立車輛故障標誌，車輛駛離現場時，應即拆除："],[2,"一、在行車時速四十公里以下之路段，應豎立於車身後方五公尺至三十公尺之路面上，車前適當位置得視需要設置。"],[2,"二、在行車時速逾四十公里之路段，應豎立於車身後方三十公尺至一百公尺之路面上，車前適當位置得視需要設置。"],[2,"三、交通擁擠之路段，應懸掛於車身之後部，車前適當位置得視需要設置。"],[0,"汽車臨時停車或停車，汽車駕駛人或乘客開啟或關閉車門時，應遵守下列規定："],[2,"一、應於汽車停妥後開啟或關閉車門。"],[2,"二、乘客應由右側開啟或關閉車門，但在單行道准許左側停車者，應由左側開啟或關閉車門。車輛後方設有輪椅置放區者得由後方開啟或關閉車門。"],[2,"三、應注意行人、其他車輛，並讓其先行。"],[2,"四、確認安全無虞後，再將車門開啟至可供出入幅度，迅速下車並關上車門。"]]},{"no":"113","label":"第 113 條","lines":[[0,"消防車、警備車、救護車、工程救險車、外交部禮賓車、公用事業機構之工程車、垃圾車及傳遞郵件電報等車輛，於執行任務時，其臨時停車及停車地點得不受前二條之限制。但公路主管機關、市區道路主管機關或警察機關另有特別規定者，應依其規定。"]]},{"no":"113-1","label":"第 113-1 條","lines":[[0,"古董車行駛道路應依下列規定："],[2,"一、古董車僅限星期日、紀念日或其他休息日行駛。但為參加車輛相關活動、辦理定期檢驗或臨時檢驗，並經公路監理機關許可者，不在此限。"],[2,"二、古董車除公路主管或市區道路主管機關有特別規定，或經車籍所在地之公路監理機關許可外，應於車籍所在地直轄市、縣（市）道路範圍內行駛，且不得行駛於高速公路及快速公路。但經高速公路及快速公路主管機關許可者，不在此限。"]]},{"no":"114","label":"第 114 條","lines":[[0,"汽車駕駛人有下列情形之一者，不得駕車："],[2,"一、連續駕車超過八小時。"],[2,"二、飲用酒類或其他類似物後其吐氣所含酒精濃度達每公升零點一五毫克或血液中酒精濃度達百分之零點零三以上。"],[2,"三、吸食毒品、迷幻藥、麻醉藥品或其相類似管制藥品。"],[2,"四、患病影響安全駕駛。"],[2,"五、計程車駕駛人未向警察機關請領執業登記證，或雖已領有而未依規定放置車內指定之插座。"]]}]},{"title":"第 五 章 慢車","articles":[{"no":"115","label":"第 115 條","lines":[[0,"其他慢車未依規定向直轄市、縣（市）政府辦理登記，領取證照，不得行駛道路。"],[0,"前項之證照，駕駛人應隨身攜帶。"]]},{"no":"115-1","label":"第 115-1 條","lines":[[0,"電動輔助自行車應經檢測及型式審驗合格，並黏貼審驗合格標章後，始得行駛道路。"]]},{"no":"115-2","label":"第 115-2 條","lines":[[0,"微型電動二輪車應經檢測及型式審驗合格，取得安全審驗合格證明書，並登記、領用、懸掛牌照後，始得行駛道路。"],[0,"微型電動二輪車牌照之型式、顏色及編號由交通部定之。"],[0,"微型電動二輪車牌照包括號牌及行車執照，為行車之許可憑證，由微型電動二輪車所有人向公路監理機關申請登記，經繳清其違反道路交通管理處罰條例第二章、第三章尚未結案之罰鍰，並實車查核與來歷證件相符後發給之。"],[0,"微型電動二輪車所有人申請新領牌照登記應依下列規定繳驗證明文件，經公路監理機關實車查核後，發給牌照："],[2,"一、第十六條第一項第一款至第四款之證明文件。"],[2,"二、繳驗車輛來歷證明："],[3,"（一）國內製造之車輛，應繳驗車輛出廠證明及統一發票。"],[3,"（二）進口之車輛，應繳驗海關進口與貨物稅完免稅照證及統一發票。"],[2,"三、安全審驗合格證明書。"],[0,"原微型電動二輪車所有人委託微型電動二輪車買賣業代辦過戶者，準用第十六條第二項申請異動登記規定。"],[0,"第四項實車查核，公路監理機關得委託製造業及進口商。"],[0,"微型電動二輪車出廠五年以上，辦理轉讓過戶，應向公路監理機關申請實施實車查核。"]]},{"no":"115-3","label":"第 115-3 條","lines":[[0,"微型電動二輪車號牌每車一面，應正面懸掛於車輛後端之明顯適當位置。"],[0,"微型電動二輪車牌照不得偽造、變造或矇領，並不得借供他車使用或使用他車牌照行駛。"],[0,"微型電動二輪車號牌不得變造損毀、塗抹或黏貼其他材料、加裝邊框或霓虹燈、裝置旋轉架、顛倒懸掛或以安裝其他器具之方式使不能辨認其牌號，並不得以他物遮蔽，如有污穢，致不能辨認其牌號時，應洗刷清楚。號牌有裁剪或扭曲懸掛者，以損毀號牌論。"]]},{"no":"115-4","label":"第 115-4 條","lines":[[0,"微型電動二輪車辦理過戶、變更車輛所有人名稱、地址、報廢、繳銷牌照或註銷牌照時，應向公路監理機關申請異動登記。"]]},{"no":"115-5","label":"第 115-5 條","lines":[[0,"微型電動二輪車牌照之登記主體不存在或不需使用時，準用第三十二條第一項、第二項及第三十三條第一項至第三項之申請異動登記規定。"]]},{"no":"115-6","label":"第 115-6 條","lines":[[0,"微型電動二輪車所有人辦理失竊註銷牌照及尋獲後重行申領牌照，準用第三十三條第四項及第五項之申請異動登記規定。"]]},{"no":"115-7","label":"第 115-7 條","lines":[[0,"微型電動二輪車駕駛人應依下列規定配戴安全帽："],[2,"一、安全帽應為乘坐機車用或自行車用之安全帽，經經濟部標準檢驗局檢驗合格，並於帽體貼有商品檢驗標識。"],[2,"二、帽體及相關配件必須齊全，並無毀損、鬆脫或變更之情事。"],[2,"三、配戴時安全帽應正面朝前及位置正確，於顎下繫緊扣環，安全帽並應適合頭形，穩固戴在頭上，不致上下左右晃動，且不可遮蔽視線。"]]},{"no":"116","label":"第 116 條","lines":[[0,"各直轄市、縣（市）政府因地方交通發展，對各種慢車認為須予淘汰者，報請行政院核定後公告禁止行駛。"]]},{"no":"117","label":"第 117 條","lines":[[0,"（刪除）"]]},{"no":"118","label":"第 118 條","lines":[[0,"（刪除）"]]},{"no":"119","label":"第 119 條","lines":[[0,"慢車不得擅自變更裝置，並應保持煞車、鈴號、燈光及反光裝置等安全設備之良好與完整。"],[0,"電動輔助自行車及微型電動二輪車之安全設備，應符合電動輔助自行車及微型電動二輪車安全檢測基準，不得擅自增、減、變更電子控制裝置或原有規格。"],[0,"其他慢車，其安全設備應符合直轄市、縣（市）政府依道路交通管理處罰條例第六十九條第三項、第四項授權另定之管理辦法規定。"],[0,"慢車擅自加裝補助引擎或馬達行駛者，依汽車之拼裝車輛處理。"]]},{"no":"120","label":"第 120 條","lines":[[0,"慢車駕駛人有下列情事之一者，不得駕駛或推拉車輛："],[2,"一、患有妨害作業之疾病。"],[2,"二、身心狀況或體力不能對所駕車輛為正常之控制。"],[2,"三、飲用酒類或其他類似物後其吐氣所含酒精濃度達每公升零點一五毫克或血液中酒精濃度達百分之零點零三以上。"],[0,"慢車行駛於道路時，駕駛人不得以手持方式使用行動電話、電腦或其他相類功能裝置進行撥接、通話、數據通訊或其他有礙駕駛安全之行為。"]]},{"no":"121","label":"第 121 條","lines":[[0,"（刪除）"]]},{"no":"122","label":"第 122 條","lines":[[0,"慢車之裝載，應依下列規定："],[2,"一、自行車不得附載坐人。但腳踏自行車或電動輔助自行車依規定附載一名幼童者，不在此限。"],[2,"二、自行車載物高度不得超過駕駛人肩部，重量不得超過二十公斤，長度不得伸出前輪，並不得伸出車後一公尺，寬度不得超過車把手。"],[2,"三、其他慢車載客不得超過二人。"],[2,"四、其他慢車載重不得超過五百公斤，高度不得超過駕駛人肩部，寬度不得伸出車身兩側，長度不得伸出車後二公尺。並不得附載乘客。"],[2,"五、手拉（推）貨車載重不得超過一千公斤，高度自地面起不得超過二．五公尺，寬度不得伸出車身兩側，連同載物全長不得超過四公尺。"],[2,"六、獸力行駛車輛載重不得超過二千公斤，高度自地面起不得超過二．五公尺，寬度不得伸出車身兩側，載物全長不得超過四公尺。"],[2,"七、裝載容易滲漏、飛散、有惡臭氣味及危險性之貨物，應予嚴密封固或適當裝置。"],[2,"八、裝載禽獸不得重疊或倒置。"],[2,"九、裝載貨物應捆紮結實。"],[0,"年滿十八歲駕駛人使用合格腳踏自行車或電動輔助自行車，並安裝合格兒童座椅之前座椅者，以附載一歲以上四歲以下且重量十五公斤以下幼童為限；其屬安裝後座椅者，以附載一歲以上六歲以下且重量二十二公斤以下幼童為限。"],[0,"腳踏自行車或電動輔助自行車應標示合格標章後始得依前項規定附載幼童行駛道路。"],[0,"第二項所稱合格腳踏自行車、電動輔助自行車及自行車兒童座椅係指符合附件二十三規定並標示合格標章者。"],[0,"附載幼童之腳踏自行車、電動輔助自行車、自行車兒童座椅製造商及進口商，應於其產品中文使用說明書中加註附載幼童之相關安全使用注意事項。"]],"attachment":true},{"no":"123","label":"第 123 條","lines":[[0,"慢車上下乘客或裝卸貨物，應緊靠路邊，不得妨礙交通。但公路主管機關、市區道路主管機關或警察機關對停車之時間、地點有特別規定者，應依其規定。"]]},{"no":"124","label":"第 124 條","lines":[[0,"慢車起駛前應注意前後左右有無障礙或車輛行人，並應讓行進中之車輛行人優先通行。"],[0,"慢車行駛，應遵守道路交通標誌、標線、號誌之指示，並服從交通指揮人員之指揮。"],[0,"慢車行駛之車道，應依標誌或標線之規定行駛；無標誌或標線者，應依下列規定行駛："],[2,"一、應在劃設之慢車道上靠右順序行駛，在未劃設慢車道之道路，應靠右側路邊行駛。但公路主管機關、市區道路主管機關或警察機關對行駛地區、路線或時間有特別規定者，應依其規定。"],[2,"二、單行道道路應在最左、右側車道行駛。"],[2,"三、不得侵入快車道或人行道行駛。"],[2,"四、不得在禁止穿越地段穿越道路。"],[0,"慢車在同一車道行駛時，後車與前車之間應保持隨時可以煞停之距離；變換車道時，應讓直行車先行，並應注意安全之距離。"],[0,"慢車行駛時，駕駛人應注意車前狀況及與他車行駛間隔，並隨時採取必要之安全措施。"]]},{"no":"124-1","label":"第 124-1 條","lines":[[0,"公路主管機關、市區道路主管機關或警察機關得在不妨礙通行或行車安全無虞之原則，於人行道設置必要之標誌或標線供慢車行駛。慢車應依標誌或標線之指示行駛，並應讓行人優先通行。"]]},{"no":"125","label":"第 125 條","lines":[[0,"慢車行駛至交岔路口，其行進或轉彎，應依標誌、標線或號誌之規定行駛，無標誌、標線或號誌者，應依第一百零二條及下列規定行駛："],[2,"一、直行時，應順其遵行方向直線通過，不得蛇行搶先。"],[2,"二、右轉彎時，應靠右側路邊右轉。但行駛於二車道以上之單行道左側車道或左側慢車道者，應採兩段方式右轉。"],[2,"三、左轉彎時，應繞越道路中心處左轉進入規定行駛車道內行進。但行駛於同向二車道以上之單行道右側車道或右側慢車道者，應依兩段方式進行左轉。"],[2,"四、在設有交通島劃分行車方向或快慢車道之道路行駛，不得左轉。"],[2,"五、應讓行人優先通行。"],[0,"慢車迴車時，除應依第一百零六條規定外，迴車前並應暫停，看清無來往車輛，並注意行人通過，始得迴轉。"]]},{"no":"126","label":"第 126 條","lines":[[0,"慢車行近行人穿越道或未劃設行人穿越道之交岔路口，遇有行人穿越、攜帶白手杖或導盲犬之視覺功能障礙者時，無論有無交通指揮人員指揮或號誌指示，均應暫停讓行人、視覺功能障礙者先行通過。"],[0,"慢車行駛於行人優先區，應依速限減速慢行，不得危及行人安全或阻礙行人通行，並應暫停讓行人先行通過。"],[0,"慢車行駛，不得爭先、爭道、並行競駛或以其他危險方式駕駛。"],[0,"慢車超車時，應在慢車道可容超越前車之處，沿前車左邊超越，再駛入原行路線。"],[0,"第三項所稱之其他危險方式駕駛，如包括吸食毒品、迷幻藥、麻醉藥品或其相類似管制藥品，或服用藥物不能對所駕車輛為正常控制等之駕駛行為。"],[0,"慢車行駛於大眾捷運系統車輛共用通行之車道時，聞或見大眾捷運系統車輛臨近之聲號或燈光時，應即依規定變換車道，避讓其優先通行，並不得在後跟隨迫近。但道路主管機關另有規定者，不在此限。"]]},{"no":"127","label":"第 127 條","lines":[[0,"慢車不得牽引其他車輛或攀附車輛隨行。"]]},{"no":"128","label":"第 128 條","lines":[[0,"慢車在夜間行駛應開啟燈光。"]]},{"no":"129","label":"第 129 條","lines":[[0,"慢車行駛或停止時，聞消防車、警備車、救護車、工程救險車、毒性化學物質災害事故應變車之警號，應立即靠道路右側避讓；於單行道應靠道路兩側避讓，並暫時停車於適當地點，供執行緊急任務車輛超越。"]]},{"no":"130","label":"第 130 條","lines":[[0,"慢車行經鐵路平交道，應依下列規定："],[2,"一、鐵路平交道設有遮斷器或看守人員管理者，如警鈴已響、閃光號誌已顯示或遮斷器已開始放下或看守人員表示停止時，應即靠邊暫停，俟遮斷器開放或看守人員表示通行後，始得通過。如遮斷器未放下或看守人員未表示停止時，仍應看、聽鐵路兩方無火車駛來，始得通過。"],[2,"二、鐵路平交道設有警鈴及閃光號誌者，警鈴已響，閃光號誌已顯示，駕駛人應靠邊暫停俟火車通過後，看、聽鐵路兩方確無火車駛來始得通過。如警鈴未響，閃光號誌未顯示，仍應看、聽鐵路兩方確無火車駛來，始得通過。"],[2,"三、鐵路平交道無看守人員管理或無遮斷器、警鈴、閃光號誌之設備者，駕駛人應靠邊暫停，看、聽鐵路兩方無火車駛來時，始得通過。"],[2,"四、在鐵路平交道上，不得超車、迴車、倒車或臨時停車。"]]},{"no":"130-1","label":"第 130-1 條","lines":[[0,"慢車行經大眾捷運系統車輛共用通行之交岔路口，除應依標誌、標線或號誌之指示行駛外，並應遵守下列規定："],[2,"一、行至設有聲光號誌之交岔路口，警鈴已響，閃光號誌已顯示，駕駛人應暫停俟大眾捷運系統車輛通過後，看、聽兩方無大眾捷運系統車輛駛來，始得通過。"],[2,"二、行至聲光號誌故障而無交通指揮人員指揮之交岔路口時，駕駛人應暫停、看、聽兩方無大眾捷運系統車輛駛來，始得通過。"]]},{"no":"131","label":"第 131 條","lines":[[0,"慢車不得任意停放，應在規定地點或劃設之標線以內，順序排列。"],[0,"在未設置自行車停車設施之處所，自行車得比照大型重型機車以外之機車停放。"]]},{"no":"132","label":"第 132 條","lines":[[0,"（刪除）"]]}]},{"title":"第 六 章 行人","articles":[{"no":"133","label":"第 133 條","lines":[[0,"行人應在劃設之人行道行走，在未劃設人行道之道路，應靠邊行走；於行人優先區行走時，可於道路全寬通行。"],[0,"行人不得在道路上任意奔跑、追逐、嬉戲或坐、臥、蹲、立，阻礙交通。"],[0,"行人聞消防車、救護車、警備車、工程救險車、毒性化學物質災害事故應變車等執行緊急任務車輛之警號，應立即避讓，不得阻礙執行緊急任務車輛動線；穿越道路時，已開始穿越者，如行進方向未影響該車輛通行，應迅速穿越；未開始穿越者應暫停，不得搶快穿越道路，以避讓執行緊急任務車輛先行。"]]},{"no":"134","label":"第 134 條","lines":[[0,"行人穿越道路，應依下列規定："],[2,"一、設有行人穿越道、人行天橋或人行地下道，必須經由行人穿越道、人行天橋或人行地下道穿越，不得在其一百公尺範圍內穿越道路。但行人行走於行人優先區不在此限。"],[2,"二、未設有前款設施之交岔路口，行人穿越道路之範圍，應於人行道之延伸線內；未設人行道，而有劃設停止線者，應於停止線前至路緣以內；未設有人行道及劃設停止線者，應於路緣延伸線往路段起算三公尺以內。"],[2,"三、在禁止穿越、劃有分向限制線、設有劃分島或護欄之路段或三快車道以上之單行道，不得穿越道路。"],[2,"四、行人穿越道路，有交通指揮人員指揮或有燈光號誌指示者，應依交通指揮人員之指揮或號誌之指示前進。無交通指揮人員指揮又無號誌指示者，應小心迅速通行。"],[2,"五、行人穿越道設有行人穿越專用號誌者，應依號誌之指示迅速穿越。"],[2,"六、在未設第一款行人穿越設施，亦非禁止穿越之路段穿越道路時，應注意左右無來車，始可小心迅速穿越。"]]},{"no":"135","label":"第 135 條","lines":[[0,"行人通過鐵路平交道，應依下列規定："],[2,"一、鐵路平交道設有遮斷器或看守人員管理或警鈴及閃光號誌者，如遮斷器已開始放下或看守人員表示停止或警鈴已響，閃光號誌顯示時，應即靠邊停止，不得通過。"],[2,"二、鐵路平交道無看守人員管理或無遮斷器警鈴閃光號誌之設備者，應看、聽鐵路兩方確無火車駛來，始得通過。"],[2,"三、行人如持有長形物品通過電氣化鐵路平交道時，其總高度不得高出軌面四公尺；各該平交道設有限高標誌者，依限高標誌之規定。"]]},{"no":"135-1","label":"第 135-1 條","lines":[[0,"行人通過大眾捷運系統車輛共用通行之交岔路口、行人穿越道及行人徒步區，除應依標誌、標線或號誌之指示通過外，並應遵守下列規定："],[2,"一、行至設有聲光號誌之交岔路口，聲光號誌已顯示時，應即靠邊停止，不得通過。"],[2,"二、行至聲光號誌故障而無交通指揮人員指揮之交岔路口時，應暫停、看、聽兩方無大眾捷運系統車輛駛來，始得通過。"]]},{"no":"136","label":"第 136 條","lines":[[0,"行人乘車時，應依下列規定："],[2,"一、購票或候車，應在適當地點或指定之區界內，按先後次序，排列等候，不得爭先恐後擾亂秩序。"],[2,"二、應按次序上下車，不得爭先擁擠。"],[2,"三、車未停妥，不得上下車。"],[2,"四、應由右側車門上下車。但在單行道准許左側停車者，應由左側車門上下車。"],[2,"五、車輛行駛中，不得攀登跳車或攀附隨行。"],[2,"六、乘車時，頭手不得伸出車外。"]]},{"no":"137","label":"第 137 條","lines":[[0,"行人結隊成行而行者，應靠路邊行進，並應依交通指揮人員之指揮或其所指定區間分段保持適當距離通行。"],[0,"民間婚、喪、喜慶、迎神賽會或其他類似之聚眾行為等須結隊成行通行者，應事先向警察機關申請核准。"]]},{"no":"138","label":"第 138 條","lines":[[0,"行人行走時遇有攜帶白色手杖或導盲犬之視覺功能障礙者時應禮讓其先行通過。"]]},{"no":"139","label":"第 139 條","lines":[[0,"父母或監護人不得疏縱未滿十四歲之人，擅自穿越車道，或於交通頻繁之道路或鐵路平交道附近任意奔跑、追逐、嬉戲或坐、臥、蹲、立，阻礙交通。"]]}]},{"title":"第 七 章 道路障礙","articles":[{"no":"140","label":"第 140 條","lines":[[0,"任何人不得有下列行為："],[2,"一、利用道路堆積、置放、設置或拋擲足以妨礙交通之物品。"],[2,"二、在道路兩旁附近燃燒物品，發生濃煙，妨礙行車視線。"],[2,"三、利用道路為工作場所。"],[2,"四、利用道路放置拖車、貨櫃或動力機械。"],[2,"五、未經許可在道路擺設攤位。"],[2,"六、擅自設置或變更道路交通標誌、標線、號誌或其他類似之標識。"],[2,"七、疏縱或牽繫畜、禽或寵物在道路奔走，妨害交通。"],[2,"八、在車道或交通島上散發廣告物、宣傳單或其相類之物。"],[2,"九、在車道上、車站內、高速公路服務區，任意販賣物品妨礙交通。"]]},{"no":"141","label":"第 141 條","lines":[[0,"興修房屋或其他工程，未經公路主管機關或市區道路主管機關許可，不得使用道路；其經許可者，不得超出限制。"]]},{"no":"142","label":"第 142 條","lines":[[0,"未經警察機關許可，不得在道路上舉行賽會、擺設筵席、拍攝影片、演戲、運動或其他類似之行為。"]]},{"no":"143","label":"第 143 條","lines":[[0,"挖掘道路，應事先向公路主管或市區道路主管機關申請許可，主管機關許可時，應知會當地警察機關；工程進行中，並應樹立警告標誌，夜間並安裝警告燈；工程完竣後，應立即撤除並將障礙物清除。"]]}]},{"title":"第 八 章 附則","articles":[{"no":"144","label":"第 144 條","lines":[[0,"有關汽車檢驗、登記、發照及駕駛人考驗、登記、發照，公路監理機關於必要時，得委託相關團體協助辦理，其委託作業及監督要點，由交通部另定之。"],[0,"前項各項業務所需各種書、表、證、照格式，由交通部另定之。"]]},{"no":"145","label":"第 145 條","lines":[[0,"（刪除）"]]},{"no":"146","label":"第 146 條","lines":[[0,"本規則施行日期另定之。"]]}]}],"attachments":[{"file_id":"0000236452","name":"附件一.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000236452&lan=C","fetched":true,"bytes":157496,"pages":4,"text":"1\n附件一\n一、凡以公司、行號名義申領自用大客、貨車牌照者，應依下列規定：\n（一）申請自用大客車牌照者，以員工人數為申請核發牌照標準，員工人數每滿四十\n人者，得申請發給自用大客車牌照一付，員工人數須以參加勞工保險，取得勞\n工保險局最近三個月之勞工保險費計算表之平均數證明為準，增加車輛請領牌\n照亦同。\n（二）申請自用大貨車牌照者，經公路監理機關核有需要，得核發牌照一付，毋需審\n查營業額。但第二次以後申請增車者，應提供最近二個月或最近一年之營業稅\n稅單，其最近二個月累計營業額或一年平均二個月營業額，每滿新臺幣二百萬\n元，准予發給牌照一付；其申請增領牌照之自用大貨車，總重量在十公噸以下\n者，發給牌照之營業額基準，折半計算。\n（三）新成立之公司、行號尚無法取得最近二個月營業額證明或原公司、行號計畫擴\n充業務，其最近二個月營業額無法達到規定標準者，為適應需要申請自用大\n客、貨車多輛者，應檢具證明（如登記資本額或增資證明，新攬工程或業務合\n約書、營運計畫書等）並敘明理由，經公路監理機關查核屬實後，核發牌照。\n（四）公司、行號與附設工廠在不同一公路監理機關轄區內，工廠得檢具公司或商業\n登記證明文件，最近二個月之營業額稅單，工廠登記證及停車場所證明申領牌\n照。\n（五）生產、運銷及消費合作社得依需要檢具正式登記證明文件、統一編號編配通知\n書及年度營利所得稅結算書，依第二款規定申請核發。\n二、人民團體、民間機構或私立學校申請自用大客、貨車牌照者，除人民團體中之政黨\n外，應經各該主管機關之同意，並依下列規定辦理，始予發照：\n（一）政黨應繳驗經該政黨之中央黨部取得內政部出具該政黨或其分支機構依法備案\n之證明文件，並須符合下列規定：\n1.應檢具載明申請單位名稱、申領大客車、大貨車之型式、使用目的及經常行\n駛地區之申請書。\n2.申請自用大客車牌照者，應檢附現有職（員）工名冊，其職（員）工人數每\n滿四十人者，得申請發給自用大客車牌照一付。申請增加車輛請領牌照時，\n亦同。\n3.申領自用大貨車牌照者，以一付為限。\n（二）政黨以外之人民團體、民間機構或私立學校申請者，準用前款規定之程序申領\n牌照。\n（三）依法辦妥設立登記之宗教團體，或慈善團體申領自用大客車牌照者，得準用第\n一款第一目之規定予以核發，但以一付為限。\n三、實際從事農林、漁、畜牧、養殖者，具備下列資格規定者，得申請發給總重十公噸\n以下之自用大貨車牌照一付：\n（一）申請人未領有自用小貨車牌照，並持有大車以上有效駕駛執照者。\n（二）實際從事農林者，應檢附耕地、牧場、園藝、林場土地所有權狀登記證明文\n\n2\n件，其面積達一公頃以上或零點七公頃以上有大型農用機械證明文件。\n（三）實際從事畜牧、養殖者，應檢具依法登記之同業協會或主管機關之證明文件。\n（四）實際從事漁業者，應檢附船舶登記證明文件。\n四、申請自用大客車、大貨車牌照者，應符合下列規定：\n（一）應檢具停車場所之土地所有人身分證明影本、土地所有權狀影本及土地登記\n謄本、地籍圖謄本等證明文件暨停車場平面關係位置圖。但以租用、借用者，\n應加附期限二年以上租借契約;自中華民國一百零五年一月一日起得免檢附\n土地登記謄本及地籍圖謄本。\n（二）應逐車備具停車場所，其設置面積，以車輛長、寬各加一公尺核計。\n（三）停車場所設置地點以公司與其分公司、辦事處、工廠之所在地或跨其鄰接之縣\n（市）為範圍。但標得二年以上公共工程合約者，得於該工程所在縣市設置停\n車場所。\n五、政府機關申領自用大客車、大貨車牌照，及依本規則第二條第一項第七款所規定之\n特種車申領牌照，不受本審核規定之限制。\n六、自用大客車、大貨車汰舊換新或轉讓時，應辦理牌照繳銷手續。牌照因繳銷、吊銷、\n註銷重領者，應重新繳驗各項證明，始予發照。公司合併者，其自用大客車、大貨\n車得以存續公司或另立之公司名義專案申請過戶登記。\n七、依本審核規定核發牌照之車輛，應分戶建檔（卡）登記，以供查處參考。\n八、公司、行號或團體申請自用大客、貨車牌照之申請書如附表。\n九、以融資性租賃方式申領自用大客、貨車牌照者，除依前列各點規定辦理外，應依下\n列規定辦理：\n（一）車輛出租人應檢具公司或商業登記證明文件（其營業項目應有「車輛租賃」\n等業務）及租賃合約副本，租用人並應檢具相關文件，共同向租用人所在地\n之公路監理機關申請核准申領牌照。\n（二）租賃合約之約定事項由出租人及租用人共同商定，其合約期間至少為兩年；\n惟租用人之停車場係租借用者，其停車場租借用期間不得少於車輛租賃期間。\n（三）受理申請之公路監理機關應以租用人名稱或其統一編號查核車輛車籍資料檔\n中之車輛主及租用人已有車輛數，據以核定申請案。\n（四）公路監理機關於核准該申請案時，除函復申請人外，應副知出租人所在地之\n公路監理機關，據以供出租人登檢領照；該項車輛並應登記租用人名稱、統\n一編號、地址及合約期間、核准文號等資料。\n（五）融資性租賃車輛之異動登記應由出租人申請辦理；惟異動項目如為租用人地\n址變更、車輛式樣，應由雙方共同向租用人所在地之公路監理機關申請核准\n後，再向出租人所在地之公路監理機關辦理。\n（六）租用人登記之主體已不存在，租用人所在地之公路監理機關應通知出租人所\n在地之公路監理機關依道路交通安全規則第三十二條第一項及第三十三條第\n一項及第二項核處。\n（七）租賃合約到期時，出租人所在地之公路監理機關依道路交通安全規則第三十\n\n3\n二條第一項及第三十三條第一項及第二項核處。\n（八）租賃合約到期前，得由出租人及租用人共同向租用人所在地之公路監理機關申\n請核准續約；公路監理機關於核定續約案時，不再查核本審核規定第一點第二\n款及第三款所列之規定。核准續約時應副知出租人所在地之公路監理機關。\n\n4\n\n                                            日期：         檔    號：\n                      文號：         保存年限：\n申請人\n全銜\n印章\n負責人\n印章\n地址\n\n電話\n\n統一編號\n\n應備文件\n\n\n申請資格\n□ 公司執照影本乙份（自耕農附身分證及大貸車駕照影本）\n□ 營利事業登記證影本乙份（第一次申領者需附正本查驗，獨資行號應檢具財稅機關編\n號之統一編號證明）\n□ 工廠登記證影本乙份（新車者請檢具車輛規格表）\n□ 汽車牌照登記書影本乙份\n□ 政黨相關證明文件及具結書均為正本\n□ 人民團體、民間機構或私立學校各該主管機關之同意文件乙份（正本）\n\n\n停車場\n□ 停車場位置圖乙份（需標示長寬、路名、門牌號碼）\n□ 土地所有權狀影本乙份及地政單位提供之地籍圖及土地登記謄本建物\n謄本正本（並需附所有人身分證影本）(自中華民國一百零五年一月一日起得免檢附\n土地登記謄本及地籍圖謄本)\n□ 同意書乙份\n□ 租約或借約乙份（停車場期限最少二年）\n※各項影本附件均需蓋公司（行號）負責人印鑑及簽註「本影本與正本相符無誤」等字樣\n營業額（大自貨車增車\n時間）二百萬元（十噸\n以下折半）第二車以上\n累計\n    （最近二個月）\n□ 月份營業額稅單共計            元                （影本二份）（公司行號適用）\n（增車者需附正本查）\n□ 大貨車行駛路線正本乙份（政黨適用）\n員工人數（申請自用大\n客車用）40人第二輛車\n以上累計\n□ 最近三個月勞保局保費計算表及繳款收據影本各乙份（公司行號適用）\n□ 政黨現有職（員）工名冊、黨證、派令及薪資所得憑證影本各乙份\n□ 大客車行駛路線圖正本乙份（政黨適用）\n\n車別數量\n      客\n自用大  車            輛\n      貨\n\n申請事項\n□ 新領         □ 過戶（請領新車者請\n附車輛型式規格表）\n□ 繳、吊、註銷重領\n\n車\n號\n\n原\n車\n主\n地\n址\n\n\n申請自用大客車、貨車牌照申請書"},{"file_id":"0000171864","name":"附件一.DOC","format":"DOC","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000171864&lan=C","fetched":true,"bytes":70656},{"file_id":"0000338938","name":"附件一之一自用小貨車牌照申領審核規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000338938&lan=C","fetched":true,"bytes":113759,"pages":3,"text":"附件一之一 自用小貨車牌照申領審核規定\n一、個人從事第二項規定行業，並領有小型車以上之有效駕駛執照者，\n得檢具下列證明文件之一，申領自用小貨車牌照一付：\n（一）所從事行業之職業工會出具之證明文件。\n（二）無固定僱主之流動工人應繳附所屬職業工會證明文件，如無\n法提出證明者，申領人應繳驗國民身分證正本及切結書。\n（三）實際從事農、漁、畜牧、養殖、種殖花卉園藝者，應檢附土\n地所有權狀或船舶登記、牧場、園藝、林場登記證明。申領\n者如無法提具本人之土地所有權狀者，依下列方式辦理：\n1.提具其直系血親或其配偶名義之土地所有權狀影本及戶籍\n謄本或國民身分證、戶口名簿等證明文件。\n2.經政府機關證明之耕地租約或記載權利種類為農育權設定\n及他項權利證明書。\n3.申領人經查證其配偶及配偶之父母無領用自用小貨車牌照，\n申領人得以其配偶父母之農地為幫農身分領用自用小貨車\n牌照。\n（四）攤販限由市場管理機關開具有案攤販證明。\n（五）個人名義同時申領自用大貨車、自用小貨車牌照者，僅得擇\n一辦理。\n下列行業，得依前項規定申領小貨車牌照：\n序號職業類別行業\n1\n農\n自耕農、半自耕農、佃農、幫農、自佃農、農牧業、僱農、\n農民、花農、佃耕、種花、農事雜工、蔬菜、稻作、種果\n樹、林業、雜糧、農耕、園藝。\n２\n畜牧養殖\n養牛、養豬、養羊、養漁、養蝦、養九孔、養雞、養鴨、養\n鵝、養兔、養蚵、養殖、養蜂。\n３\n漁\n漁民、漁夫、捕漁、漁業、什漁。\n４\n家庭手工藤類加工、竹類加工、編織工。\n５\n木工\n傢俱工、裝璜工、板模工、雕刻工。\n\n６\n水泥工\n泥水工、土水工、泥水匠、大理石工、磨石工。\n７\n油漆工\n噴漆工。\n８\n鐵工\n亞鉛工、鉗工、車床工、銑床工。\n９\n水電工\n水電技工、電焊工、冷凍工、空調維修工、氣焊工、水工、\n電工、電氣修理工、鑿井工。\n１０攤販\n小販、賣魚、賣肉、賣菜等。\n１１環保\n舊貨買賣業。\n１２推挖土工推土機工、挖土機工。\n１３其他\n清潔工、蛋類加工、餐飲業。\n二、以公司、行號名義申領自用小貨車牌照者，應依下列規定辦理：\n（一）申請三付以下自用小貨車牌照者，經公路監理機關核有需要，\n得免審查營業額發給牌照。\n（二）申領自用小貨車第四付牌照者，應提供最近二個月營業額之\n稅單或最近一年營業額稅單平均計算，每滿新臺幣五十萬元，\n准予發給牌照一付。但同時申領自用大貨車牌照者，其營業\n額應與其領用之第二付以上自用大貨車牌照一併計算。\n（三）汽車買賣業辦理自用小貨車過戶登記者，無需審查營業額。\n由公路監理機關於行照上加註「禁止裝載貨物營業及從事流\n動攤販」字樣。\n（四）新成立之公司、行號尚無法取得最近二個月營業額證明或原\n公司、行號計畫擴充業務，其最近二個月營業額無法達到規\n定標準者，為適應需要申請自用小貨車多輛者，應檢具證明\n（如登記資本額、增資證明、新攬工程或業務合約書或營運\n計畫書等）並敘明理由，經公路監理機關查核屬實後，核發\n牌照。\n三、生產、運銷及消費合作社得依需要檢具正式登記證明文件、統一編\n號編配通知書及年度營利所得稅結算書，依前點規定申請核發。\n四、政府機關申領自用小貨車牌照，及依本規則第二條第一項第七款所\n規定之特種車申領牌照，不受本審核規定之限制。\n\n五、人民團體、民間機構或私立學校申領自用小貨車牌照者，以一部為\n限。但有特殊需要者，得敘明實際情形，專案申請公路監理機關核\n辦。\n六、自用小貨車汰舊換新或轉讓時，應辦理牌照繳銷或過戶手續。牌照\n因繳銷、吊銷、註銷重領者，應重新繳驗各項證明，始予發照。公\n司合併者，其自用小貨車得以存續公司或另立之公司名義專案申請\n過戶登記。"},{"file_id":"0000209778","name":"附件一之一自用小貨車牌照申領審核規定.ODT","format":"ODT","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000209778&lan=C","fetched":true,"bytes":23155},{"file_id":"0000344704","name":"附件一之二 個人申領身心障礙者專用車輛牌照審核規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000344704&lan=C","fetched":true,"bytes":57853,"pages":1,"text":"附件一之二\n個人申領身心障礙者專用車輛牌照審核規定\n一、申領身心障礙者專用車輛牌照（以下簡稱專用牌照），應依本規則、本審\n核規定及身心障礙者權益保障相關法規辦理。\n二、申領專用牌照，應向車籍所轄公路監理機關為之。\n三、專用牌照得由經需求評估為行動不便之身心障礙者本人、配偶或一親等親\n屬、設於同一戶籍或同址分戶之二親等以上親屬一人自行選擇是否申領，\n不強制換發；惟僅能就專用牌照或專用停車位識別證，選擇其一，以利管\n理。在社政機關未取消核發專用停車位識別證前，申領專用牌照，須先由\n專用牌照受理機關向社政主管機關確認申請者未領用專用停車位識別證，\n始得核發。\n申請專用牌照之車輛種類為自用小貨車者，其車主及駕駛人應為身心\n障礙者本人。\n四、被限制申請專用停車位識別證者，不得申領專用牌照。\n五、身心障礙者本人領用專用牌照，以一人一車一付牌照為限；以載運身心障\n礙者為由，用身心障礙者之配偶、一親等親屬、設於同一戶籍或同址分戶\n之二親等以上親屬名義領用專用牌照者，以身心障礙者一人發給一付牌照\n為限，兩者擇一不得重複領用。\n六、申領專用牌照者，身心障礙者本人、配偶或本人之親屬須領有小型車以上\n之有效駕駛執照，並填具異動登記書，及檢附下列規定文件：\n（一）身心障礙證明。\n（二）申請者為身心障礙者之配偶或親屬，應另檢具全戶戶口名簿影本或最近\n三個月內戶籍謄本影本。\n（三）申領自用小貨車牌照者除應具備前二款文件外，尚須符合本規則第十六\n條附件一之一自用小貨車牌照申領審核規定。\n七、領用專用牌照之車輛，辦理過戶登記移轉至不符領用專用牌照之車主時，\n須同時換領一般車輛牌照。\n八、已領有牌照車輛，改換領專用牌照或一般車輛牌照，均須依規定繳交相關\n規費。\n九、領用專用牌照原因消滅時，領用人應將牌照繳回或換領一般車牌照。未繳\n回或未換領一般車牌照者，由公路監理機關逕行註銷之。"},{"file_id":"0000233628","name":"附件三危險物品道路運送計畫書.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000233628&lan=C","fetched":true,"bytes":134944,"pages":1,"text":"附\n件\n三\n\n\n危\n\n險\n\n物\n\n品\n\n道\n\n路\n\n運\n\n送\n\n計\n\n畫\n\n書\n\n年\n\n月\n\n日\n\n運\n輸\n車\n輛\n資\n料\n\n公司（行號）\n名        稱\n\n\n電\n話\n\n號\n碼\n\n（    ）\n\n地        址\n\n\n車        型\n\n車      號\n\n駕駛人姓名\n\n駕駛號碼\n\n危\n\n險\n\n物\n\n品\n\n資\n\n料\n\n危 險 物 品\n中 英 名 稱\n\n\n特      性\n\n\n\n裝 載 方 式\n\n裝載總重量\n\n生產廠商名稱\n\n電\n話\n號\n碼\n\n（    ）\n\n生產廠商地址\n運 送 時 應\n注 意 事 項\n\n\n災\n變\n發\n\n生\n處\n理\n\n人 員 撤 離\n安 全 距 離\n\n\n對人員之\n主要危害\n\n\n緊急處理方法\n運\n送\n路\n線\n起\n訖\n地\n點\n\n運 送 路 線\n及 起 訖 點\n\n\n運 送 時 間\n\n\n申\n請\n廠\n商\n\n\n負\n責\n人\n\n簽\n章\n\n\n地\n\n址\n\n\n運\n輸\n公\n司\n（\n代\n號\n）\n\n\n負\n責\n人\n\n簽\n章\n\n\n地\n\n址\n\n注\n意\n事\n項\n：\n應\n檢\n附\n「\n危\n險\n物\n品\n緊\n急\n處\n理\n方\n法\n說\n明\n書\n」\n一\n式\n二\n份\n。"},{"file_id":"0000021935","name":"附件三危險物品道路運送計畫書.DOC","format":"DOC","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000021935&lan=C","fetched":true,"bytes":32256},{"file_id":"0000233629","name":"附件四車輛裝載危險物品臨時通行證.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000233629&lan=C","fetched":true,"bytes":88162,"pages":1,"text":"附\n件\n四\n\n\n車\n\n輛\n\n裝\n\n載\n\n危\n\n險\n\n物\n\n品\n\n臨\n\n時\n\n通\n\n行\n\n證\n\n運\n\n送\n\n車\n\n輛\n\n車\n\n主\n\n\n電\n話\n號\n碼\n\n\n地\n\n址\n\n\n車\n\n別\n\n□\n一\n般\n貨\n車\n\n□\n半\n聯\n結\n車\n\n牌\n照\n號\n碼\n\n貨\n車\n：\n\n半\n拖\n車\n：\n\n危\n\n險\n\n物\n\n品\n\n資\n\n料\n\n廠\n商\n\n貨\n主\n\n名\n\n稱\n\n\n電\n話\n號\n碼\n\n\n地\n\n址\n\n\n危\n險\n物\n品\n類\n別\n\n\n第\n\n類\n\n危\n險\n物\n品\n類\n別\n名\n稱\n\n\n裝\n載\n方\n式\n\n\n裝\n\n載\n\n重\n\n量\n\n\n運\n\n送\n\n限\n\n制\n\n限\n定\n運\n送\n路\n線\n\n\n本\n通\n行\n證\n\n有\n效\n期\n限\n\n自\n\n年\n\n月\n\n日\n起\n至\n\n年\n\n月\n\n日\n\n行\n駛\n時\n間\n\n\n時\n起\n至\n\n時\n止\n\n注\n\n意\n\n事\n\n項\n\n\n一\n、\n應\n隨\n車\n攜\n帶\n本\n臨\n時\n通\n行\n證\n、\n有\n效\n之\n「\n危\n險\n物\n品\n運\n送\n人\n員\n專\n業\n訓\n練\n證\n明\n書\n」\n、\n所\n裝\n載\n危\n險\n物\n品\n之\n「\n物\n質\n安\n全\n資\n料\n表\n」\n等\n，\n如\n為\n罐\n槽\n車\n並\n應\n隨\n車\n攜\n帶\n有\n效\n之\n「\n罐\n槽\n體\n檢\n驗\n合\n格\n證\n明\n」\n。\n\n二\n、\n車\n頭\n及\n車\n尾\n應\n懸\n掛\n布\n質\n三\n角\n紅\n旗\n，\n車\n輛\n之\n左\n、\n右\n兩\n側\n及\n後\n方\n應\n懸\n掛\n或\n黏\n貼\n危\n險\n物\n品\n標\n誌\n及\n標\n示\n牌\n，\n應\n依\n規\n定\n隨\n車\n攜\n帶\n相\n關\n文\n件\n及\n有\n關\n安\n全\n之\n配\n備\n。\n\n（\n公\n路\n監\n理\n機\n關\n）\n\n核\n准\n日\n期\n、\n文\n號\n："},{"file_id":"0000021936","name":"附件四車輛裝載危險物品臨時通行證.DOC","format":"DOC","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000021936&lan=C","fetched":true,"bytes":28672},{"file_id":"0000412355","name":"附件五 大客車、大貨車、曳引車、小型汽車附掛之廂式拖車、露營車及幼童專用車應備有滅火器規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000412355&lan=C","fetched":true,"bytes":251139,"pages":2,"text":"第三十九條、第三十九條之一附件五\n  附件五  大客車、大貨車、曳引車、小型汽車附掛之廂式拖車、露營車\n及幼童專用車應備有滅火器規定\n 大客車、大貨車、曳引車、小型汽車附掛之廂式拖車、露營車及\n幼童專用車應備有符合下列規定之滅火器：\n一、應備有附表所列滅火器之一。\n二、滅火器外殼應明確標明有效期限，參加檢驗時，其有效期間並應在\n一個月以上。\n三、滅火器附有壓力計者，其壓力指針應在壓力錶之有效範圍內。\n四、滅火器外殼應標明使用方法並加漆車輛牌照號碼。\n五、滅火器應放置於駕駛人取用方便之處所。\n六、滅火器應固定妥善，以防止車輛行駛中產生振動、滾動、衝擊等情\n形。\n車輛種類\n\n滅火器種類\n大客車或大型露\n營車\n大貨\n車\n曳引\n車\n幼童專用車、小型汽車\n附掛之廂式拖車或小型\n露營車\n軸距未達\n四公\n尺者\n軸距四\n公尺以\n上\n鹵化烷類或同\n級代用品\n滅火器\n\n3型1具\n5型1具\n或3型2\n具\n5型1\n具\n5型1\n具\n\n3型1具\n乾粉滅火器\n5型1具\n10 型 1\n具\n10 型\n1具\n10 型\n1具\n5型1具\n二氧化碳滅\n火器\n5磅1具\n10 磅 1\n具\n10 磅\n1具\n10 磅\n1具\n5磅1具\n泡沫或強化液\n滅火器\n8 Ｌ型 1\n具\n8Ｌ型1\n具\n8 Ｌ\n型 1\n具\n8 Ｌ\n型 1\n具\n\n8Ｌ型1具\n\n\n\n註：\n一、泡沫或強化液：泡沫指化學泡沫、機械泡沫(包括表面活性劑、水成膜等)\n兩類；強化液指鹼金屬鹽類之水溶液，採用泡沫或強化液滅火器應使用可適\n用ＡＢＣ三類火災之滅火器）。\n二、乾粉：包括普通、紫焰、鉀鹽及多效磷鹽等，其中多效磷鹽可適用ＡＢ\nＣ三類火災。\n三、鹵化烷類:包括海龍一零一一、一二一一、一三零一、二四零二。對Ｂ\nＣ類火災可適用，惟受國際公約之限制，自一九九六年起將不得再\n生產。\n四、二氧化碳滅火器對ＢＣ類火災可適用，惟不耐高溫及不適用於密閉\n之車廂使用。\n五、各種車輛應視潛在火災性質分別選用能滅ＢＣ或ＡＢＣ類火災之滅\n    火器。"},{"file_id":"0000412351","name":"附件六 大客車車身各部規格應符合下表規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000412351&lan=C","fetched":true,"bytes":441037,"pages":4,"text":"第三十九條附件六\n附件六 大客車車身各部規格應符合下表規定\n項  目 適用一般大客\n車\n適用軸距\n四公尺以\n上大客車\n適用市區雙\n層公車     檢  驗  要  領   備\n註\n實施日\n期\n一、踏步\n高\n至多四十公分 至多四十\n公分\n至多四十公\n分\n在空車狀態時以踏\n板上表面與地面間\n之距離為準\n\n\n\n現行規\n定\n二、走道\n寬\n             至少三十\n二公分\n至少三十二\n公分\n                           現行規\n定\n三、門框\n高\n             至少一百\n八十五公\n分\n至少一百八\n十五公分\n                           現行規\n定\n四、門框\n寬\n至少七十六公\n分\n至少七十\n六公分\n\n至少九十公\n分\n至少六十公\n分\n一、 市區雙層公車\n靠上下層聯絡\n階梯之上下客\n車門寬度不得\n少於九十公分\n；另一車門寬\n度不得少於六\n十公分。\n二、 市區雙層公車\n以外之大客車\n，門框高於一\n百六十五公分\n以上之部分，\n其門框寬不受\n七十六公分之\n限制，但該部\n分面積應至少\n七百六十平方\n公分。\n\n現行規\n定\n五、內高一百八十五公\n分\n\n至少一百\n八十五公\n分\n\n上層至少一\n百七十公分\n下層至少一\n百八十五公\n分\n以走道中央以內部\n淨高為準。\n\n軸距未達四\n公尺大客車\n申請核定立\n位時，內高\n應符合本規\n定。\n現行規\n定\n六、椅距至少七十公分 至少七十\n公分\n至少七十公\n分\n從前椅之前緣量至\n後椅之前緣間（即對\n應點）之距離為準。\n本項目道路\n交通安全規\n則內已有規\n定，但補充\n檢驗要領。\n現行規\n定\n\n七、椅墊\n深\n至少四十公分 至少四十\n公分\n至少四十公\n分\n以椅墊前端至椅墊\n最深處之距離。\n          現行規\n定\n八、駕駛\n座欄桿\n應設\n應設\n應設\n設於駕駛座之後部。申請核定立\n位車輛適用\n。\n現行規\n定\n九、行李\n架\n             應設\n長途車必備\n，但有行李\n廂者得免設\n置。\n現行規\n定\n十、行李\n廂高度\n\n至多一百\n公分\n\n一、以行李廂內最大\n淨高為準。\n二、行李廂不得裝置\n座椅。\n三、車高三點五公尺\n以下或經實車\n滿載配重傾斜\n穩定度大於三\n十五度測試合\n格者，其行李廂\n高度得不受至\n多一百公分之\n限制。\n\n自發布\n日起實\n施。\n十一、扶\n手或拉\n捍或拉\n環\n\n應設      應設\n申請核定立\n位之長途及\n市區公車必\n備，具備其\n中任何一種\n均可。\n現行規\n定\n十二、上\n下車扶\n手\n             應設\n應設\n每車門（不包括安全\n門）兩邊各一套。\n\n現行規\n定\n十三、安\n全門有\n效高\n\n\n至少一百\n六十公分\n有效幅度至\n少上層一百\n四十公分×五\n十公分，下層\n一百五十公\n分×五十公分\n安全門應設於車身\n後部中央，如引擎為\n後置式或車身後部\n裝設冷氣機者，准設\n於車身左側之後部\n或中部。\n\n自發布\n日起實\n施。\n十四、安\n全門有\n效寬\n至少七十六公\n分\n至少七十\n六公分\n十五、安\n全門通\n道寬\n\n\n至少三十\n二公分\n至少三十二\n公分\n安全門通道應設置\n於安全門有效寬之\n範圍內。\n\n          現行規\n定\n\n十六、安\n全門下\n緣距地\n高\n至多一百公分 至多一百\n公分\n至多一百公\n分\n                 指安全門通\n道或階梯下\n緣距地高，\n但設階梯者\n其階梯寬至\n少七十六公\n分，階梯深\n至少二十五\n公分。\n自八十\n二年一\n月一日\n起新領\n牌車輛\n實施。\n十七、「\n安全門」\n標識字\n體\n每字至少十公\n分見方\n\n每字至少\n十公分見\n方\n\n每字至少十\n公分見方\n\n\n一、應設置\n於安全\n門上（\n即安全\n門本身\n上方）\n。\n二、安全門\n上並\n應標\n明操\n作方\n法。\n現行規\n定\n十八、安\n全門警\n告裝置\n應備有安全門\n開啟時對駕駛\n人之警告裝置\n\n應備有安\n全門開啟\n時對駕駛\n人之警告\n裝置\n應備有安全\n門開啟時對\n駕駛人之警\n告裝置\n                 警告裝置可\n為警告燈、\n警鈴或蜂鳴\n器等。\n\n自八十\n二年一\n月一日\n起新領\n牌車輛\n實施。\n十九、安\n全窗\n車身兩側每側\n至少各五面，每\n面有效面積至\n少九千平方公\n分\n車身兩側\n每側至少\n各五面，每\n面有效面\n積至少九\n千平方公\n分\n車身兩側每\n側至少各五\n面，每面有效\n面積至少九\n千平方公分\n一、有效面積指安全\n窗打開後窗框\n之淨長乘以深\n寬所得乘積。\n二、安全窗每面開度\n均應可達九十\n度以上。\n一、已設有\n安全門\n者得免\n設置安\n全窗。\n二、具備安\n全窗者\n得免設\n安全門\n。\n現行規\n定\n\n\n\n二十、車\n窗擊破\n裝置\n兩具\n兩具\n兩具\n\n車窗為活動\n式（可開啟\n式）者得免\n設置。\n現行規\n定\n二十一\n、其他\n\n          本附件未規\n範部分應符\n合「市區汽車\n客運業申請\n行駛雙層公\n車處理要點」\n之規定\n\n          現行規\n定"},{"file_id":"0000412361","name":"附件六之一 新型式大客車車身各部規格規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000412361&lan=C","fetched":true,"bytes":327011,"pages":5,"text":"第三十九條、第三十九條之一、第四十二條附件六之\n一\n附件六之一 新型式大客車車身各部規格規定\n一、本附件適用單層大客車及其分類如下：\n(一)甲類大客車係指軸距逾四公尺之大客車。\n(二) 乙類大客車係指軸距未逾四公尺且核定總重量逾四點五噸之大客車。\n(三) 丙類大客車係指軸距未逾四公尺且核定總重量逾三點五噸而未逾四點五噸之大客車。\n(四) 丁類大客車係指軸距未逾四公尺且核定總重量未逾三點五噸之大客車。\n二、出口係指車門和緊急出口，其位置及數量應符合下列規定：\n(一) 車門係指供乘客於正常情況下使用之門，不含鄰近駕駛座左側供駕駛人出入之門。車門應設於\n右側且數量至少一個（申請核定座立位總數逾四十七人之市區公車至少二個）。\n(二) 緊急出口係指安全門、安全窗和車頂逃生口。應於車身後方或左後側至少裝設一個安全門，應\n於車身後方或車頂至少裝設一個緊急出口（申請核定座立位總數逾五十二人之大客車應至少裝\n設二個）。\n(三) 甲類、乙類及丙類大客車出口總數應符合下列規定，其中可供二個量測車門通道之矩形鑲板併\n排通過之雙扇車門計為二個車門，中線左右兩側區域均符合安全窗尺度與通道規定之雙扇安全\n窗計為二個安全窗，但車頂逃生口僅可計為一個緊急出口：\n１、 申請核定座立位總數未逾十八人之大客車及車廂為部分或全部無車頂之大客車（以下簡稱\n單層開放式大客車）：至少三個。\n２、申請核定座立位總數逾十八人但未逾三十二人之大客車：至少四個。\n３、申請核定座立位總數逾三十二人但未逾四十七人之大客車：至少五個。\n４、申請核定座立位總數逾四十七人但未逾六十二人之大客車：至少六個。\n５、申請核定座立位總數逾六十二人之大客車：至少七個。\n(四) 甲類大客車另應符合下列規定：\n１、 車輛兩側出口數量應相等且兩相鄰出口內緣應有間隔。但單層開放式大客車得免符合「車\n輛兩側出口數量應相等」之規定。\n２、 車輛同側二門（車門或安全門）間之距離應不小於乘客室全長之百分之四十，其距離應於\n車門（安全門）中心量測，若其中之一為雙扇車門時，應於二門間最遠處量測。乘客室全\n長係指最前排乘客座椅椅墊前緣與最後排乘客座椅椅背後緣相切於車輛縱向中心面之水平\n距離。\n３、 若僅裝置一個車頂逃生口，應裝設於車頂中段；若裝置二個時，兩開口內緣應至少間隔二\n公尺。\n三、出口標識\n(一) 甲類大客車應於出口或距出口三十公分之範圍內裝設綠色標識燈。乙類大客車應於車門、安全\n門及車頂逃生口或距該出口三十公分之範圍內裝設綠色標識燈，且自中華民國九十五年一月一\n日起，應於安全窗或距安全窗三十公分之範圍內裝設綠色標識燈。\n(二) 緊急出口標識應以中文「緊急出口」及英文「Emergency exit」標識於乘客輕易可視之車內及\n車外緊急出口或其鄰近位置。中文標識字體於安全門者，每字至少十公分見方，於安全窗及車\n頂逃生口者，每字至少四公分見方。\n(三) 應於乘客輕易可視之緊急出口控制裝置或其鄰近位置標示操作方法。\n四、車門\n(一)門框高：\n１、甲類大客車：至少一百八十五公分。\n\n\n２、乙類大客車：至少一百五十公分。\n３、丙類及丁類大客車：至少一百十公分。\n４、設於單層開放式大客車之無車頂區域者，得免符合門框高之規定。\n(二) 門框寬：\n１、甲類及乙類大客車：至少七十六公分。\n２、丙類及丁類大客車：至少六十五公分。\n(三) 在緊急事件發生時，動力操作式車門應可於車輛停止時，藉由符合下列規定之控制裝置由車內徒\n手開啟，且於車門未鎖住時由車外開啟，否則不得列入車門數量計算：\n１、應可獨立控制（不受其他控制裝置控制）。\n２、車內控制裝置應設置於車門或距車門三十公分之範圍內。\n３、應於該裝置或其鄰近位置標示操作方法。\n４、應可由一個人操作使車門開啟。\n５、得以易破壞之防護遮蓋保護該裝置（應同時以聲音及信號警示駕駛人）。\n五、車門通道係指車門至最上層階梯外緣（即走道側，未設階梯者應為車門內側向內延伸三十公分處）間\n之通道，大客車車門通道應符合下列規定：\n(一) 甲類大客車：應允許寬度五十五公分，高度一百八十五公分且厚度為二公分之矩形鑲板，其平\n面應以乘客離開車輛之方向，自走道側垂直穿越車門至車輛外側。\n(二) 乙類大客車：應允許寬度五十五公分，高度一百五十公分且厚度為二公分之矩形鑲板，其平面\n應以乘客離開車輛之方向，自走道側垂直穿越車門至車輛外側。\n六、安全門\n(一) 有效高：\n１、甲類大客車：至少一百六十公分。\n２、 乙類大客車：至少一百二十五公分。\n３、丙類及丁類大客車：至少一百十公分。\n４、設於單層開放式大客車之無車頂區域者，得免符合有效高之規定。\n(二) 有效寬至少五十五公分。\n(三) 下緣距地高（指安全門通道或階梯下緣距地高）：\n１、 甲類及乙類大客車：至多七十公分。但中華民國九十四年十二月三十一日以前之甲類市區公\n車及乙類大客車得為至多一百公分。\n２、丙類及丁類大客車：至多一百公分。\n(四)安全門應設有「防止誤開啟裝置」及該裝置啟動時對駕駛人之聲音警告裝置。安全門不得為動力\n操作式或滑動式，其應能於車輛靜止時由車內及車外開啟，安全門開啟後非經外力不得自動關閉。\n(五) 安全門車外控制裝置距地高至多一百八十公分。\n七、安全門通道係指走道至安全門間之通道，大客車安全門通道應符合下列規定：\n(一) 不得裝設活動式座椅或蓋板且應保持暢通。（安全門通道旁設有活動物品者，其所有可能位置均\n應符合本項規定）\n(二) 甲類大客車：應允許寬度五十五公分，高度為一百六十公分且厚度為二公分之矩形鑲板，其平面\n應以乘客離開車輛之方向，自走道側垂直穿越安全門至車輛外側。\n(三) 乙類大客車：應允許寬度五十五公分，高度為一百二十五公分且厚度為二公分之矩形鑲板，其平\n面應以乘客離開車輛之方向，自走道側垂直穿越安全門至車輛外側。\n(四) 前二款規定之安全門通道與走道平行者，其安全門通道有效淨深至少五十五公分。\n八、安全窗\n(一) 安全窗應為下列兩種型式之一：\n\n\n１、 活動式安全窗：應可於車內及車外徒手開啟。若為鉸鍊式安全窗應向外開啟，其每面開度均\n應可達九十度以上。以鉸鍊繫住頂端之安全窗應裝設適當機構維持開啟。應備有鉸鍊式安全\n窗開啟時對駕駛人之聲音警告裝置，該裝置應由安全窗扣移動來作動，並非由安全窗本身移\n動時來作動。\n２、 玻璃式安全窗：玻璃材質應為符合中華民國國家標準之汽車用強化安全玻璃或「車輛安全檢\n測基準」中「安全玻璃」之強化安全玻璃且應易碎，並應於新登檢領照時由申請者提出相關\n證明文件。\n(二)安全窗窗框之內高乘以內寬至少四千平方公分，其應至少容納尺度五十公分×七十公分之矩形。裝\n於車輛後方且無法符合上述尺度之安全窗應至少容納高三十五公分，寬一百五十五公分且邊角曲率\n半徑不逾二十五公分之矩形。\n(三)車輛側方安全窗下緣距車內地板之高度應不大於一百公分，且若為鉸鍊式安全窗不得小於六十五\n公分，若為玻璃式安全窗不得小於五十公分。若鉸鍊式安全窗之窗框裝設距車內地板高六十五公分\n之防護裝置，以防範乘客掉出車外，其下緣距車內地板高可減少至五十公分，且防護裝置上方之窗\n框尺度應不得小於前款安全窗尺度之規定。\n九、 安全窗通道係指走道至安全窗間之通道，應允許尺度四十公分×六十公分，厚度二公分且邊角曲率半\n徑為二十公分之薄板，其平面應以乘客離開車輛之方向，走道側垂直穿越安全窗至車輛外側。無法\n符合上述規定之車輛後方安全窗通道得以尺度三十五公分×一百四十公分，厚度二公分且邊角曲率半\n徑為十七點五公分之薄板代替。安全窗前設有活動物品者，其所有可能位置均應符合本項規定。\n十、車窗擊破裝置\n(一)至少三具。\n(二)置放位置應使乘客易於取用且滿足下列條件：\n１、駕駛人附近應至少設置一具。\n２、車輛前半段及後半段各應至少設置一具。\n３、車身兩側各應至少設置一具。\n(三) 應於該裝置附近且於乘客輕易可視之處標示「車窗擊破裝置」之標識字體和操作方法，標識字\n體每字至少四公分見方。\n(四)未設有玻璃式安全窗者，得免符合應設置車窗擊破裝置之規定。\n十一、車頂逃生口\n(一) 車頂逃生口應可由車內及車外徒手開啟，其有效面積至少四千平方公分，且應至少容納尺度五\n十公分×七十公分之矩形。\n(二)應允許銳角二十度且高一百六十公分之垂直三角板，其頂端接觸車頂逃生口框架內緣時（若車\n頂厚度逾十五公分時，其頂端應接觸車頂逃生口外側表面之框架），底邊可接觸座椅或支撐物。\n若支撐物為折疊式或可移動式，其使用時應可被鎖定。\n十二、階梯\n(一)深度：\n１、 甲類大客車離地第一階表面應至少容納四十公分×三十公分之矩形，其他階梯應至少容納四\n十公分×二十公分之矩形，矩形區域內最大坡度應不逾三度。\n２、 乙類大客車：安全門通道之階梯深度至少二十五公分，但自中華民國九十五年一月一日起\n，其離地第一階最小深度應至少二十三公分，其他階梯最小深度應至少二十公分，且各階\n梯面積不得小於八百平方公分，階梯表面最大坡度應不逾三度。\n３、 丙類及丁類大客車：安全門之階梯深度至少二十五公分。\n４、 前三目規定之階梯表面外緣突出下一階梯至多十公分，且階梯表面之有效垂直投影深度至\n少二十公分。\n(二) 高度：\n１、 離地第一階：離地第一階高度以在空車狀態時踏板上表面與地面間之距離為準。甲類及乙\n類大客車：於車門者至多四十公分，於安全門者至多七十公分。但中華民國九十四年十二\n\n\n月三十一日以前之甲類市區公車及乙類大客車至多一百公分。丙類及丁類大客車：於車門\n者至多四十公分，於安全門者至多一百公分。\n２、其他階梯：至少十二公分，至多三十五公分。\n(三) 伸縮式階梯應符合下列規定：\n１、當車門或安全門關閉時，突出車身部分應不逾一公分。\n２、當車門或安全門開啟且其位於伸展位置時，其階梯深度應符合規定。\n３、 當其位於伸展位置時，車輛應無法移動。當車輛移動時，其應無法伸展。\n十三、走道係指平行車輛縱向中心線，自最前排乘客座椅椅背後緣至最後排乘客座椅椅墊前方三十公分之\n通道空間，並得延伸至車門通道及安全門通道，但不包括前置式引擎隆起區域旁之乘客座椅椅背後\n緣以前之通道空間和後置式引擎之大客車其最後第二排乘客座椅椅墊前方三十公分以後之通道空\n間。大客車走道應符合下列規定：\n(一)不得設置活動式座椅。\n(二) 未申請核定立位之丙類及丁類大客車：走道有效寬至少二十五公分，走道內高至少一百二十公\n分，並應能允許直徑二十五公分，高度一百二十公分之圓柱體垂直順利通過。\n(三) 未申請核定立位之乙類大客車：走道有效寬至少三十二公分，走道內高至少一百五十公分，並\n應能允許直徑三十二公分，高度一百五十公分之圓柱體垂直順利通過。\n(四) 甲類大客車及自中華民國九十五年一月一日起申請核定立位之之乙類大客車：走道有效寬至少\n三十二公分，走道內高至少一百八十五公分，並應能允許直徑三十二公分，高度一百八十五公\n分之圓柱體垂直順利通過。若圓柱體可能會與供立位乘客使用之活動式扶手或拉桿或拉環接觸\n時可將其移開。\n(五) 申請核定立位之丙類、丁類及中華民國九十四年十二月三十一日以前申請核定立位之乙類大客\n車：走道有效寬至少三十二公分，走道內高至少一百八十五公分，並以走道中央淨高為一百八\n十五公分之量測標準位置。\n十四、乘客座椅（駕駛座右側服務員座椅除外）\n(一) 乘客座椅前方為安全門通道或車門通道者，其座椅空間地板與其前方地板高度差逾十二公分時\n應設置欄杆或保護板，欄杆或保護板上緣距座椅空間地板高度至少八十公分，欄杆或保護板寬\n度應能涵蓋該座椅之椅背對應寬度。\n(二) 椅墊最上方之水平面與距地高六十二公分之水平面間，水平量測其座椅椅背前緣至前方座椅椅\n背（欄杆或保護板）後緣間之椅距：\n１、 除市區公車外之甲類大客車：至少六十八公分。\n２、 其他大客車：至少六十五公分。\n(三) 甲類大客車及自中華民國九十五年一月一日起之乙類大客車，水平量測其椅墊前緣至前方座椅\n椅背（欄杆或保護板）後緣間之距離至少應為二十八公分。\n(四)椅墊前緣至椅墊最深處之距離：\n１、 除市區公車外之甲類大客車：至少四十公分。\n２、 其他大客車：至少三十五公分。\n(五) 設於駕駛室上方之最前方乘客座椅應設欄杆或保護板與擋風玻璃區隔，欄杆或保護板上緣之後\n緣與擋風玻璃間之距離至少七十公分，欄杆或保護板上緣距地板高度至少八十公分，其寬度應\n能涵蓋該座椅之椅背對應寬度。\n十五、行李廂係指除乘客室和盥洗設備外可供乘客置放行李之空間，若裝設者應符合下列規定：\n(一)不得設置座椅或臥舖。\n(二) 不得設置邊窗，且其外側車身材質應與整車外側車身主要材質相同，不得使用玻璃或其他透明\n材質。\n(三) 車輛兩側各至少設置一個液壓或氣壓式之上掀式行李廂門，同側各門框內緣間隔至多十公分，\n所有門之門框寬總和至少一百五十公分。\n\n\n(四) 行李廂內部材質應為以焊接或相當方式固定之金屬鈑件，同側行李廂之內部空間應相通，且其\n應較門框對應之內部空間大，並應允許邊長五十公分之正方體自車輛外側穿越行李廂門至行李\n廂內側且能順利妥適關閉行李廂門。\n(五) 甲類大客車，行李廂內最大淨高至多一百公分；但車高在三點五公尺以下或經實車滿載配重傾\n斜穩定度大於三十五度測試合格者，其行李廂高度得不受至多一百公分之限制。\n十六、單層開放式大客車其無車頂之區域應依下列規定設置乘員防護裝置：\n(一) 應具備連續前方護板，連續之前方護板應涵蓋整個車身全寬，以前方護板所在處之車內地板為\n量測基準，其高度應不小於一百四十公分。若使用玻璃於防護裝置，則其玻璃應符合本基準中\n「安全玻璃」之擋風玻璃規定。\n(二) 應具備連續之側方及後方防護裝置，以該防護裝置所在處之車內地板為量測基準，其側方防護\n裝置之高度應不小於一百一十公分；後方防護裝置，其高度應不小於一百二十公分；若使用玻\n璃於防護裝置，則其玻璃應符合本基準中「安全玻璃」之強化玻璃規定。在前述高度範圍內，\n防護裝置應為連續護板式；若在前述高度範圍內非為連續護板式，則防護裝置應至少在自車內\n地板至距地高七十公分之間為連續護板，而其上方使用一個以上連續護欄者，其護欄安裝應符\n合下列規格：\n１、 其斷面高度應不小於二公分且不大於四點五公分。\n２、 護板與欄杆之間距及欄杆與欄杆之間距應不大於二十公分。\n(三)應牢固地固定於車輛結構上。\n(四)出口處之車門應視為構成該防護裝置之一部分。\n(五)擋風玻璃與最前排座椅之間，應設置能防止衝擊之保護設施。\n十七、單層開放式大客車應依下列規定設置車內視野和通訊裝置：\n(一)應裝設相關視覺設備，以使駕駛人可透過鏡子、攝影機及監視器等，觀察乘客狀況。\n(二) 應提供一內部通訊系統以利駕駛能將訊息通知乘客。\n十八、其他\n(一) 申請核定立位之大客車，應設置扶手或拉桿或拉環，且應於駕駛座之後部設置駕駛座欄杆。\n(二) 甲類長途車，應設置行李架，但有行李廂者得免設置，且其每一車門兩邊均應設置上下車扶手\n。\n(三) 駕駛區為無車頂設計時，應具有專用保護設施，防止駕駛人受天候或環境變化等之影響。\n(四)單層開放式大客車之座位，應設置繫妥安全帶之提醒標誌。"},{"file_id":"0000412353","name":"附件六之二 使用中及既有車型大客車車身各部規格規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000412353&lan=C","fetched":true,"bytes":340425,"pages":1,"text":"第三十九條之一附件六之二\n附件六之二 使用中及既有車型大客車車身各部規格規定\n一、 車門應設於右側，安全門應設於車身後部中央，如引擎為後置式或後側設有冷氣機者，准設於車身\n左側之後部或中部。\n二、 軸距逾四公尺之大客車，其門框高至少一百八十五公分。\n三、 緊急出口標識：\n(一)緊急出口標識應以中英文標識於乘客輕易可視之車內及車外緊急出口或其鄰近位置。緊急出口英\n文標識應為「Emergency exit」。「安全門」中文標識字體，每字至少十公分見方。「安全窗」中\n文標識字體，每字至少四公分見方。\n(二) 應於乘客輕易可視之緊急出口控制裝置或其鄰近位置標示操作方法。\n四、 安全門應備有安全門開啟時對駕駛人之警告裝置，警告裝置可為警鈴或蜂鳴器等。\n五、 安全門通道係指走道至安全門間之通道，應設置於安全門有效寬之範圍內，且軸距逾四公尺之大客\n車，其安全門通道有效寬度至少三十二公分。\n六、 安全門通道不得裝設活動式座椅或蓋板，並應保持暢通，軸距逾四公尺之大客車，其安全門有效高\n至少一百六十公分，安全門有效寬至少七十六公分，安全門下緣距地高至多一百公分（市區雙層公\n車之上層安全門不受此限，自八十一年十二月三十一日以前新領牌車輛不受安全門下緣距地高至多\n一百公分之限制）。\n七、 大客車車身兩側每側至少各五面安全窗，安全窗每面開度均應可達九十度以上，安全窗每面有效面\n積至少九千平方公分；有效面積指安全窗打開後窗框之淨長乘以淨寬所得乘積；設有安全門者得免\n設安全窗，設有安全窗者得免設安全門。\n八、 車窗擊破裝置\n(一) 至少三具。（市區雙層公車上下層，每層至少三具）\n(二) 置放位置應滿足下列條件：\n１、 駕駛人附近應至少設置一具。\n２、 車輛前半段及後半段各應至少設置一具。\n３、 車身兩側各應至少設置一具。\n(三) 應於該裝置附近且於乘客輕易可視之處標示「車窗擊破裝置」之標識字體和操作方法，標識字體\n每字至少四公分見方。\n九、 設於駕駛室上方之最前方乘客座椅應設欄杆或保護板與擋風玻璃區隔，欄杆或保護板上緣之後緣與\n擋風玻璃間之距離至少七十公分，欄杆或保護板上緣距地板高度至少八十公分，其寬度應能涵蓋該\n座椅之椅背對應寬度。\n十、 乘客座椅不得懸空設於安全門有效通道範圍內，且安全門通道設階梯之邊緣與座椅椅墊前緣至少三\n十公分。其空間地板與其前方地板高度差逾十二公分時應設置欄杆或保護板，欄杆或保護板上緣距\n地板高度至少八十公分，欄杆或保護板寬度應能涵蓋該座椅之椅背對應寬度。\n十一、行李廂（若裝設者）應符合下列規定：\n(一) 軸距逾四公尺之大客車，行李廂內最大淨高至多一百公分。\n(二)中華民國九十三年六月三十日以前至公路監理機關登錄者，且未有違規裝設座椅載客之情形，\n其行李廂高度得不受至多一百公分之限制。\n(三) 不得設置座椅或臥舖。\n(四) 不得設置邊窗。\n十二、其他\n(一) 申請核定立位之大客車，應設置扶手或拉桿或拉環，且應於駕駛座之後部設置駕駛座欄杆。\n(二) 軸距逾四公尺之長途車，應設置行李架，但有行李廂者得免設置，且其每一車門兩邊均應設置\n上下車扶手。"},{"file_id":"0000412356","name":"附件六之三 雙節式大客車車身各部規格規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000412356&lan=C","fetched":true,"bytes":444996,"pages":4,"text":"第三十九條、第三十九條之一附件六之三\n附件六之三  雙節式大客車車身各部規格規定\n一、出口係指車門和緊急出口，其位置及數量應符合下列規定：\n（一）車門係指供乘客於正常情況下使用之門，不含鄰近駕駛座左側供駕駛人出入之\n門。車門應設於右側且每一節剛性車廂應至少一個（申請核定座立位總數逾七\n十人之雙節式大客車，其第一節剛性車廂應至少二個車門）。\n（二）雙節式大客車每一節剛性車廂之出口總數應符合下列規定，其中可供二個量測\n車門通道之矩形鑲板併排通過之雙扇車門計為二個車門，中線左右兩側區域均\n符合安全窗尺度與通道規定之雙扇安全窗計為二個安全窗：\n1.申請核定座立位總數逾十六人但未逾三十人之剛性車廂：至少四個。\n2.申請核定座立位總數逾三十人但未逾四十五人之剛性車廂：至少五個。\n3.申請核定座立位總數逾四十五人但未逾六十人之剛性車廂：至少六個。\n4.申請核定座立位總數逾六十人之剛性車廂：至少七個。\n（三）車廂兩側出口數量應相等且兩相鄰出口內緣應有間隔。對於超過最少數量要求\n之額外出口，其可不必兩側具有相同數量。\n（四）車廂同側二門（車門或安全門）間之距離應不小於車廂全長之百分之四十，其\n距離應於車門（安全門）中心量測，若其中之一為雙扇車門時，應於二門間最\n遠處量測。車廂全長係指第一節車廂最前排乘客座椅椅墊前緣與第二節車廂最\n後排乘客座椅椅背後緣相切於車輛縱向中心面之水平距離。\n（五）每一節剛性車廂若僅裝置一個車頂逃生口，應裝設於車頂中段；若裝置二個時\n，兩開口內緣應至少間隔二公尺。\n二、出口標識\n（一）緊急出口標識應以中文「緊急出口」及英文「Emergency exit」標識於乘客輕\n易可視之車內及車外緊急出口或其鄰近位置。中文標識字體於安全門者，每字\n至少十公分見方，於安全窗及車頂逃生口者，每字至少四公分見方。\n（二）於乘客輕易可視之緊急出口控制裝置或其鄰近位置標示操作方法。\n三、車門\n（一）門框高至少一百八十公分。\n（二）門框寬至少五十五公分。\n（三）在緊急事件發生時，動力操作式車門應可於車輛停止時，藉由符合下列規定之\n控制裝置由車內徒手開啟，且於車門未鎖住時由車外開啟，否則不得列入車門\n數量計算：\n1.應可獨立控制(不受其他控制裝置控制)。\n2.車內控制裝置應設置於車門或距車門三十公分之範圍內。\n3.應於該裝置或其鄰近位置標示操作方法。\n\n\n4.應可由一個人操作使車門開啟。\n5.得以易破壞之防護遮蓋保護該裝置(應同時以聲音及信號警示駕駛人)。\n四、車門通道係指車門至最上層階梯外緣(即走道側，未設階梯者應為車門內側向內延伸\n三十公分處)間之通道，車門通道應允許寬度五十五公分，高度一百八十公分且厚度\n為二公分之矩形鑲板，其平面應以乘客離開車輛之方向，自走道側垂直穿越車門至\n車輛外側。\n五、安全門\n（一）有效高至少一百二十五公分。\n（二）有效寬至少五十五公分。\n（三）下緣距地高（指安全門通道或階梯下緣距地高）至多七十公分。\n（四）安全門應設有「防止誤開啟裝置」及該裝置啟動時對駕駛人之聲音警告裝置。\n安全門應能於車輛靜止時由車內及車外開啟，安全門開啟後非經外力不得自動\n關閉。\n（五）安全門車外控制裝置距地高至多一百五十公分。\n六、安全門通道係指走道至安全門間之通道，安全門通道應符合下列規定：\n（一）不得裝設活動式座椅或蓋板且應保持暢通。(安全門通道旁設有活動物品者，其\n所有可能位置均應符合本項規定)\n（二）應允許一疊加圓柱自由通過，該疊加圓柱由一個直徑為三十公分、距離地板高\n度為七十公分的垂直圓柱和一個直徑為五十五公分的垂直圓柱構成，這兩個圓\n柱的總高度為一百四十公分。上圓柱直徑可在頂部減為四十公分，其過渡斜面\n與水平面夾角不得超過三十度，且第一個圓柱體的底部應在第二個圓柱體的投\n影內。\n七、安全窗\n（一）安全窗應為下列兩種型式之一：\n1.活動式安全窗：應可於車內及車外徒手開啟。若為鉸鍊式安全窗應向外開啟，\n其每面開度均應可達九十度以上。以鉸鍊繫住頂端之安全窗應裝設適當機構維\n持開啟。應備有鉸鍊式安全窗開啟時對駕駛人之聲音警告裝置，該裝置應由安\n全窗扣移動來作動，並非由安全窗本身移動時來作動。\n2.玻璃式安全窗：玻璃材質應為符合「車輛安全檢測基準」中「安全玻璃」之強\n化安全玻璃且應易碎，並應於新登檢領照時由申請者提出相關證明文件。\n（二）安全窗窗框之內高乘以內寬至少四千平方公分，其應至少容納尺度五十公分×\n七十公分之矩形。\n（三）裝於車輛後方且無法符合上述尺度之安全窗應至少容納高三十五公分，寬一百\n五十五公分且邊角曲率半徑不逾二十五公分之矩形。\n（四）車輛側方安全窗下緣距車內地板之高度應不大於一百二十公分，且若為鉸鍊式\n安全窗不得小於六十五公分，若為玻璃式安全窗不得小於五十公分。若鉸鍊式\n安全窗之窗框裝設距車內地板高六十五公分之防護裝置，以防範乘客掉出車外\n，其下緣距車內地板高可減少至五十公分，且防護裝置上方之窗框尺度應不得\n小於前款安全窗尺度之規定。\n\n\n八、安全窗通道係指走道至安全窗間之通道，應允許尺度四十公分×六十公分，厚度二公\n分且邊角曲率半徑為二十公分之薄板，其平面應以乘客離開車輛之方向，自走道側\n垂直穿越安全窗至車輛外側。無法符合上述規定之車輛後方安全窗通道得以尺度三\n十五公分×一百四十公分，厚度二公分且邊角曲率半徑為十七點五公分之薄板代替。\n安全窗前設有活動物品者，其所有可能位置均應符合本項規定。\n九、車窗擊破裝置\n（一）駕駛人附近應至少一具。\n（二）每扇玻璃式安全窗鄰近處至少一具。\n（三）應於該裝置附近且於乘客輕易可視之處標示「車窗擊破裝置」之標識字體和操\n作方法，標識字體每字至少四公分見方。\n十、車頂逃生口\n（一）車頂逃生口應可由車內及車外徒手開啟，其有效面積至少四千平方公分，且應\n至少容納尺度五十公分×七十公分之矩形。\n（二）應允許銳角二十度且高一百六十公分之垂直三角板，其頂端接觸車頂逃生口框\n架內緣時（若車頂厚度逾十五公分時，其頂端應接觸車頂逃生口外側表面之框\n架），底邊可接觸座椅或支撐物。若支撐物為折疊式或可移動式，其使用時應可\n被鎖定。\n十一、階梯\n（一）深度：\n1.離地第一階表面應至少容納四十公分×三十公分之矩形，其他階梯應至少容納四\n十公分×二十公分之矩形，矩形區域內最大坡度應不逾三度。\n2.前目規定之階梯表面外緣突出下一階梯至多十公分，且階梯表面之有效垂直投\n影深度至少二十公分。\n（二）高度：\n1.離地第一階：於車門者至多三十四公分，於安全門者至多七十公分。離地第一\n階高度以在空車狀態時踏板上表面與地面間之距離為準。\n2.其他階梯：至少十二公分，至多二十五公分。\n（三）伸縮式階梯應符合下列規定：\n1.當車門或安全門關閉時，突出車身部分應不逾一公分。\n2.當車門或安全門開啟且其位於伸展位置時，其階梯深度應符合規定。\n3.當其位於伸展位置時，車輛應無法移動。當車輛移動時，其應無法伸展。\n十二、走道係指平行車輛縱向中心線，自每一節剛性車廂最前排乘客座椅椅背後緣至最\n後排乘客座椅椅墊前方三十公分之通道空間，並得延伸至車門通道及安全門通道\n，但不包括前置式引擎隆起區域旁之乘客座椅椅背後緣以前之通道空間和後置式\n\n\n引擎之雙節式大客車其最後第二排乘客座椅椅墊前方三十公分以後之通道空間。\n走道應符合下列規定：\n（一）不得設置活動式座椅。\n（二）走道有效寬至少三十二公分，走道內高至少一百八十五公分，並應能允許直徑\n三十二公分，高度一百八十五公分之圓柱體垂直順利通過。若圓柱體可能會與\n供立位乘客使用之活動式扶手或拉桿或拉環接觸時可將其移開。\n十三、乘客座椅(駕駛座右側服務員座椅除外)\n（一）乘客座椅前方為安全門通道或車門通道者，其座椅空間地板與其前方地板高度\n差逾十二公分時應設置欄杆或保護板，欄杆或保護板上緣距座椅空間地板高度\n至少八十公分，欄杆或保護板寬度應從車身側邊向車內延伸至超出該座椅的縱\n向中心線至少十公分，或者延伸至最裡面一級階梯的豎板(取兩者之中的較小尺\n寸)。\n（二）椅墊最上方之水平面與距地高六十二公分之水平面間，水平量測其座椅椅背前\n緣至前方座椅椅背(欄杆或保護板)後緣間之椅距：應至少六十五公分。\n（三）水平量測其椅墊前緣至前方欄杆或保護板後緣間之距離至少應為二十八公分。\n（四）椅墊前緣至椅墊最深處之距離：應至少三十五公分。\n十四、其他：申請核定立位之大客車，應設置扶手或拉桿或拉環，且應於駕駛座之後部\n設置駕駛座欄杆。"},{"file_id":"0000410654","name":"附件六之四 雙層公車車身各部規格規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000410654&lan=C","fetched":true,"bytes":120202,"pages":8,"text":"第三十九條、第三十九條之一附件六之四修正\n規定\n附件六之四 雙層公車車身各部規格規定\n一、雙層公車應為甲類大客車。\n二、出口係指車門和緊急出口，其位置及數量應符合下列規定：\n(一)車門係指供乘客於正常情況下使用之門，不含鄰近駕駛座左側供駕駛\n人出入之門。車門應設於右側，且下層車廂應至少設置兩個車門。\n(二)除上層為部分或全部無車頂之市區雙層公車（以下簡稱開放式市區雙\n層公車）其上層車廂外，各層車廂出口總數應符合下列規定，其中可供\n二個量測車門通道之矩形鑲板併排通過之雙扇車門計為二個車門，中\n線左右兩側區域均符合安全窗尺度與通道規定之雙扇安全窗計為二個\n安全窗，上下層通道可視為車輛上層車廂之一個出口：\n1. 申請核定座立位總數逾十六人但未逾三十人之每層剛性車廂：至少\n四個。\n2. 申請核定座立位總數逾三十人但未逾四十五人之每層剛性車廂：至\n少五個。\n3. 申請核定座立位總數逾四十五人但未逾六十人之每層剛性車廂：至\n少六個。\n4. 申請核定座立位總數逾六十人之每層剛性車廂：至少七個。\n(三)車廂兩側出口數量應相等且兩相鄰出口內緣應有間隔，開放式市區雙\n層公車上層得免符合「車輛兩側出口數量應相等」之規定。對於超過最\n少數量要求之額外出口，其可不必兩側具有相同數量。\n(四)車廂同側二門（車門或安全門）間之距離應不小於車廂全長之百分之四\n十，其距離應於車門（安全門）中心量測，若其中之一為雙扇車門時，\n應於二門間最遠處量測。車廂全長係指第一節車廂最前排乘客座椅椅\n墊前緣與第二節車廂最後排乘客座椅椅背後緣相切於車輛縱向中心面\n之水平距離。\n(五)上層剛性車廂若僅裝置一個車頂逃生口，應裝設於車頂中段；若裝置二\n個時，兩開口內緣應至少間隔二公尺。\n\n(六)緊急狀況下，下層之乘員，無須進入或利用上層車廂即可撤至車外。\n三、出口標識\n(一)緊急出口標識應以中文「緊急出口」及英文「Emergency exit」標識於\n乘客輕易可視之車內及車外緊急出口或其鄰近位置。中文標識字體於\n安全門者，每字至少十公分見方，於安全窗及車頂逃生口者，每字至少\n四公分見方。\n(二)於乘客輕易可視之緊急出口控制裝置或其鄰近位置標示操作方法。\n四、車門\n(一)門框高至少一百八十公分。\n(二)門框寬至少五十五公分。\n(三)在緊急事件發生時，動力操作式車門應可於車輛停止時，藉由符合下列\n規定之控制裝置由車內徒手開啟，且於車門未鎖住時由車外開啟，否則\n不得列入車門數量計算：\n1. 應可獨立控制（不受其他控制裝置控制）。\n2. 車內控制裝置應設置於車門或距車門三十公分之範圍內。\n3. 應於該裝置或其鄰近位置標示操作方法。\n4. 應可由一個人操作使車門開啟。\n5. 得以易破壞之防護遮蓋保護該裝置（應同時以聲音及信號警示駕駛\n人）。\n五、車門通道及上下層通道\n(一)門通道係指車門至最上層階梯外緣（即走道側，未設階梯者應為車門內\n側向內延伸三十公分處）間之通道，車門通道應允許寬度五十五公分，\n高度一百八十公分且厚度為二公分之矩形鑲板，其平面應以乘客離開\n車輛之方向，自走道側垂直穿越車門至車輛外側。\n(二)上下層通道係指由階梯所在之下層地板至最上層階梯外緣（即走道側）\n間之通道，應允許寬度五十五公分，高度一百八十公分且厚度為二公分\n之矩形鑲板，其平面應分別以乘客往上層及往下層階梯之方向垂直穿\n越。\n六、上下層通道階梯扶手和把手\n\n(一)階梯兩側應設置合適之扶手或把手。其應位於各級階梯踏步面上方八\n十公分至一百十公分之間。\n(二)階梯所安裝之扶手及／或把手，其應有利於靠近車輛上層或下層階梯\n處，及各級階梯處之乘客上下階梯使用之抓握點。抓握點應設計於車輛\n下層地板上方或每級階梯踏步面上方，其垂直高度應為八十公分至一\n百十公分之間，且\n1. 對於車輛下層之乘客，其第一階之抓握點應位於第一階之最外緣向\n內不大於四十公分範圍內；及\n2. 對於其他之階梯上方抓握點位置，其向外不應超過該級階梯之最外\n緣，向內應不得大於其階梯最外緣六十公分。\n七、安全門\n(一)有效高至少一百二十五公分。\n(二)有效寬至少五十五公分。\n(三)下緣距地高（指安全門通道或階梯下緣距地高）至多七十公分。\n(四)安全門應設有「防止誤開啟裝置」及該裝置啟動時對駕駛人之聲音警告\n裝置。安全門應能於車輛靜止時由車內及車外開啟，安全門開啟後非經\n外力不得自動關閉。\n(五)安全門車外控制裝置距地高至多一百五十公分。\n八、安全門通道係指走道至安全門間之通道，安全門通道應符合下列規定：\n(一)不得裝設活動式座椅或蓋板且應保持暢通。（安全門通道旁設有活動物\n品者，其所有可能位置均應符合本項規定）\n(二)應允許一疊加圓柱自由通過，該疊加圓柱由一個直徑為三十公分、距離\n地板高度為七十公分的垂直圓柱和一個直徑為五十五公分的垂直圓柱\n構成，這兩個圓柱的總高度為一百四十公分。上圓柱直徑可在頂部減為\n四十公分，其過渡斜面與水平面夾角不得超過三十度，且第一個圓柱體\n的底部應在第二個圓柱體的投影內。\n九、安全窗\n(一)安全窗應為下列兩種型式之一：\n1. 活動式安全窗：應可於車內及車外徒手開啟。若為鉸鍊式安全窗應\n向外開啟，其每面開度均應可達九十度以上。以鉸鍊繫住頂端之安\n\n全窗應裝設適當機構維持開啟。應備有鉸鍊式安全窗開啟時對駕駛\n人之聲音警告裝置，該裝置應由安全窗扣移動來作動，並非由安全\n窗本身移動時來作動。\n2. 玻璃式安全窗：玻璃材質應為符合「車輛安全檢測基準」中「安全玻\n璃」之強化安全玻璃且應易碎，並應於新登檢領照時由申請者提出\n相關證明文件。\n(二)安全窗窗框之內高乘以內寬至少四千平方公分，其應至少容納尺度五\n十公分×七十公分之矩形。\n(三)裝於車輛後方且無法符合上述尺度之安全窗應至少容納高三十五公分，\n寬一百五十五公分且邊角曲率半徑不逾二十五公分之矩形。\n(四)車輛側方安全窗下緣距車內地板之高度應不大於一百二十公分，且若\n為鉸鍊式安全窗不得小於六十五公分，若為玻璃式安全窗不得小於五\n十公分。若鉸鍊式安全窗之窗框裝設距車內地板高六十五公分之防護\n裝置，以防範乘客掉出車外，其下緣距車內地板高可減少至五十公分，\n且防護裝置上方之窗框尺度應不得小於前款安全窗尺度之規定。\n十、安全窗通道係指走道至安全窗間之通道，應允許尺度四十公分×六十公分，\n厚度二公分且邊角曲率半徑為二十公分之薄板，其平面應以乘客離開車輛\n之方向，自走道側垂直穿越安全窗至車輛外側。無法符合上述規定之車輛\n後方安全窗通道得以尺度三十五公分×一百四十公分，厚度二公分且邊角曲\n率半徑為十七點五公分之薄板代替。安全窗前設有活動物品者，其所有可\n能位置均應符合本項規定。\n十一、 車窗擊破裝置（開放式市區雙層公車之車輛上層得免符合本項規定）\n(一) 駕駛人附近應至少一具。\n(二) 每扇玻璃式安全窗鄰近處至少一具。\n(三) 應於該裝置附近且於乘客輕易可視之處標示「車窗擊破裝置」之標\n識字體和操作方法，標識字體每字至少四公分見方。\n(四) 未設有玻璃式安全窗者，得免符合本項規定。\n十二、 車頂逃生口（開放式市區雙層公車之車輛上層得免符合本項規定）\n(一) 車頂逃生口應可由車內及車外徒手開啟，其有效面積至少四千平方\n公分，且應至少容納尺度五十公分×七十公分之矩形。\n\n(二) 應允許銳角二十度且高一百六十公分之垂直三角板，其頂端接觸車\n頂逃生口框架內緣時（若車頂厚度逾十五公分時，其頂端應接觸車\n頂逃生口外側表面之框架），底邊可接觸座椅或支撐物。若支撐物\n為折疊式或可移動式，其使用時應可被鎖定。\n十三、 階梯\n(一) 深度：\n1. 離地第一階表面應至少容納四十公分×三十公分之矩形，其他階\n梯應至少容納四十公分×二十公分之矩形，矩形區域內最大坡度\n應不逾三度。\n2. 前目規定之階梯表面外緣突出下一階梯至多十公分，且階梯表面\n之有效垂直投影深度至少二十公分。\n(二) 高度：\n1. 離地第一階：於車門者至多三十四公分，於安全門者至多七十公\n分。離地第一階高度以在空車狀態時踏板上表面與地面間之距離\n為準。\n2. 其他階梯：至少十二公分，至多二十五公分。\n(三) 伸縮式階梯應符合下列規定：\n1. 當車門或安全門關閉時，突出車身部分應不逾一公分。\n2. 當車門或安全門開啟且其位於伸展位置時，其階梯深度應符合規\n定。\n3. 當其位於伸展位置時，車輛應無法移動。當車輛移動時，其應無\n法伸展。\n(四) 上下層通道階梯設計應避免乘客於車輛行駛狀態中急遽煞車時向\n下跌落。若符合下述條件任一項，則視為符合本項要求：\n1. 階梯無任何部分為朝向車前遞降之設計；\n2. 階梯配有防護裝置或類似安全設施；\n3. 階梯之最上方設有一可防止於車輛行駛時使用階梯之自動裝置；\n且該裝置能在緊急情況下易於操作。\n(五) 上下層通道之各級階梯應為封閉式之設計。\n\n十四、 走道係指平行車輛縱向中心線，自每一節剛性車廂最前排乘客座椅椅背\n後緣至最後排乘客座椅椅墊前方三十公分之通道空間，並得延伸至車門\n通道及安全門通道，但不包括前置式引擎隆起區域旁之乘客座椅椅背後\n緣以前之通道空間。走道應符合下列規定：\n(一) 不得設置活動式座椅。\n(二) 上層走道有效寬至少四十五公分，走道內高至少一百六十八公分，\n並應能允許直徑四十五公分，高度一百六十八公分之圓柱體垂直順\n利通過；下層走道有效寬至少四十五公分，走道內高至少一百八十\n公分，並應能允許直徑四十五公分，高度一百八十公分之圓柱體垂\n直順利通過。若圓柱體可能會與供立位乘客使用之活動式扶手或拉\n桿或拉環接觸時可將其移開。\n(三) 車輛上層走道應連接至一個或一個以上之上下層通道，且其應連接\n至車門通道處或距車門三公尺內之下層走道處。\n(四) 上層之乘客座位數逾五十人者，其上下層通道應至少為兩個（其中\n一個可為連接至安全門出口之設計）。\n十五、 乘客座椅（駕駛座右側服務員座椅除外）\n(一) 乘客座椅前方為安全門通道或車門通道者，其座椅空間地板與其前\n方地板高度差逾十二公分時應設置欄杆或保護板，欄杆或保護板上\n緣距座椅空間地板高度至少八十公分，欄杆或保護板寬度應從車身\n側邊向車內延伸至超出該座椅的縱向中心線至少十公分，或者延伸\n至最裡面一級階梯的豎板（取兩者之中的較小尺寸）。\n(二) 椅墊最上方之水平面與距地高六十二公分之水平面間，水平量測其\n座椅椅背前緣至前方座椅椅背（欄杆或保護板）後緣間之椅距：應\n至少六十五公分。\n(三) 水平量測其椅墊前緣至前方欄杆或保護板後緣間之距離至少應為\n二十八公分。\n(四) 椅墊前緣至椅墊最深處之距離：應至少三十五公分。\n十六、 開放式市區雙層公車其車輛上層無車頂區域應依下列規定設置乘員防護\n裝置：\n\n(一) 應具備連續前方護板，連續之前方護板應涵蓋整個車身全寬，以前\n方護板所在處之車內地板為量測基準，其高度應不小於一百四十公\n分。若使用玻璃於護板，則其玻璃應符合本基準中「安全玻璃」之\n擋風玻璃規定。\n(二) 應具備連續之側方及後方防護裝置，以該防護裝置所在處之車內地\n板為量測基準，其側方防護裝置之高度應不小於一百一十公分；後\n方防護裝置，其高度應不小於一百二十公分；若使用玻璃於護板，\n則其玻璃應符合本基準中「安全玻璃」之強化玻璃規定。在前述高\n度範圍內，防護裝置應為連續護板式；若在前述高度範圍內非為連\n續護板式，則防護裝置應至少在自車內地板至距地高七十公分之間\n為連續護板，而其上方使用一個以上連續護欄者，其護欄安裝應符\n合下列規格：\n1. 其斷面高度應不小於二公分且不大於四點五公分。\n2. 護板與欄杆之間距及欄杆與欄杆之間距應不大於二十公分。\n(三) 應牢固地固定於車輛結構上。\n(四) 出口處之車門應視為構成該防護裝置之一部分。\n(五) 擋風玻璃與最前排座椅之間，應設置能防止衝擊之保護設施。\n十七、 開放式市區雙層公車應依下列規定設置車內視野和通訊裝置：\n(一) 應裝設相關視覺設備，以使駕駛人可透過鏡子、攝影機及監視器等，\n觀察車輛上層乘客狀況。\n(二) 應提供一內部通訊系統以利駕駛能將訊息通知到該處乘客。\n十八、 其他：\n(一) 申請核定下層立位空間者，應設置扶手或拉桿或拉環，且應於駕駛\n座之後部設置駕駛座欄杆。\n(二) 駕駛區為無車頂設計時，應具有專用保護設施，防止駕駛人受天候\n或環境變化等之影響。\n(三) 上層通道口應設有一個遮蔽式防護裝置，該裝置之上緣距地高應至\n少八十公分，下緣與所在地板之距離應不大於十公分。\n(四) 各上下層通道最上方處，應設置至少一盞以上之照明裝置。\n\n(五) 開放式市區雙層公車之車廂無車頂區域，或經公路主管機關核准可\n使用行駛高速公路及快速公路路線之雙層公車全部座位，應設置繫\n妥安全帶之提醒標誌。"},{"file_id":"0000420182","name":"附件七 車輛燈光與標誌檢驗規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000420182&lan=C","fetched":true,"bytes":234354,"pages":9,"text":"第三十九條、第三十九條之二附件七修正規定\n附件七 車輛燈光與標誌檢驗規定\n一、汽車及拖車之燈光與標誌檢驗規定\n(一) 頭燈（head lamp）：拖車不適用。\n1. 應為二燈式或四燈式，左右對稱裝設。\n2. 燈色可為白色或淡黃色，左右燈色應一致。\n3. 頭燈裝設位置，近光燈基準中心距地高在空車狀態時，應在零點\n五公尺至一點四公尺以下；總重量逾十二公噸之大貨車最大高度\n可增至一點五公尺。（四燈縱列式以上燈基準中心為準），近光燈\n照明面外緣距車身（不包括後視鏡）外緣應在四十公分以內。\n4. 中華民國九十七年六月三十日前登檢領照車輛之遠光（main-\nbeam）燈照明面內緣間距應不大於近光（dipped-beam）燈照明\n面內緣間距。\n(二) 車寬燈（clearance/front position lamp）：車寬小於一點六公尺之拖\n車，可免符合本項規定。\n1. 燈色應為白色、淡黃色或橙色，左右並應為同顏色。\n2. 裝設位置：燈具照明面上緣距地高在空車狀態時應在二點一公尺\n以下且左右同高。\n(三) 尾燈（tail/rear position lamp）：\n1. 燈色應為紅色。\n2. 裝設位置：燈具照明面上緣距地高在空車狀態時應在二點一公尺\n以下，燈具照明面外緣距車身外緣（不包括後視鏡）應在四十公\n分以內。除小型汽車外，其左右兩燈具照明面內緣間隔應為車寬\n之四分之一以上並對稱裝設（全寬小於一點三公尺除外）；裝置一\n組以上時僅有一組符合即可。\n(四) 煞車燈（stop lamp）：\n1. 燈色應為紅色，亮度應較尾燈明亮。\n2. 裝設位置：燈具照明面上緣距地高在空車狀態時應在二點一公尺\n以下，左右兩燈具照明面內緣間隔應為車寬之四分之一以上並對\n稱裝設（全寬小於一點三公尺除外）；裝置一組以上時僅有一組符\n合即可。\n3. 踩下煞車踏板時，應為續亮，不得閃爍，但配備符合車輛安全檢\n測基準「緊急煞車訊號」功能者，不在此限。\n(五) 第三煞車燈（high mounted/S3 lamp）：除小客車適用外，若各型車\n輛裝置第三煞車燈時，本項規定亦應適用。\n\n\n1. 自中華民國八十四年七月一日起新登檢領照之小客車應裝置第三\n煞車燈。\n2. 燈色應為紅色。\n3. 第三煞車燈應裝置於車後中線且其基準中心應高於煞車燈基準中\n心。其車後中線處為可動件（如門板），缺乏足夠空間安裝燈具者，\n可容許燈具基準中心偏移車後中線十五公分內裝設或以兩具相同\n尺寸之煞車燈對稱車後中線裝設。踩下煞車踏板時，應為續亮，\n不得閃爍。\n(六) 方向燈（direction indicator/turn signal lamp）：除汽車適用外，若拖\n車前方裝置方向燈，本項規定亦應適用。\n1. 燈色應為橙色或黃色，但方向燈鄰近淡黃色頭燈者限用橙色，車\n後之方向燈並得為紅色。\n2. 燈具照明面上緣距地高在空車狀態時應在二點三公尺以下，左右\n兩燈具應對稱裝設；裝置一組以上時僅有一組符合即可。\n3. 燈具照明面內側間隔應為六十公分以上（但車寬在一百三十公分\n以下者，則其間隔應在四十公分以上），照明面最外側與車身最外\n緣之間距應在四十公分以下，裝置側面方向燈者可不受此限制；\n裝置一組以上時僅有一組符合即可。\n4. 閃爍次數每分鐘在六十次以上，一百二十次以下。\n(七) 後號牌燈（rear registration plate lamp）：\n1. 燈色應為白色。\n2. 號牌燈應安裝於車後號牌上方、下方或左右兩側。\n3. 應有適當覆蓋保護且光型應不影響後方來車之行車視野。\n(八) 倒車燈（reversing lamp）：除汽車適用外，若拖車裝置倒車燈，本\n項規定亦應適用。\n1.  倒車燈盞數應為一盞或二盞。\n2. 燈色應為白色。\n3. 裝設位置：基準中心距地高在空車狀態時應在一點二公尺以下。\n4. 應與變速裝置連動，亦即排檔桿置於「倒檔」位置時亮燈。\n(九) 危險警告燈（hazard warning lamp）：\n1. 自中華民國八十三年七月一日起新登檢領照之汽車應裝置危險警\n告燈。\n2. 除燈光顯示時，左右同亮外，其餘各點規定與方向燈規定相同。\n(十) 計程車車頂燈：多元化計程車不得設置。\n1. 盞數應為一盞。\n2. 燈色不得為紅色。\n\n\n3. 安裝位置：應固定於車頂前半部適當位置，不得以磁鐵吸住方式\n安裝。\n(十一) 汽車後方非三角形反光標誌（rear retro- reflecting /reflex reflecting\ndevice，non-triangular）：自中華民國九十一年七月一日起新登檢\n領照之汽車應符合本項規定。\n1. 反光顏色應為紅色。\n2. 反光面距地高在空車狀態時，上緣應在一點五五公尺以下；下緣\n應在零點二五公尺以上；裝置一組以上時僅有一組符合即可。\n(十二) 拖車後方三角形反光標誌（rear retro-reflecting /reflex reflecting\ndevice, triangular）：自中華民國九十一年七月一日起新登檢領照\n之拖車應符合本項規定。\n1. 反光顏色應為紅色，三角形頂點向上。\n2. 反光面距地高在空車狀態時，上緣應在零點九公尺以下（因車體\n結構無法配合者應在一點五公尺以下）；下緣應在零點二五公尺以\n上。反光面外緣距車身外緣應在四十公分以內，內側間隔應在六\n十公分以上（但車寬在一百三十公分以下者，則其間隔應在四十\n公分以上）。\n(十三) 拖車前方非三角形反光標誌（front retro-reflect-ing/reflex reflect-\ning device, non-triangular）：自中華民國九十一年七月一日起新登\n檢領照之拖車應符合本項規定。\n1. 反光顏色應為無色（或稱白色）透明或黃色。\n2. 反光面距地高在空車狀態時，上緣應在零點九公尺以下（因車體\n結構無法配合者應在一點五公尺以下）；下緣應在零點二五公尺以\n上。反光面外緣距車身外緣應在十五公分以內，內側間隔應在六\n十公分以上（但車寬在一百三十公分以下者，則其間隔應在四十\n公分以上）。\n(十四) 汽車（車長六公尺以上者）及拖車側方非三角形反光標誌\n（intermediate side retro-reflecting/ reflex reflecting device, non-tri-\nangular）：自中華民國九十一年七月一日起新登檢領照之汽車及\n拖車應符合本項規定。\n1. 反光顏色在前端及中央者應為橙色、在後端者應為紅或橙色。\n2. 反光面距地高在空車狀態時，上緣應在二公尺以下；下緣應在零\n點二五公尺以上。除小型汽車外，其兩相鄰反光面外緣間距不得\n超過三公尺（因車體結構無法配合者不得超過四公尺），車長三分\n之一至三分之二間至少裝設一個反光標誌，最前端之反光標誌其\n前緣距車輛前端不得超過三公尺；後端之反光標誌後緣距車輛後\n\n\n端不得超過一公尺。前端、後端反光標誌間距超過三公尺時，應\n視車長再加裝側方反光標誌。\n(十五) 汽車（車長六公尺以上者）及拖車側方標識燈（side marker\nlamp）：自中華民國九十一年七月一日起新登檢領照之汽車及拖\n車應符合 本項規定。\n1. 顏色在前端及中央者應為橙色、在後端者應為紅或橙色。\n2. 照明面距地高在空車狀態時，上緣應在二點一公尺以下；下緣應\n在零點二五公尺以上。兩相鄰照明面外緣間距不得超過三公尺\n（因車體結構無法配合者不得超過四公尺），車長三分之一至三分\n之二間至少裝設一個側方標識燈，最前端之標識燈照明面前緣距\n車輛前端不得超過三公尺；後端之標識燈照明面後緣距車輛後端不\n得超過一公尺。前端、後端標識燈照明面外緣間距超過三公尺時，\n應視車長再加裝側方標識燈。\n(十六) 重型拖車車身側方及後方帶狀反光識別材料（side and rear retro-\nreflective marking with strips）：中華民國九十九年六月三十日前\n登檢領照之總重逾三點五公噸之重型拖車應符合本項規定。\n1. 側方反光識別材料之反光顏色應為紅色、白色或黃色；後方反光識\n別材料之反光顏色應為紅色。\n2. 反光識別材料距地高在空車狀態時，上緣應在一點五公尺以下（因\n車體結構無法配合者應在二點一公尺以下）；下緣應在零點二五公\n尺以上。\n3. 反光識別材料標識車身兩側前後應各裝置一公尺，後方裝置應盡可\n能顯示車輛之全寬，且至少為全寬之百分之八十（如與後方標示牌\n照號碼位置有干涉者，該位置得免裝置），且寬度應為零點零五公\n尺（正零點零一公尺，負零公尺）。\n4. 非連續之帶狀反光識別材料之間的距離，應盡可能縮短，且不得超\n過裝置之最短反光識別材料長度之百分之五十。\n(十七) 重型拖車車身側方及後方帶狀反光識別材料（side and rear retro-\nreflective marking with strips）：自中華民國九十九年七月一日起\n登檢領照之總重逾三點五公噸之重型拖車應符合本項規定。\n1. 車身標示用反光標識應符合車輛安全檢測基準中「反光識別材料」\n之規定。\n2. 標識尺寸：側邊及後部標識，其材質需為帶狀反光識別材料，且寬\n度應為零點零五公尺（正零點零一公尺，負零公尺）。\n3. 帶狀之側邊及後部標識之形狀裝置要求：\n(1) 車輛安裝反光識別材料可以用一個元件，或多個元件連續不\n\n\n斷緊密形成。但需平行或者盡可能與地面平行。\n(2) 車輛之後部標識，其顏色應為紅色或黃色。\n(3) 車輛之側邊標識，其顏色應為白色、黃色或紅色。\n(4) 標識裝置應盡可能顯示車輛之全寬或全長，或其至少為全寬\n或全長之百分之八十。\n(5) 非連續之帶狀元件之間的距離，應盡可能縮短，且不應該超\n過最短的元件長度之百分之五十。\n(6) 反光識別材料距地高在車輛無負載狀態時最小為零點二五公\n尺，最大為一點五公尺。若受技術條件限制時，其最大值可\n調整為二點一公尺。\n(7) 車輛後方之反光識別材料距離煞車燈應大於零點二公尺。\n二、機車燈光與標誌檢驗規定\n(一) 頭燈：\n1. 應為單燈式，或二燈式對稱裝設。全寬超過一點三公尺之大型重型\n三輪機車應為二燈式對稱裝設。\n2. 燈色可為白色或淡黃色，二燈式左右燈色應一致。\n3. 裝設位置：近光燈照明面距地高在空車狀態時，上緣應在一點二公\n尺以下；下緣應在零點五公尺以上。全寬超過一點三公尺之大型重\n型三輪機車，其沿發光中心點垂直軸方向兩燈之外表面內緣間距應\n在零點五公尺以上。\n(二) 尾燈：\n1. 數量應為一盞或二盞，全寬超過一點三公尺之大型重型三輪機車應\n為二燈式對稱裝設。\n2. 燈色應為紅色，頭燈開啟時，尾燈應同時開啟，且不可單獨熄滅。\n3. 裝設位置：照明面距地高在空車狀態時，上緣應在一點五公尺以下；\n下緣應在零點二五公尺以上。全寬超過一點三公尺且後方為二輪型\n式之大型重型三輪機車，則其二燈間距應在零點六公尺以上。\n(三) 煞車燈：\n1. 燈色應為紅色，亮度應較尾燈明亮。\n2. 應為單燈式，或二燈式對稱裝設，全寬超過一點三公尺之大型重型\n三輪機車應為二燈式對稱裝設。\n3. 裝設位置：照明面距地高在空車狀態時，上緣應在一點五公尺以下；\n下緣應在零點二五公尺以上。全寬超過一點三公尺且後方為二輪型\n式之大型重型三輪機車，則其二燈間距應在零點六公尺以上。\n4. 機車煞車作用時，煞車燈應為續亮，不得閃爍。但配備符合車輛安\n\n\n全檢測基準「緊急煞車訊號」功能者，不在此限。\n(四) 方向燈：\n1. 燈色應為橙色。\n2. 照明面距地高在空車狀態時，上緣應在一點二公尺以下；下緣應在\n零點三五公尺以上。\n3. 閃爍次數每分鐘在六十次以上，一百二十次以下。\n4. 中華民國九十二年一月一日起之新車型及中華民國九十四年一月\n一日起新登檢領照之新車應符合本項規定：前方向燈之照明面內緣\n距二十四公分以上；後方向燈之照明面內緣距十六公分以上。\n(五) 號牌燈：\n1. 燈色應為白色。\n2. 號牌燈應安裝於車後號牌上方、下方或左右兩側。\n3. 應有適當覆蓋保護且光型應不影響後方來車之行車視野。\n(六) 後方反光標誌：\n1. 機車後方反光標誌反光顏色應為紅色，且不得為三角形。\n2. 反光面距地高在空車狀態時，上緣應在零點九公尺以下；下緣應在\n零點二五公尺以上。\n3. 全寬超過一點三公尺之大型重型三輪機車，其沿反光面中心方向兩\n外表面內緣間距應在零點五公尺以上。\n(七) 倒車燈：\n1. 除身心障礙者用特製車外，設有倒車裝置者，應符合本項規定。\n2. 倒車燈盞數應為一盞或二盞。\n3. 燈色應為白色。\n4. 裝設位置：位於車輛後方，基準中心距地高在空車狀態時應在一點\n二公尺以下，零點二五公尺以上。\n5. 應與變速裝置連動，亦即排檔桿置於「倒檔」位置時亮燈。\n三、車輛因行車安全或特定操作之需，得裝置符合下列規定之輔助燈光與\n標誌。\n(一) 大型汽車及拖車輪廓邊界標識燈（end outline marker lamp）：\n1. 顏色在前方者應為白色或黃色、在後方者應為紅色。\n2. 裝置位置以能表示車輛寬度為前提並盡可能接近車頂裝設。\n(二) 大型汽車及拖車辨識燈（identification lamp）：\n1.  顏色在前方者應為橙色、黃色或綠色、在後方者應為紅色；前方\n無兼具速率指示功能之辨識燈，其顏色不得為綠色。\n2. 前或後方各三個，兼具速率指示功能者，應面朝車前方向。\n\n\n(三) 汽車前角燈（cornering lamp）：\n1. 顏色應為白色或黃色。\n2. 兩側各一個，其操作與方向燈連動，應能於轉向方向提供恆亮照明。\n(四) 汽車晝行燈（daytime running lamp）：\n1.  燈具照明面內側間隔應為六十公分以上（但車寬在一百三十公分\n以下者，則其間隔應在四十公分以上）；上緣應在一點五公尺以下，\n下緣應在零點二五公尺以上。\n2. 顏色應為白色或淡黃色。左右對稱裝設。\n3. 利用近光燈以光度切換達成者：同近光燈之規定，但使用遠光燈以\n光度切換達成者，燈具基準中心距地高在空車狀態時，應在零點九\n公尺以下。\n(五) 汽車工作燈或聚光燈（working/ cargo lamp, spot lamp）：\n1.  顏色應為白色或淡黃色；依實際需要裝設。\n2. 其開關不得與其他燈光連動。\n3. 可於行駛中使用而有影響他車行車視野者，應使用適當之固定遮蔽\n裝置。\n(六) 霧燈（fog lamp）：\n1. 前霧燈盞數應為二盞，左右對稱裝設；後霧燈得為一盞或二盞。\n2. 前霧燈限用黃色或淡黃色或白色；後霧燈限用紅色。\n3. 前霧燈之照明面上緣不得高於近光燈之照明面上緣。\n4. 前霧燈與頭燈不得連動。除非頭燈或前霧燈或車寬燈或尾燈點亮，\n否則後霧燈不得點亮，裝置前霧燈時，後霧燈應能單獨熄滅。\n5. 後霧燈基準中心與煞車燈基準中心間距應大於零點一公尺。\n(七) 機車霧燈：\n1. 前、後霧燈盞數應為一盞或二盞，裝置一盞時基準中心應在中心縱\n向面上或使照明面內緣距中心縱向面小於零點二五公尺，兩盞時應\n左右對稱裝設。全寬超過一點三公尺且後方為二輪型式之大型重型\n三輪機車，則其後霧燈間距應在零點六公尺以上。\n2. 前霧燈限用黃色或淡黃色或白色；後霧燈限用紅色。\n3. 前霧燈之照明面不得高於近光燈照明面上緣，距地高度應在零點二\n五公尺以上。後霧燈距地高度應介於零點二五公尺至零點九公尺之\n間且其基準中心與煞車燈基準中心間距應大於零點一公尺。\n4. 前霧燈與頭燈不得連動。除非頭燈或前霧燈點亮，否則後霧燈不得\n點亮，裝置前霧燈時，後霧燈應能單獨熄滅。\n(八) 機車側方非三角形反光標誌：\n1. 機車側方反光標誌反光顏色應為橙色或紅色，且不得為三角形。\n\n\n2. 反光面距地高在空車狀態時，距地高度應介於零點三公尺至一公尺\n之間，且於正常狀況下須不被駕駛或乘客之衣物遮蔽。\n(九) 機車輔助煞車燈：\n1. 顏色應為紅色。\n2. 燈具基準中心應在中心縱向面上並高於其他後方燈具。\n3. 應為續亮，不得閃爍。\n(十) 機車前位置燈：\n1. 燈色應為白色或淡黃色。\n2. 應為單燈式，或二燈式對稱裝設，全寬超過一點三公尺之大型重型\n三輪機車應為二燈式對稱裝設。\n3. 裝設位置：照明面距地高在空車狀態時，上緣應在一點二公尺以下，\n下緣應在零點三五公尺以上。\n(十一) 機車危險警告燈（hazard warning lamp）：除燈光顯示時，左右應\n同亮外，並不得與其他燈光連動，其餘各項規定與機車方向燈規\n定相同。\n(十二) 機車晝行燈（daytime running lamp）：\n1. 應為單燈式，或二燈式對稱裝設。\n2. 燈色可為白色或淡黃色，二燈式左右燈色應一致。\n3. 裝設位置：照明面距地高在空車狀態時，應在零點二五至一點五公\n尺之間。\n(十三) 機車停車燈（parking lamp）：\n1. 應於車輛靜止時持續點亮不得閃爍。\n2. 燈色在前方者應為白色或淡黃色，在後方者應為紅色。\n(十四) 拖車後方非三角形反光標誌：同前一、之（十一）規定。\n(十五) 汽車前方反光標誌：同前一、之（十三）規定。但反光面外緣距\n車身（不包括後視鏡）外緣應在四十公分以內。\n(十六) 車長六公尺以下（含）之汽車側方非三角形反光標誌：\n1. 反光顏色在前端及中央者應為橙色、在後端者應為紅或橙色。\n2. 反光面距地高在空車狀態時，上緣應在二公尺以下；下緣應在零點\n二五公尺以上。至少裝設一個反光標誌於車長前三分之一或後三分\n之一以內處。\n(十七) 車長六公尺以下（含）之汽車側方標識燈：\n1. 顏色在前端及中央者應為橙色、在後端者應為紅或橙色。\n2. 照明面距地高在空車狀態時，上緣應在二點一公尺以下；下緣應在\n零點二五公尺以上。至少裝設一個側方標識燈於車長前三分之一\n或後三分之一以內處。\n\n\n(十八) 汽車及拖車側面方向燈：\n1. 燈數為二或四個，左右對稱裝設。\n2. 燈色應為橙色或黃色。\n3. 燈具照明面上緣距地高在空車狀態時應在一點五公尺以下（因車體\n結構無法配合者應在二點三公尺以下），其照明面後緣與車身前緣\n之間距應在一點八公尺以下（因車體結構無法配合者應在二點五公\n尺以下）。\n4. 閃爍次數每分鐘在六十次以上，一百二十次以下。\n(十九) 汽車及拖車停車燈（parking lamp）：\n1. 無論引擎是否啟動，線路設計應使同側燈具之點滅能獨立操作。\n2. 燈色前方應為白色、淡黃色或橙色，後方應為紅色。若以其他燈具\n達到此燈功能者，依原燈具之顏色。\n3. 燈具照明面上緣距地高在空車狀態時應在一點五公尺以下（因車體\n結構無法配合者應在二點一公尺以下），其照明面外緣距車身外緣\n（不包括後視鏡）應在四十公分以內。以側面方向燈作為停車燈者\n依側面方向燈之規定。\n(二十) 車身標示用反光標識：\n1. 顏色為白色、黃色或紅色，可相間使用。\n2. 裝設位置以能表示車身長度、寬度或高度為原則。\n四、非屬前三點所列之燈光，須經主管機關核定後，方能裝置。"},{"file_id":"0000272840","name":"附件八 危險物品標誌及標示牌內容及應列要項.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000272840&lan=C","fetched":true,"bytes":503201,"pages":1,"text":"8\n\n附件八\n危險物品標誌及標示牌內容及應列要項：\n一、危險物品標誌：形狀為直立四十度角之正方形(菱形)，其最小尺\n度如圖一，如為小型車，其尺度得減半；標誌之圖例及顏色依中\n華民國國家標準CNS6864。車輛應懸掛或黏貼所裝載危險物品主要\n特性之危險物品標誌，亦得同時懸掛或黏貼危險物品主要特性及\n次要性之危險物品標誌；若危險物品無法依類別歸類者，則免懸\n掛或黏貼危險物品標誌。\n二、標示牌：標示內容應含危險物品名稱、聯合國物質編號(UN NO.)\n及緊急聯絡電話，其格式及最小尺寸如圖二，以白底紅字正楷字\n體標明，如為小型車，其尺度得減半。危險物品名稱以中文為主，\n必要時得加註英文；聯合國物質編號(UN NO.)用以查詢意外事故\n處理原則及應注意事項，如裝載之危險物品尚無聯合國物質編號，\n則以處理原則號碼替代；緊急聯絡電話應含區域號碼。\n三、危險物品標誌及標示牌應以反光材料製作，文字為正楷，運輸過\n程中應不致產生變形、磨損、褪色及剝落等現象而能辨識清楚。\n四、車輛左、右兩側及後方均應於明顯適當位置懸掛或黏貼危險物品\n標誌及標示牌；危險物品標誌及標示牌應緊靠懸掛或黏貼，倘因\n空間不足致緊靠困難時，亦得分開懸掛或黏貼。"},{"file_id":"0000233128","name":"附件九液化石油氣汽車改裝完成檢驗合格紀錄表.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000233128&lan=C","fetched":true,"bytes":112176,"pages":1,"text":"附件九  液化石油氣汽車改裝完成檢驗合格紀錄表\n                     改裝序號：\n牌照號碼 廠       牌 型            式\n營業用或自用 車        別\n\n\n\n\n\n車身號碼\n\n\n液\n化\n石\n油\n氣\n容\n器\n\n內   容   積    公升   個\n引擎號碼\n\n\n廠        牌\n燃料裝置\n單   燃   料\n號        碼\n雙   燃   料\n檢 查 日 期\n  年   月\n公司登記證明文件編號\n\n工廠登記或商業登記證明文件編號\n\n車輛專業技術研究機構檢測合格編號\n\n檢\n驗\n方\n法\n及\n結\n果\n\n高壓配管之氣密性\n18 ㎏f/㎝2 不燃性氣體檢驗結果：\n液化石油氣容器置室之氣密性\n二氧化碳檢驗法測結果：\n發煙劑檢驗法檢測結果：\n整套裝置之安裝狀態\n有無異常\n燃料系統零組件是否經商品檢驗機關驗證合格\n是    否\n檢驗合格日期\n改裝技術人員\n  年  月  日  簽章\n委託人姓名\n地   址\n              簽章\n\n改裝工廠名稱\n地    址\n負  責  人\n公\n司\n章\n\n負人\n責章"},{"file_id":"0000007001","name":"附件九液化石油氣汽車改裝完成檢驗合格紀錄表.DOC","format":"DOC","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000007001&lan=C","fetched":true,"bytes":28672},{"file_id":"0000412352","name":"附件十 液化石油氣汽車燃料系統檢驗規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000412352&lan=C","fetched":true,"bytes":248917,"pages":2,"text":"第三十九條附件十\n附件十 液化石油氣汽車燃料系統檢驗規定\n一、液化石油氣容器之有效使用期限距車輛檢驗日期至少半年以上。\n二、液化石油氣容器裝置室及配管之氣密檢驗，按下列三種方法擇一檢驗：\n(一)使用檢視液檢驗：以肥皂液塗於所有配管接頭，上並全開液化石油\n氣容器出口開關，不得有氣泡產生。\n (二)使用氣體測漏器檢查：將液化石油氣容器出口開關全開，以測漏\n器檢查所有配管接頭，不得有漏氣現象。\n (三)使用壓力計檢驗：將壓力計與配管連接，開於液化石油氣容器出\n口開關，使用氮氣將其壓力調整至與液化石油氣的操作壓力相同，\n並開氮氣開關壓力計達到操作壓力（kgf/c）後關斷試壓用開關，\n觀察一分鐘壓力表示不得有降壓現象。\n三、液化石油氣汽車新車型或改裝車型之燃料系統應經車輛專業技術研究機\n構審檢合格，其應審驗項目如下：\n (一)書面審查部分：\n   1.規格表。\n   2.液化石油氣（LPG）系統主要構造及裝置明細表（名稱、型式、\n廠牌、規格）。\n   3.全車三視圖及外觀相片、液化石油氣（LPG）系統安裝概要及主\n要構造及裝置安裝相片。主要構造及裝置安裝相片至少應包含：\n  (1)引擎室全景及蒸發器、低壓軟管、電磁閥、濾清器。\n  (2)駕駛室液化石油氣（LPG）切斷開關。\n  (3)充填口。\n   4.燃料管線配置圖及說明。\n   5.瓦斯容器配置圖及說明（瓦斯容器擺設位置及安裝方式）。\n   6.瓦斯容器氣密室之氣密性及瓦斯洩漏之排除法。\n(二)實車檢測部分：（參CNS12916D1067）\n  1.燃氣構造之安裝檢驗：\n\n\n  (1)液化石油氣（LPG）容器之固定裝置。\n  (2)液化石油氣（LPG）容器之安裝。\n  (3)灌氣用快速接頭之安裝。\n  (4)蒸發調壓裝置之安裝。\n  (5)燃氣控制閥及過濾器之安裝。\n  (6)配管之安裝。\n  2.配管之氣密檢驗：\n  (1)檢視液。\n  (2)氣體測漏器。\n  (3)壓力計。\n  3.液化石油氣（LPG）容器儲藏室之氣密檢驗：（可使用下列任一\n方法）\n  (1)二氧化碳檢驗法。\n  (2)發煙劑檢驗法。"},{"file_id":"0000264873","name":"附件十一 車輛總重量及總聯結重量限制規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000264873&lan=C","fetched":true,"bytes":131468,"pages":2,"text":"附件十一 車輛總重量及總聯結重量限制規定\n一、除曳引車、半拖車、拖架及專供營建工程不具載貨空間特種車以外之大型車輛\n總重量\n軸組型態\n最遠軸距\n前單軸後單軸\n車輛\n前雙軸後單\n軸車輛\n前單軸後雙\n軸車輛\n前雙軸後雙軸\n車輛\n全拖車\n二公尺\n十六公噸\n十六公噸\n十六公噸\n十六公噸\n十六公噸\n二點五公尺\n十七公噸\n十七公噸\n十七公噸\n十七公噸\n十七公噸\n三公尺\n十八公噸\n十八公噸\n十八公噸\n十八公噸\n十八公噸\n三點五公尺\n十八點五公噸十九點五公\n噸\n十九點五公\n噸\n十九點五公噸十九點五公噸\n四公尺\n十八點五公噸\n二十公噸\n二十點五公\n噸\n二十點五公噸\n二十公噸\n四點五公尺\n十八點五公噸\n二十公噸\n二十一點五\n公噸\n二十一點五公\n噸\n二十公噸\n五公尺\n十八點五公噸\n二十公噸\n二十二點五\n公噸\n二十二點五公\n噸\n二十公噸\n五點五公尺\n十八點五公噸\n二十公噸\n二十四公噸\n二十四公噸\n二十公噸\n六公尺\n十八點五公噸\n二十公噸\n二十五公噸\n二十五公噸\n二十公噸\n六點五公尺\n十八點五公噸\n二十公噸\n二十六公噸\n二十六公噸\n二十公噸\n七公尺\n十八點五公噸\n二十公噸\n二十六公噸\n二十七公噸\n二十公噸\n七點五公尺\n十八點五公噸\n二十公噸\n二十六公噸\n二十八公噸\n二十公噸\n八公尺\n十八點五公噸\n二十公噸\n二十六公噸\n二十九點五公\n噸\n二十公噸\n八點五公尺\n十八點五公噸\n二十公噸\n二十六公噸\n三十公噸\n二十公噸\n九公尺\n十八點五公噸\n二十公噸\n二十六公噸\n三十一公噸\n二十公噸\n九點五公尺以\n上\n十八點五公噸\n二十公噸\n二十六公噸\n三十二公噸\n二十公噸\n附註：\n(一) 本表係依車輛最遠軸距及軸組別，表列車輛總重限制值。\n(二) 查表方式為表列最遠軸距採下限值，及無條件捨去公尺為單位之小數點後\n第二位數字。\n(三) 例如：車輛實際最遠軸距值為四點五三公尺，軸組別為前單軸後單軸，則\n應查最遠軸距欄位為「四點五公尺」之列，再查前單軸後單軸車輛之欄位，\n即可查得其車輛總重限制值為十八點五公噸。\n二、曳引車及半拖車總聯結重量限制\n１. 曳引車總聯結重量限制：\n14\n\n(1). 前單軸後單軸曳引車：三十五公噸。\n(2). 前單軸後雙軸曳引車：四十三公噸。\n２. 半拖車總聯結重量限制：\n軸組型態\n軸距(公尺)\n後單軸半拖車\n後雙軸半拖車\n後參軸半拖車\n二公尺\n二十五公噸\n二十五公噸\n二十五公噸\n二點五公尺\n二十六公噸\n二十六公噸\n二十六公噸\n三公尺\n二十七公噸\n二十七公噸\n二十七公噸\n三點五公尺\n二十八公噸\n二十八公噸\n二十八公噸\n四公尺\n二九點五公噸\n二十九點五公噸\n二十九點五公噸\n四點五公尺\n三十點五公噸\n三十點五公噸\n三十點五公噸\n五公尺\n三十一點五公噸\n三十一點五公噸\n三十一點五公噸\n五點五公尺\n三十二點五公噸\n三十二點五公噸\n三十二點五公噸\n六公尺\n三十二點五公噸\n三十四公噸\n三十四公噸\n六點五公尺\n三十二點五公噸\n三十五公噸\n三十五公噸\n七公尺\n三十二點五公噸\n三十六公噸\n三十六公噸\n七點五公尺\n三十二點五公噸\n三十七公噸\n三十七公噸\n八公尺\n三十二點五公噸\n三十八點五公噸\n三十八點五公噸\n八點五公尺\n三十二點五公噸\n三十九點五公噸\n三十九點五公噸\n九公尺\n三十二點五公噸\n四十公噸\n四十點五公噸\n九點五公尺\n三十二點五公噸\n四十公噸\n四十一點五公噸\n十公尺以上\n三十二點五公噸\n四十公噸\n四十三公噸\n附註：查表方式同第一項。\n三、兼供曳引之大貨車總聯結重量限制\n１.前單軸後單軸大貨車：三十四公噸。\n２.前單軸後雙軸大貨車：四十六公噸。\n３.前雙軸後單軸大貨車：四十公噸。\n４.前雙軸後雙軸大貨車：五十二公噸。\n四、拖架總重量限制\n１.單軸組拖架：十二公噸。\n２.雙軸組拖架：二十公噸。\n３.參軸組拖架：二十二公噸。\n五、專供營建工程不具載貨空間特種車之總重量限制\n軸組型態\n前單軸後單軸\n車輛\n前雙軸後單軸\n車輛\n前單軸後雙軸\n車輛\n前雙軸後雙軸\n車輛\n總重量\n二十一點五公\n噸\n二十七點五公\n噸\n二十七點五公\n噸\n三十五公噸\n15"},{"file_id":"0000412360","name":"附件十二 幼童專用車車身各部規格.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000412360&lan=C","fetched":true,"bytes":614866,"pages":2,"text":"第三十九條、第三十九條之一、第四十一條附件十\n二\n附件十二 幼童專用車車身各部規格\n項目\n檢驗標準\n實施日期\n新登檢領照檢\n驗\n定期檢驗\n１. 出入\n口\n(１)幼童專用車出入口第一階距地踏步高至\n多三十公分，其餘各階高度至多二十公\n分；階梯有效寬度至少五十公分。\n自九十年三月\n一日起\n自九十年三月\n一日起新登檢\n領照者\n(２)幼童專用車出入口第一階或於車身外附\n加之階貼深度至少二十公分，且不得突出\n車身兩側。\n自九十七年十\n月一日起\n自九十七年十\n月一日起新登\n檢領照者\n(３)幼童專用車應於出入口設置階梯及上下\n車扶手，並應能提供幼童適當使用。\n(４)大型幼童專用車之出入口規格應符合大\n客車出入口之規定；小型幼童專用車之出\n入口門框寬度至少六十公分，門框高度至\n少一百二十公分。\n自九十年三月\n一日起\n自九十一年一\n月一日起\n２. 走道\n寬與\n內高\n(１)大型幼童專用車之走道寬度與內高應符\n合大客車之車身各部規格相關規定。\n(２)小型幼童專用車之走道有效寬度至少三\n十公分，走道內高至少一百三十公分；出\n入口至走道應能允許直徑三十公分且高\n度一百公分之圓柱物體垂直順利通過。\n３. 幼童\n座椅\n配置\n與尺\n度\n(１)幼童座位空間每位寬度至少三十公分，但\n椅墊有效寬度不得少於二十五公分，椅墊\n有效深度應為二十三至二十五公分之\n間，椅墊上緣距地板高度應為二十三至二\n十五公分之間，但輪弧位置不受此限；椅\n\n\n墊面不得前傾；椅墊內緣至前座椅背後緣\n之水平距離應為四十二至四十五公分之\n間。\n(２)幼童座椅應設椅背，椅背高度應為四十至\n四十五公分之間，椅背向後傾斜角度五度\n至十度且為固定式；座椅配置除幼童管理\n人座椅之外，其餘座椅應面向前方，並不\n得設置立位與輔助座椅。\n(３)幼童座椅之椅背上緣不得設有堅硬之物\n品。\n(４)最前排幼童座椅之前方應設置表面為軟\n質材料之保護板，保護板上緣距地板高度\n至少六十公分，保護板之寬度應能涵蓋該\n幼童座椅之椅背對應寬度。\n(５)幼童座椅得於走道側設置平行於椅墊面\n之座椅扶手，座椅扶手上緣至座椅椅墊上\n緣應為十四至十五公分之間，座椅扶手內\n緣至臨走道之座位中心至少十二點五公\n分，座椅扶手寬度至少二公分。\n４. 安全\n門\n(１)除全部幼童座椅皆相鄰出入口外，應在與\n出入口不同側設置可由車內及車外開啟\n之安全門，安全門開啟後非經外力不得自\n動關閉。\n(２)幼童專用車應於安全門上標示「安全門」\n字體及其操作方法，其字體顏色應為紅色\n且「安全門」字體每字至少十公分見方。\n(３)大型幼童專用車之安全門規格應符合大\n客車安全門之規定；小型幼童專用車之安\n全門門框寬度至少五十五公分，有效高度\n至少一百二十公分，安全門下緣距地高至\n多六十二公分。\n(４)安全門出入口至走道應能允許直徑三十\n公分且高度一百二十公分之圓柱物體垂\n直順利通過，且不得於安全門出入口至走\n道之間設置活動式座椅。\n(５)安全門應設有「防止幼童誤開啟裝置」，\n啟動「防止幼童誤開啟裝置」時應有警\n音，警示駕駛及幼童管理人。\n自九十一年\n一月一日起\n自九十一年一\n月一日起新登\n檢領照者\n５.其他\n幼童專用車不得裝設行李架，出入口地板及階\n梯踏板應有防滑功能，踏板前緣應有明顯辨識\n界線，車窗玻璃不得黏貼不透明之色紙或隔熱\n紙，兩側車窗不得裝設橫桿或護網，駕駛座之\n後方應設置駕駛座欄桿。\n自九十年七月\n一日起\n自九十年七月\n一日起"},{"file_id":"0000412357","name":"附件十三 壓縮天然氣汽車燃料系統檢驗規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000412357&lan=C","fetched":true,"bytes":253914,"pages":3,"text":"第三十九條、第三十九條之一附件十三\n附件十三 壓縮天然氣汽車燃料系統檢驗規定\n壹、壓縮天然氣汽車燃料系統審驗、新領牌照檢驗及變更登記檢驗規定\n一、壓縮天然氣汽車燃料系統之容器、加氣接頭、安全閥、關閉閥及壓力調整器應符合「車\n輛零組件型式安全及品質一致性審驗作業要點」之規定。\n二、壓縮天然氣汽車燃料系統各部位之氣密試驗不得洩漏。\n(一)氣密室之氣密試驗可使用二氧化碳檢驗法或發煙劑檢驗法。\n(二)天然氣燃料系統其他部位之氣密試驗可使用檢示液、氣體測漏器或壓力計檢驗法。\n三、壓縮天然氣汽車燃料系統安裝規定：\n(一) 壓縮天然氣容器及其附件、固定裝置之安裝規定：\n１.壓縮天然氣容器應以不易消除之方法烙印或標示下列項目：\n (１)容器製造業者之名稱或其符號。\n(２)容器批號或序號。\n(３)容器首次檢驗或定期檢驗之合格日期。\n(４)壓縮天然氣或CNG。\n(５)容器之耐壓試驗壓力及最高填充壓力。\n(６)容器之內容積（單位為公升）。\n(７)容器之質量(即空重，單位為公斤)。\n(８)「汽車專用容器」之字體。\n２.應於加氣接頭附近之顯明位置處以不易消除之方法標示下列項目：\n(１)填充燃料種類(即壓縮天然氣或CNG)。\n(２)壓縮天然氣系統之工作壓力。\n(３)容器之總容積（單位為公升）。\n(４)容器之下次檢驗日期。\n３.容器及其附件、固定裝置應安裝在汽車之全長、全寬、全高範圍內，且應高於最\n低離地高度，但不得安裝於車廂內。變更使用壓縮天然氣為燃料者，其容器及\n其附件不得裝置於車頂。\n４.容器及其附件應距汽車最後端（含保險桿）三十公分以上及距車身最外側二十公\n分以上，且應距排氣管及消音器等熱源十公分以上，但有適當之隔熱措施者，則\n得距四公分以上，容器附件並應距排氣管開口部三十公分以上。\n５.容器之附件安裝在後行李箱者，應裝設氣密設施與車廂隔開，安裝處並應通風良\n好。\n６.容器之附件應距電氣端子及電氣開關二十公分以上。容器之附件安裝在密閉處\n者，應在安裝處附近設置換氣孔將洩漏之天然氣排出車外，該換氣孔並應設置在\n排出之天然氣不致影響露出的電氣端子及電氣開關處。內部的配線應予包覆，並\n\n\n應與車體固定。容器及其附件、配管、其他相關燃料系統零組件不得裝置於電瓶\n下方。\n７.容器應有覆蓋，不得直接接觸陽光。容器及其附件裝有防護蓋者，應不致產生積\n水現象。\n８.容器上應裝置壓力洩放裝置（即安全閥），以供容器在壓力或溫度異常時洩放壓\n力，洩放之天然氣應以金屬管路導引至車外遠離熱源之安全處排放。\n９.容器及其附件應固定牢固，固定處並應安裝保護裝置，以防止外來物體或車輛相\n關零組件之碰撞造成損傷。\n１０.容器上應裝置手動關閉閥。容器上或容器附近應裝置超流閥(Excess Flow\nShut-off Valve)。\n１１.容器及其附件裝設之區域應方便人員進行檢查或維修。\n(二)關閉閥、逆止閥及壓力調整器安裝規定：\n１.關閉閥、逆止閥及壓力調整器應距汽車最後端三十公分以上及距車身最外側二十\n公分以上。\n２.容器至引擎間應裝置關閉閥，引擎停止運轉、電源關閉或不使用天然氣燃料時，\n關閉閥應能自動切斷燃料供應。加氣接頭附近應裝置一操作方便之手動１\\４關\n閉閥及其操作方向之明顯標示。\n３.壓力調整器不得直接使用引擎排放廢氣加熱。\n(三)配管安裝規定：\n１.配管應安裝在汽車全長、全寬、全高之範圍內，並應高於最低離地高度。配管應\n距排氣管及消音器十公分以上，但有適當之隔熱措施者，則得距四公分以上，並\n應距排氣管開口部三十公分以上。配管應距電氣端子及電氣開關二十公分以上，。\n２.配管安裝在車廂內或後行李箱者，應設置氣密設施與車廂隔開。配管安裝在密閉\n處者，應在安裝處附近設置換氣孔，該換氣孔並應設置在排出之天然氣不致影響\n露出的電氣端子及電氣開關處。內部的配線應予包覆，並應與車體固定。\n３.配管各彎曲部之彎曲半徑應大於該管外徑兩倍。配管應以金屬材質固定式管夾固\n定，兩固定點間之距離不得超過一百公分。\n４.配管支撐器或固定式管夾之金屬部不得直接接觸配管，貫穿車體金屬部之配管並\n應予以保護，不得直接接觸金屬。\n(四)加氣接頭安裝規定：\n１.加氣接頭不得設置在排氣管的開口部方向，並應距排氣管開口部三十公分以上。\n２.加氣接頭應距電氣端子及電氣開關二十公分以上。\n３.加氣接頭不得安裝於乘客室內，且加氣接頭開口不得朝向車內。\n４.加氣接頭應裝設保護蓋或栓塞。加氣接頭之保護蓋或栓塞開啟時，汽車引擎應無\n法運轉。\n四、容器固定裝置強度：\n(一)申請者應檢附容器固定裝置之強度計算說明資料。\n(二)使用支撐框固定容器者，以支撐框危險斷面負荷之二點五倍計算，該危險斷面強度\n\n\n之安全率應大於一點六倍以上。\n(三)容器固定裝置應安裝二個以上之金屬固定帶，且得拆裝容器，但不得使用鋼索固定。\n(四)金屬固定帶及其支撐不得與容器直接接觸，固定帶與容器間並應裝置非含水性之彈\n性墊片。\n五、其他：\n(一)應於汽車適當位置裝設靜電扣環，以供汽車充填天然氣燃料時，導引汽車靜電接地。\n(二)汽車排氣管出口應安裝具有滅焰功能之裝置，以避免汽車排氣產生火花。\n(三)加氣接頭附近應裝設壓力表以顯示容器中壓縮天然氣之壓力。駕駛室儀表附近並應\n設置壓縮天然氣存量顯示之裝置，該裝置且不得造成天然氣洩漏至車廂內。\n(四)壓力調整器前端應裝設天然氣過濾器。\n貳、壓縮天然氣汽車燃料系統定期檢驗規定\n一、使用中之壓縮天然氣容器，每三年應定期檢驗一次，檢驗不合格之容器應銷毀報廢，\n不得繼續使用。使用壓縮天然氣為燃料汽車之所有人，應向交通部認可之容器定期\n檢驗機構申請辦理容器定期檢驗，並檢具容器檢驗合格報告向專業機構申請辦理壓\n縮天然氣燃料系統定期檢驗。\n二、使用中之壓縮天然氣容器定期檢驗項目及檢驗標準如下：\n(一)外觀檢查：容器外表及內部不得有腐蝕、裂痕及條痕之現象。\n(二)膨脹測定試驗：無洩漏或異常膨脹，且內容積恆久增加率，鋼製容器應小於百\n分之十，複合材質容器應小於百分之五。\n(三)質量檢查：實際量測質量應大於容器上所標示質量之百分之九十五。\n三、壓縮天然氣燃料系統各部位之氣密試驗不得洩漏。\n四、容器及加氣接頭附近之烙印或標示不得污損或去除。\n五、容器、閥件、壓力調整器、加氣接頭、配管及其固定裝置不得有損傷、腐蝕及鬆動現\n象。\n六、加氣接頭保護蓋或栓塞之功能正常。\n七、引擎停止運轉或電源關閉時，關閉閥應能自動切斷燃料供應。\n    八、車身前後汽車號牌附近顯明位置之「天然氣汽車」標示不得污損或脫落。"},{"file_id":"0000222124","name":"附件十四計程車設置車頂廣告看板架審驗作業規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000222124&lan=C","fetched":true,"bytes":323922,"pages":3,"text":"22 \n \n附件十四  計程車設置車頂廣告看板架審驗作業規定\n一、審驗項目與標準：\n項\n次\n審驗項目\n審驗標準\n一\n車頂廣告看板\n架尺度\n一、長度不得超出車頂長及影響車頂燈之設置。\n二、寬度不得超出車頂寬及影響車頂燈之設置。\n三、至少有百分之九十九以上的側面垂直投影面積，\n其總高度不得超過汽車車頂五十公分。\n四、實際架設車頂，距地總高度不得超過二百二十公\n分及車寬一點五倍。\n二\n車頂廣告看板\n架重量\n重量不得超過十五公斤。\n三\n車頂廣告看板\n架發聲及畫面\n設備\n不得裝置發聲及切換畫面設備。\n四\n燈光審驗\n一、光源為白色。\n二、光源不得閃爍。\n三、\n光源應裝設於車頂廣告看板架本體內部，不得直\n接外露。\n五\n振動試驗\n依 CNS7137(D3067) 如後表，執行試驗。\n8.3Hz 至\n100Hz\n試驗頻\n率\n試驗加\n速度\n振動方\n向\n出振點\n來出時\n間\n試驗時\n間\n無共振頻\n率\n33.3Hz 2.9G\n一、上下\n軸向\n三小時 六小時\n二、左右\n軸向\n三小時 三小時\n三、前後\n軸向\n三小時 三小時\n有共振頻\n率\n共振頻\n率\n2.9G\n一、上下\n軸向\n三小時 一點五\n小時\n二、左右\n軸向\n三小時 零點七\n五小時\n三、前後\n軸向\n三小時 零點七\n五小時\n\n\n\n33.3Hz 2.9G\n一、上下\n軸向\n三小時 四點五\n小時\n二、左右三小時 二點二\n\n23 \n \n軸向\n五小時\n三、前後\n軸向\n三小時 二點二\n五小時\n\n二、產品一致性抽測作業方式及抽測標準：\n（一）產品一致性抽測作業方式\n1.車頂廣告看板架一致性抽測由專業機構依抽測標準，以隨機方式於\n裝配地點實施抽測。\n2.同型式之車頂廣告看板架依申請標識數量，每二百個抽測一個，不\n足二百個仍抽測一個。\n3.抽測結果如有不符抽測標準，暫停核發標識，俟複測合於標準後再\n行核發，複測以二次為限。\n4.同型式之車頂廣告看板實施抽測，累計三個以上不符合抽測標準者，\n須重新實施振動試驗。\n5.同型式之車頂廣告看板架經複測二次不符合抽測標準者或振動試\n驗不合格者，取消該型式之車頂廣告看板架審驗報告及其合格標\n識。\n（二）產品一致性抽測標準：\n項目\n抽測標準\n車頂廣告看板\n架尺度\n如審驗項目與標準，其誤差範圍不得超過原合格車頂廣告\n看板架型式之±一十mm。\n車頂廣告看板\n架重量\n如審驗項目與標準，其誤差範圍不得超過原合格車頂廣告\n看板架型式之±零點一kg。\n發聲設備\n不得裝置。\n切換畫面設備 不得裝置。\n燈光審驗\n如審驗項目與標準\n\n三、計程車車頂廣告看板架之製作、安裝、拆（移）裝備由具廣告公會\n會員之廣告業者為之。\n四、計程車車頂廣告看板架經專業機構型式審驗合格者，應核發合格標\n識，黏貼於廣告看板架上。\n五、計程車設置車頂廣告看板架設置方向為平行或垂直車輛行進方向圖\n例如下：\n\n \n\n24"},{"file_id":"0000403808","name":"附件十五 汽車設備規格變更規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000403808&lan=C","fetched":true,"bytes":430300,"pages":10,"text":"第二十三條、第二十四條、第三十九條之一附件十\n五修正規定\n附件十五  汽車設備規格變更規定\n一、本點汽車設備變更項目須經交通部委託之車輛專業技術研究機構審驗合格，並繳\n驗改(加)裝設備之統一發票，經公路監理機關檢驗合格後，辦理變更登記。\n(一)本款汽車設備變更：\n設備分類\n變更項目\n變更要件或檢驗基準\n引擎\n使用液化石油\n氣為燃料者\n（含單、雙燃\n料）\n應符合「汽車變更使用液化石油氣燃料系統車型安全\n及品質一致性審驗作業要點」之規定，並繳驗下列證\n件：\n1.改裝完成檢驗合格紀錄表（格式如附件九）。\n2.公司登記證明文件影本及工廠登記或商業登記證\n明文件影本並加蓋公司章，其營業項目應列有液\n化石油氣汽車改裝。\n3.負責改裝技術人員證件影本並蓋公司章（政府機\n關舉辦之液化石油氣汽車課程講習合格證件）。\n4.車輛專業技術研究機構檢測合格證件影本並加蓋\n公司章（同改裝廠、同廠牌、同型式）。\n5.改(加)裝設備完(免)稅證件。\n使用壓縮天然\n氣為燃料者\n（含單、雙燃\n料）\n應檢附逐車經車輛專業機構依附件十三規定檢測天\n然氣燃料系統審驗合格報告及改（加）裝設備完\n（免）稅證件。\n車身\n小型汽車固定\n式置放架\n1.應符合「車輛安全檢測基準」之「小型汽車置放架之\n靜態強度」規定。\n2.應安裝牢固，不得遮蔽號牌及燈光，不得突出車\n身兩側。\n3.如裝置於後方者，長度不得超過後側車身外五十\n公分，並以其完全展開狀態丈量。\n計程車設置車\n頂廣告看板架\n應符合第二十四條之一規定。\n車身變更打造\n全高三點四公\n尺以上大客車\n三點五公尺之\n其他車輛\n應符合第三十九條第十六款、第十七款之規定。\n設置輪椅區或\n迴轉式座椅\n1.申請設置輪椅區者，或自中華民國一百零二年一\n月一日起申請變更迴轉式座椅者，應符合「汽車變\n更設置輪椅區或迴轉式座椅車型安全審驗作業要\n點」之規定，並應繳驗車輛專業技術研究機構審驗\n合格報告影本並加蓋公司章及檢驗合格紀錄表。\n2.中華民國一百零二年一月一日前已辦理變更設置\n昇降機者，應檢具已變更昇降機之行車執照，並\n於車外進出口處及車內輪椅置放區附近，依「汽車\n變更設置輪椅區或迴轉式座椅車型安全審驗作業\n\n要點」規定設有載運輪椅使用者車輛之識別標示\n後，於中華民國一百零三年一月一日前辦理變更\n登記。\n加裝聯結器\n(貨車兼供曳\n引)\n1.非經車輛型式安全審驗車輛，出廠證或海關進口\n與貨物稅完(免)稅證明書載明有總聯結重量者。\n2.經車輛型式安全審驗合格車輛，其車輛型式安全\n審驗合格證明書中有註明總聯結重量或於底盤車\n型式登錄總聯結重量者。\n3.應檢附符合「車輛安全檢測基準」之「機械式聯結裝\n置」及「機械式聯結裝置安裝規定」審查合格報告影\n本並加蓋公司章。\n底盤\n車輛後懸部分\n大樑\n應符合「車輛後懸部分大樑變更審驗作業要點」之規\n定。\n小型汽車附掛\n拖車設備\n應符合「使用中小型汽車附掛拖車變更審查及登檢作\n業規定」之規定。\n其他設備\n大客車座椅拆\n減\n大客車座椅拆減未涉及變更車體或座椅配置之情形\n者，應向公路監理機關過磅登檢，辦理座位數變更\n登記。\n大客車座椅材\n質或配置換\n裝、內裝整體\n整修換裝\n1.自中華民國九十九年一月一日起，新登檢領照之\n大客車更新換裝座椅式樣（座椅之材質、結構、規\n格），應檢具座椅強度及安全帶固定裝置審查合\n格之證明文件；全數（不含駕駛座椅及車務人員\n座椅）更新換裝座椅式樣或變更座椅配置者，由\n車輛製造廠、車體打造廠或原代理商施工；其餘非\n全數換裝且未涉變更座椅配置者，得由座椅相關\n合格廠商施工，並均應出具載明符合座椅強度、安\n全帶固定裝置審查報告與編號、裝用車輛牌照或引\n擎、車身號碼並加蓋公司章之施工證明，向公路監\n理機關過磅登檢，辦理變更登記。\n2.中華民國九十一年一月一日起應符合內裝材料難\n燃性測試之大客車，有更新換裝座椅材質、換裝座\n椅配置或內裝整體整修換裝之情形，應檢具換裝\n座椅來源證件、座椅材料審查合格之證明文件及座\n椅合格施工廠商切結書(註記裝用車輛牌照或引\n擎、車身號碼並加蓋公司章)，向公路監理機關過\n磅登檢，辦理變更登記。\n3.中華民國九十年十二月三十一日前免經符合內裝\n材料難燃性測試之大客車，變更座椅後向公路監\n理機關過磅登檢，辦理座位數變更登記。\n其他經主管機\n關核定之項目\n(二)本款拖車設備變更：\n設備分類\n變更項目\n變更要件或檢驗基準\n車身\n附加吊桿\n1.非經車輛型式安全審驗車輛或車輛型式安全審驗\n合格證明書中各車型未有註明附加者，應由原製\n造廠出具計算結構後符合安全之證明文件。\n2.經車輛型式安全審驗合格車輛，且車輛型式安全\n審驗合格證明書中各車型有註明附加者。\n底盤\n車輛後懸部分\n應符合「車輛後懸部分大樑變更審驗作業要點」之\n\n大樑\n規定。\n其他設備\n其他經主管機\n關核定之項目\n二、本點設備變更須原車輛製造廠、車輛代理商或車輛修理業出具改裝證明及改\n（加）裝設備之統一發票，並經公路監理機關檢驗合格後，辦理變更登記。\n(一)本款汽車設備變更須由原汽車（底盤）製造廠、汽車代理商或依法領有公\n司、商業或工廠登記證明文件之合法汽車車體（身）打造業或汽車修理業\n者（以下簡稱汽車車廠）出具改裝證明。\n設備分類\n變更項目\n變更要件或檢驗基準\n實施日期或\n適用日期\n車身\n車身式樣變更\n(或附加設\n備)：附加吊\n桿、傾卸式、攪\n拌式、多層式\n1.須經汽車車廠出具改裝證明文件。\n2.應與底盤大樑或是其他車體主要結\n構部分連接，並安裝牢固。\n3.不得遮蔽號牌及燈光。\n自中華民國\n九十六年一\n月一日起。\n防撞桿\n1.中華民國九十六年一月一日後申請\n變更者，須經汽車車廠出具安裝證\n明文件，經公路監理機關檢驗合\n格，辦理變更登記。\n自中華民國\n九十六年一\n月一日起。\n2.中華民國九十五年十二月三十一日\n前申請變更者，得免出具安裝證明\n及統一發票，經公路監理機關檢驗\n合格，辦理變更登記。\n自中華民國\n九十五年七\n月一日至九\n十五年十二\n月三十一\n日。\n3.本項設備檢驗基準：\n(1)應與底盤大樑或是其他車體主\n要結構部分連接，並安裝牢固。\n(2)不得遮蔽號牌及燈光。\n(3)不得有銳利角及邊緣。\n(4)不得突出車身兩側，致影響行\n車安全。\n(5)前方延伸長度應在三十公分以\n內，後方延伸長度應在二十五\n公分以內，且後懸部分應符合\n第三十八條規定。\n廂式平頭小貨\n車（含小客貨\n兩用車）車頭\n附加飾板\n1.車頭原鈑金（蒙皮部分）不得切\n除，並應出示改裝固定方式圖示及\n比照計程車車頂安裝廣告看板架應\n逐車投保有效期限內之責任保險。\n2.變更頭燈，應出示經車輛專業機構\n審查合格報告，並應通過光型檢驗\n（含每次定期檢驗）。\n3.車頭附加飾板之標幟不得與原廠牌\n型式標幟有不同。\n4.不得突出車身兩側；車長於不超出\n百分之二公差範圍內，得不辦理變\n更登記；前方延伸最多應在車長百\n\n分之二正負五公分以內（超過五公\n分以內部分應辦理車長變更登\n記）。\n廂式平頭小貨\n車車側或車頂\n鈑金件變更\n1.底盤、駕駛室空間樑柱結構部分不\n得變更。\n2.載貨空間切除樑柱結構，應由從事\n改裝之汽車車廠，向交通部認可之\n檢測機構提出車身結構強度檢測申\n請。申請變更登記者，應檢附前述\n檢測機構出具之未侵入測試車輛駕\n駛室人員生存空間之結構強度證明\n文件，及該檢測機構至從事改裝之\n汽車車廠實地查核證明文件。\n3.不得突出車身兩側。\n4.車重以空車過磅按實際重量登記，\n依核定總重量減去空車重量後核定\n載重量。\n5.鈑金件變更應使用原材質。\n車身附加混凝\n土輸送設備\n1.申請變更者，須經汽車車廠出具安\n裝證明文件，經公路監理機關檢驗\n合格，辦理變更登記。\n2.中華民國一百零八年十二月三十一\n日前經專案列管之車輛申請變更\n者，得免出具安裝證明及統一發\n票，經公路監理機關檢驗合格，辦\n理變更登記。\n自中華民國\n一百零七年\n十月一日至\n一百零八年\n十二月三十\n一日。\n3.本項設備檢驗標準：\n(1)應與底盤大樑或是其他車體主\n要結構部分連接，並安裝牢固。\n(2)不得遮蔽號牌及燈光。\n電系\n頭燈\n1.中華民國九十七年七月一日後申請\n變更氣體放電式頭燈、一百零八年\n七月一日後申請變更氣體放電式以\n外之頭燈(不含鹵素頭燈)者，須汽\n車車廠出具改裝證明文件，其頭燈\n應使用經車輛型式安全審驗合格之\n燈具（泡），為近光頭燈者另應裝\n設具自動調整垂直傾角之裝置(總\n目標發光量低於二千流明除外)，\n經公路監理機關依第三目頭燈檢驗\n基準檢驗合格，辦理變更登記。\n氣體放電式\n頭燈自中華\n民國九十七\n年七月一日\n起；氣體放\n電式以外之\n頭燈自一百\n零八年七月\n一日起。\n2.中華民國一百零八年七月一日前申\n請變更發光二極體頭燈者，得免出\n具安裝證明及統一發票，其頭燈得\n免使用經車輛型式安全審驗合格之\n燈泡，經公路監理機關依第三目頭\n燈檢驗基準檢驗合格，辦理變更登\n記。\n\n3.頭燈檢驗基準：\n(1)由燈前一公尺處之頭燈試驗器\n進行量測，如圖一、圖二所示\n(單位為公分)。HH線及VV線為穿\n過近光參考軸之水平面與垂直\n面和此螢幕的交叉點。角度\nHVH2-HH為十五度。\n(2)近光燈需提供足夠清楚的明暗\n截止線(cut-off)以作為調整之\n用，在配光螢幕VV線左側為水\n平直線，而另一邊則不應超越\nHV/H2線(圖一)或HV/H3/H4線\n(圖二)上方。\n(3)應校準近光光束使明暗截止線\n水平部分位於HH線下方十公分\n處，其轉折處應位於VV線上。若\n校準後無法符合近光燈之配光\n要求，允許在水平方向左右各\n零點五度(八點七五公分)範圍\n及垂直方向上下各零點二度(三\n點五公分)範圍內。\n其他設備\n其他經主管機\n關核定之項目\n(二)本款機車設備之變更須經原機車製造廠、機車代理商或領有公司、商業或工\n廠登記證明文件之合法機車修理業（以下簡稱機車車廠）出具改裝證明。\n設備分類\n變更項目\n變更要件或檢驗基準\n實施日期或\n適用日期\n電系\n頭燈\n1.中華民國九十七年七月一日後申請\n變更氣體放電式頭燈、一百零八年七\n月一日後申請變更氣體放電式以外\n之頭燈(不含鹵素頭燈)者，須經機\n車車廠出具改裝證明文件，其頭燈\n應使用經車輛型式安全審驗合格之\n燈具（泡），經公路監理機關依第\n三目頭燈檢驗基準檢驗合格，辦理\n變更登記。\n氣體放電式\n頭燈自中華\n民國九十七\n年七月一日\n起；氣體放\n電式以外之\n頭燈自一百\n零八年七月\n一日起。\n\n2.中華民國一百零八年七月一日前申\n請變更發光二極體頭燈者，得免出\n具安裝證明及統一發票，其頭燈得\n免使用經車輛型式安全審驗合格之\n燈泡，經公路監理機關依第三目頭\n燈檢驗基準檢驗合格，辦理變更登\n記。\n3.頭燈檢驗基準：\n(1)由燈前一公尺處之頭燈試驗器進\n行量測，如圖一、圖二及圖三所示\n(單位為公分)。HH線及VV線為穿過\n近光參考軸之水平面與垂直面和\n此螢幕的交叉點。角度HVH2-HH為\n十五度。\n(2)近光燈需提供足夠清楚的明暗截\n止線(cut-off)以作為調整之用，\n非對稱光型在配光螢幕VV線左側\n為水平直線，而另一邊則不應超\n越HV/H2線(圖一)、HV/H3/H4線(圖\n二)上方，對稱光型為水平直線，\n不應超越H1H1線(圖三)。\n(3)應校準近光光束使明暗截止線水\n平部分位於HH線下方十公分處，\n非對稱光型其轉折處應位於VV線\n上。若校準後無法符合近光燈之配\n光要求，允許在水平方向左右各\n零點五度(八點七五公分)範圍及\n垂直方向上下各零點二度(三點五\n公分)範圍內。\n\n其他設備\n其他經主管機\n關核定之項目\n(三)本款拖車設備變更須由原汽車（底盤）製造廠、汽車代理商或依法領有公\n司、商業或工廠登記證明文件之合法汽車車體（身）打造業或汽車修理業\n者（以下簡稱汽車車廠）出具改裝證明。\n設備分類\n變更項目\n變更要件或檢驗基準\n車身\n車身式樣變更(或\n附加設備)：昇降\n機平板式、框式、\n廂式、多層式\n1.須經汽車車廠出具改裝證明文件。\n2.應與底盤大樑或是其他車體主要結構部\n分連接，並安裝牢固。\n3.裝置於車身後方時不得突出車身兩側；\n裝置於車身兩側時不得突出車身後方，\n致影響行車安全。\n4.不得遮蔽號牌及燈光。\n輔助階(樓)梯\n1.應與底盤大樑或是其他車體主要結構部\n分連接，並安裝牢固。\n2.不得有銳利邊角。\n3.不得突出車身兩側，致影響行車安全。\n其他設備\n其他經主管機關\n核定之項目\n三、本點設備變更須經合法業者辦理，並繳驗改(加)裝設備之統一發票，並經公路監\n理機關檢驗合格，辦理變更登記。\n(一)本款汽車設備變更須經原汽車（底盤）製造廠、汽車代理商或依法領有公\n司、商業或工廠登記證明文件之汽車車體(身)打造業或汽車修理業或與變\n更項目有關之合法業者辦理改(加)裝。\n\n設備分類\n變更項目\n變更要件或檢驗基準\n車身\n絞盤\n應與底盤大樑或是其他車體主要結構部分\n連接，並安裝牢固。\n車身式樣變更(或\n附加設備)：罐\n體、槽體\n應符合第三十九條第二十五款之規定。\n車身式樣變更(或\n附加設備)：蓬\n式、柵式、補胎機\n具、附水槽、昇降\n機(設有輪椅升降\n台之設置輪椅區\n車型除外)、廂式、\n框式、平板式、冷\n藏、冷凍、保溫\n1.應與底盤大樑或是其他車體主要結構部\n分連接，並安裝牢固。\n2.裝置於車身後方時不得突出車身兩側；\n裝置於車身兩側時不得突出車身後方，\n致影響行車安全。\n底盤\n懸吊系統之避震\n器\n變更後不得超過原核定車身高度。\n其他設備\n其他經主管機關\n核定之項目\n(二)本款機車設備變更須經原機車製造廠、機車代理商或依法領有公司、商業或\n工廠登記證明文件之機車修理業或與變更項目有關之合法業者辦理改(加)\n裝。\n設備分類\n變更項目\n變更要件或檢驗基準\n實施日期或\n適用日期\n車身\n身心障礙特\n製機車\n汽車所有人應檢具汽車變更登記書、新領\n牌照登記書車主聯、行車執照、車輛改裝\n之合法業者公司、商業或工廠登記證明文\n件影本，向當地公路監理機關辦理檢驗\n變更登記。\n其他設備\n排氣管(非\n原型式)\n1.更換非原型式排氣管，應使用經環境\n部噪音管制認證，且能對應該機車型\n式之排氣管。\n自中華民國\n一百十四年\n一月一日\n起，列為檢\n驗項目。\n2.中華民國一百十三年十二月三十一日\n前申請更換非原型式排氣管者，得免\n出具統一發票，經公路監理機關檢驗\n合格，辦理變更登記。\n自中華民國\n一百十三年\n一月十八日\n至一百十三\n年十二月三\n十一日。\n3.本項設備檢驗基準：\n(1)應有排氣系統隔熱防護裝置。\n(2)排氣管尾端出口應位於車輛後方。\n(3)在平坦地面上兩輪著地時，排氣管\n尾管出口角度不得傾斜高於水平\n線；排氣管尾管離地高度逾一公尺\n者，其尾管出口角度應低於水平\n線。\n\n其他經主管\n機關核定之\n項目\n四、本點設備變更得不經公路監理機關辦理變更登記。但變更(或改裝、加裝)後應符\n合下列規定，並列為檢驗項目。\n(一)汽車設備變更：\n設備分類\n變更項目\n變更要件或檢驗基準\n實施日期或\n適用日期\n車身\n空力套件（含\n汽車裙部、擾流\n板、尾翼）\n1.不得突出車身兩側及前、後方，致\n影響行車安全。\n2.不得有銳利邊角。\n3.不得阻礙駕駛人的視線。\n自中華民國\n九十六年一\n月一日起，\n列為檢驗項\n目。\n輔助階梯\n1.應與底盤大樑或是其他車體主要\n結構部分連接，並安裝牢固。\n2.不得有銳利邊角。\n3.不得突出車身兩側，致影響行車\n安全。\n自中華民國\n九十六年一\n月一日起，\n列為檢驗項\n目。\n其他設備\n排氣管\n1.排氣管尾端出口應位於車輛後方。\n2.排氣管不得突出車身兩側，其最\n低點與地面距離不得少於十公分。\n自中華民國\n九十六年一\n月一日起，\n列為檢驗項\n目。\n含視野輔助燈\n之照後鏡\n1.應符合「車輛安全檢測基準」之「含\n視野輔助燈之照後鏡」規定。\n2.應於原照後鏡安裝處安裝牢固，\n不得影響駕駛人視線。\n3.後方視野輔助燈應與頭燈及倒車\n燈連動。\n4.後方視野輔助燈作動時應不影響\n後方駕駛人的視線。\n自中華民國\n九十九年一\n月一日起，\n列為檢驗項\n目。\n娛樂性顯示設\n備\n駕駛人所裝設使用之娛樂性顯示設\n備，應與駐煞車或變速箱檔位連\n動，駐煞車未使用或變速箱檔位處\n於前進或後退檔位時，不得顯示。\n自中華民國\n一百零三年\n七月一日\n起，列為檢\n驗項目。\n其他經主管機\n關核定之項目\n(二)機車設備變更：\n設備分類\n變更項目\n變更要件或檢驗基準\n實施日期或\n適用日期\n車身\n車身外殼\n原機車製造廠或機車代理商宣告該\n車型外殼已停產者，可更換同廠牌\n同型式系列外殼。\n自中華民國\n九十六年一\n月一日起列\n為臨時檢驗\n項目。\n其他設備\n照後鏡\n1.應與車身主要結構部分連接，並\n自中華民國\n\n安裝牢固。\n2.不得影響駕駛人視角。\n九十六年一\n月一日起列\n為臨時檢驗\n項目。\n排氣管(原型\n式)\n1.應有排氣系統隔熱防護裝置。\n2.排氣管尾端出口應位於車輛後方。\n自中華民國\n九十六年一\n月一日起列\n為臨時檢驗\n項目。\n3.在平坦地面上兩輪著地時，排氣\n管尾管出口角度不得傾斜高於水\n平線；排氣管尾管離地高度逾一\n公尺者，其尾管出口角度應低於\n水平線。\n自中華民國\n九十九年三\n月一日起列\n為臨時檢驗\n項目。\n其他經主管機\n關核定之項目"},{"file_id":"0000412354","name":"附件十六 營業大客車保養紀錄表.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000412354&lan=C","fetched":true,"bytes":250851,"pages":2,"text":"第三十九條之一附件十六\n附件十六 營業大客車保養紀錄表\n車號：        保養時里程：         客運公司名稱：                 保養日期： 年\n月 日\n保養系類\n保養項目\n已完成保\n養\n未達保養週\n期\n附註\n引擎、冷卻\n及潤滑系\n機油、機油濾芯、冷卻系\n統、冷卻水、皮帶及軸承、\n其他原廠規定項目\n\n\n\n進排氣及\n燃油系\n空氣濾芯、進氣歧管、排\n氣歧管及消音器、渦輪增\n壓器、廢氣控制及後處理\n系統、燃油管路及柴油濾\n芯、其他原廠規定項目\n\n\n\n轉向及傳\n動系\n動力轉向系統、轉向節及\n轉向臂、直(橫)拉桿及球\n頭、傳動軸、離合器、差\n速器、變速箱、其他原廠\n規定項目\n\n\n\n煞車系\n煞車管路、煞車鼓(碟)及\n來令片、手(駐車)煞車、\n煞車總缸及分缸、儲氣筒\n及氣壓表、輔助煞車系\n統、其他原廠規定項目\n\n\n\n電系\n電瓶、啟動馬達、發電機、\n全車燈光、雨刷、喇叭、\n儀表及警示燈(器)、保險\n絲(斷路器) 、其他原廠規\n定項目\n\n\n\n懸吊系\n葉片彈簧組、避震器、空\n氣懸吊裝置、扭力桿、其\n他原廠規定項目\n\n\n\n輪軸系\n前軸及軸承、後軸及軸\n承、後軸殼及螺帽、車輪\n外觀、胎紋(深度)及使用\n年限、車輪輪圈及螺栓、\n螺帽、胎壓、其他原廠規\n定項目\n\n\n\n空調系\n冷凝器、鼓風機、高低壓\n開關、溫度開關、壓縮機、\n冷媒、皮帶、其他原廠規\n定項目\n\n\n\n電能驅動\n系\n高壓電池、馬達、電力轉\n換器、高壓電線路、其他\n原廠規定項目\n\n\n\n\n\n已依原廠\n保養項目\n及週期規\n範完成保\n養\n主管簽章\n公司核章\n\n\n備註：\n1、 本表應由汽車修理業者，依原廠保養檢查項目及週期規範保養(含檢查)，在「已完\n成保養」或「未達保養週期」欄位以「V」註記，並由汽車修理業者及業務主管簽證，\n且相關定期保養檢查及維修紀錄應保存三年備查。\n2、 離島地區得以領有汽車修護技工執照或乙級汽車修護技術士證之現場技術人員，於\n公司核章欄位簽證。\n3、 本表之保養項目，如由二以上廠商協力保養者，應分別製作，空調系部分得委由相\n關合法業者辦理並單獨製作。\n4、 保養系類勾選未達保養週期者，應於附註欄位註記原廠規定應實施保養之週期，俾\n供檢驗單位查核。\n5、 定期檢驗檢附四個月內之本表、維修清(工)單及汽車修理業相關登記證明文件影\n本，其中本表及維修清(工)單應交由檢驗單位留存三年備查。"},{"file_id":"0000412358","name":"附件十七 拖車標識牌及車身（架）號碼打刻規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000412358&lan=C","fetched":true,"bytes":291749,"pages":2,"text":"第三十九條、第三十九條之一附件十七\n附件十七 拖車標識牌及車身（架）號碼打刻規定\n一、拖車標識牌應以銅合金或不鏽鋼板製作，規格及內容如圖一，字體應端正、清晰、\n明確，採用銲接或鉚接方式固定於車架上，其銲接之位置如圖二至圖四。\n二、拖車應於標識牌下方之車身（架）上打刻車身（架）號碼，其車身（架）號碼內容\n應包含型式代號及流水號碼。\n三、車身（架）號碼打刻之字體限長零點九公分、寬零點六公分以上，字體應端正、清\n晰、明確。\n四、自中華民國八十八年九月一日起，國內產製者以出廠日為準，進口者以裝船日為準，\n拖車應依本規定打刻車身（架）號碼及銲接或鉚接標識牌。\n五、使用中拖車之車身（架）號碼打刻位置不符合本規定者，應於八十九年一月一日前，\n委請汽車修理廠或拖車製造廠，依本規定之打刻位置及字體打刻「拖車使用證」上\n所登載之車身（架）號碼。\n\n圖一 拖車標識牌之規格及內容\n\n\n圖二 半拖車標識牌銲接及車身（架）號碼打刻位置\n\n\n\n\n圖三 全拖車標識牌銲接及車身（架）號碼打刻位置\n\n\n圖四 無大樑罐槽體式拖車標識牌銲接及車身（架）號碼打刻位置"},{"file_id":"0000403809","name":"附件十八 專供營建工程不具載貨空間特種車及動力機械保養紀錄表.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000403809&lan=C","fetched":true,"bytes":405209,"pages":2,"text":"第八十條之二、第八十三條之一附件十八修正規定\n附件十八  專供營建工程不具載貨空間特種車及動力機械\n保養紀錄表"},{"file_id":"0000403810","name":"附件十八之一 專供配衡型堆高機保養紀錄表.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000403810&lan=C","fetched":true,"bytes":410491,"pages":2,"text":"第八十三條之一附件十八之一修正規定\n附件十八之一　專供配衡型堆高機保養紀錄表\n使用檢查合格打印號碼：\n引擎(車身)號碼或動力機械編號：\n所有人名稱：\n保養日期：\n年\n月\n日\n引擎系統\n底盤系統\n工作項目\n檢查\n結果\n工作\n紀錄\n工作項目\n檢查\n結果\n工作\n紀錄\n引擎本體及潤滑\n檢查機油壓力\n轉向系\n及傳動\n系\n檢查轉向機\n檢查引擎漏油漏氣\n轉向機油檢查或更換\n更換機油濾清芯子\n拆洗檢查前輪軸承\n更換機油\n檢查大王銷及銅套\n校準汽門腳間隙\n檢查羊角及轉向臂\n清洗冷卻系統及換冷\n卻水\n檢查前軸\n皮帶檢查或調整\n檢查直拉桿及球頭\n噴油正時及燃油\n清潔空氣濾清器芯子\n檢查橫拉桿及球頭\n檢查進氣歧管及空氣\n軟管\n拆洗檢查後輪軸承\n檢查排氣歧管及消音\n器\n檢查後軸後軸殼及螺\n帽\n更換柴油濾清器芯子\n檢查差速器油量或換\n油\n校正噴射幫浦正時\n檢查各部萬向接頭\n清洗噴油嘴及校正\n檢查推進軸\n檢查離合器\n電系\n清潔電瓶椿頭\n檢查變速箱油量或換\n油\n檢查啟動馬達\n煞車系\n檢查煞車系及各件裝\n置\n檢查發電機\n檢查各輪煞車配件\n換來令\n\n輪胎及注黃油\n檢查輪胎情形或換位\n檢查煞車鼓\n檢查輪胎鋼圈及螺絲\n校準手煞車\n換輪胎\n校準腳煞車\n底盤各部加註黃油\n檢查煞車總缸\n安全設備及燈\n光、反光標誌\n照後鏡及照地鏡\n車架鋼\n板系\n潤滑前後鋼板銷\n四路行車紀錄器（配\n有紅外線超廣角夜視\n鏡頭，具防震、防塵\n功能且其解析度達HD\n以上畫質）\n檢查鋼板吊架及吊\n鉤\n三邊盲區偵測雷達且\n感應距離五公尺\n檢查U型(騎馬)螺絲\n貨叉可收折裝置\n檢查避震器\n方向與倒車語音警示\n器\n三邊紅光線條警示燈\n頭燈、行駛警示燈\n箭頭紅光指示燈\n反光貼紙\n技工簽章及證號\n主管簽章\n公司簽章\n保養結果：\n完成□\n未完成□\n備註：\n1、工作前必須事先檢查，正常註記「V」，應修「X」。\n2、工作完成後按照下列註記(或以中文註記)： 正\n常：N\n分解檢修：W 零件換新：R\n修理：S\n調整：A\n 校正：C\n    鎔接：D 鎖緊：T\n補充：H\n無此設備：NE\n保養週期(時間及里程)未到：BID。\n注意事項：\n1、申請時檢附本保養紀錄表影本及公司、商業或工廠登記證明文件影本。\n2、無汽車修理業之離島地區，得以乙級汽車修護技術士或汽車修護技工簽證。\n3、本紀錄表依配衡型堆高機實際保養狀況填註。\n4、本表引擎本體及底盤系統以外項目，如由其他廠商協力保養者，得以同表作附件並由相關\n職類技術士或汽車修護技工簽章。\n5、以上各證件由公路監理機關影存乙份備查。"},{"file_id":"0000194584","name":"附件十九汽車駕駛人認知功能測驗規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000194584&lan=C","fetched":true,"bytes":201077,"pages":1,"text":"26 \n附件十九  汽車駕駛人認知功能測驗規定\n\n汽車駕駛人認知功能測驗程序及通過標準規定如下：\n   項目\n程序\n內    容\n測 驗 方 式\n通 過 標 準\n一\n對時間及空間之\n正確認知能力\n由受測者回答當日的年、月、\n日、星期與當時所在地。\n計測驗五題，答\n對四題以上為\n通過。\n二\n近程記憶思考之\n能力\n讓受測者看十種日常生活與交\n通環境相關圖案，收起圖案兩分\n鐘後，由受測者回答剛剛看到的\n圖案。\n記憶十種圖\n案，答對三種以\n上為通過\n三\n判斷力及手腦並\n用能力(畫出指\n定時刻時鐘)\n於測驗紙內畫出一個足夠大的\n圓形時鐘，將應該在時鐘內出現\n的數字及位置繪製完成，並於正\n確位置繪出指定時間之時針及\n分針。\n計有七項評\n分，得分四分以\n上為通過。\n說明：\n一、 以上三個程序須於測驗當日完成並通過。\n二、 程序三之計分方式如下：\n計    分    方    式 \n得  分 \n時間 \n分針指向正確位置 \n□0  □1 \n分針和時針都指向正確位置 \n□0  □1 \n沒有不屬於時鐘的添加物。例如：用文字寫下\n時間等。 \n□0  □1 \n數字 \n數字都在時鐘內 \n□0  □1 \n數字包含1 到12，沒有漏寫或重複 \n□0  □1 \n數字位\n置 \n每個數字的距離近乎相等 \n□0  □1 \n每個數字與圓圈邊界的距離近乎相等 \n□0  □1 \n總  分"},{"file_id":"0000338937","name":"附件二十考驗規定、道路駕駛考驗用車保險保額及標識牌.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000338937&lan=C","fetched":true,"bytes":139506,"pages":3,"text":"附件二十 考驗規定、道路駕駛考驗用車保險保額及標識牌\n\n一、汽機車駕駛執照考驗筆試、路考之考驗規定：\n（一）應考人參加汽機車駕駛執照考驗之筆試或路考，應遵守本條各項規定，如\n有違反，主考或監考人員得禁止應考人參與考驗。\n（二）必須隨身攜帶駕駛執照登記書、學習經歷證明、身分證或其他有關證明(含\n照片)證件以備查驗，並於指定時間內到場應考。\n（三）不得穿著如赤足、赤膊、穿木屐。\n（四）禁止抽菸、嚼檳榔或飲酒，使用毒品、麻醉劑或興奮劑。\n（五）報名申請駕駛執照考驗時，如對考驗時段無異議，缺考不得申請退費。\n（六）清楚路考考驗項目之扣分標準、考驗動線。\n（七）為考驗爭議及事故蒐證所須，得為考驗過程錄音錄影。\n（八）於路考之評分標準表上簽名後，始得考驗。\n（九）場考或道路駕駛考驗扣分累計超過三十分，經主考人員通知不及格終止考\n驗時，應考人應將車輛停至安全處或道路旁安全處，下車坐於後座。\n（十）不得舞弊，對主監考人員或考驗單位有侮辱或行賄等不法情事。\n（十一）參加道路駕駛考驗之應考人依法於道路上駕駛汽車完成考驗項目，並應\n為其駕駛行為負責，考驗員在旁僅負責考核評分，對考生之駕駛行為\n不負指揮監護義務。\n二、道路駕駛考驗用車投保之保險及保額規定如下：\n（一）強制汽車責任保險。\n（二）考驗用車所需之附加條款。\n（三）第三方保障：如第三人責任保險，不含強制汽車責任保險理賠，每人傷害\n理賠最高新臺幣三百五十萬元以上，財損部分新臺幣五十萬元以上。\n\n（四）應考人保障：第三人責任保險附加駕駛人傷害保險，每人理賠至少新臺幣\n五百萬元以上。\n（五）主監考及待考人員保障：第三人責任保險乘客體傷責任附加條款，每人理\n賠至少新臺幣五百萬元以上。\n(六) 道路駕駛考驗之車輛，駕訓班應依規定投保，發生事故時依保險契約條款\n理賠，如事故之賠償責任應歸責應考人時，對於理賠不足額部分由應考人\n負擔。\n三、道路駕駛考驗用車之標識牌規定如下：\n項目\n規定\n標識牌形狀\n三角形立牌\n標識牌顏色\n白底紅字\n標識牌文字\n道路駕駛考驗（前後兩面標示文字，面\n向車前方及車後方）\n文字尺寸\n長寬各8 公分以上\n標識牌長\n55 公分至70 公分\n標識牌寬\n10 公分至30 公分\n標識牌高\n15 公分至30 公分\n固定位置\n車頂（應穩固標識牌，避免掉落）\n\n\n四、道路駕駛考驗用車之標識牌參考圖例如下：\n\n\n\n\n\n\n\n\n\n\n\n \n寬\n長\n高\n標識文字\n標識文字\n標識牌\n標識牌"},{"file_id":"0000196585","name":"附件二十考驗規定、道路駕駛考驗用車保險保額及標識牌.ODT","format":"ODT","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000196585&lan=C","fetched":true,"bytes":91512},{"file_id":"0000338939","name":"附件二十一自動駕駛車輛申請道路測試作業規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000338939&lan=C","fetched":true,"bytes":167635,"pages":7,"text":"附件二十一 自動駕駛車輛申請道路測試作業規定\n一、適用範圍應依下列規定：\n具備有條件自動化、高度自動化及完全自動化自動駕駛功\n能之測試車輛(以下簡稱「測試車輛」)申請道路測試，應依本\n規定辦理。本規定適用於特定時間及條件下，開啟自動駕駛系\n統功能取代人為操控之測試車輛。\n二、測試申請及審查應依下列規定：\n(一)申請者應檢附「自動駕駛車輛道路測試申請書」(以下\n簡稱「申請書」) (格式如附表一)及下列相關申請文\n件，向測試區域所在地之公路主管機關(以下簡稱「受\n理機關」)提出測試申請。\n1.申請者承諾書(應包含第五點規定各事項之聲明與簽\n署)。\n2.自動駕駛車輛道路測試計畫書(以下簡稱「測試計畫\n書」，其應至少包含附表三所載明之文件)。\n3.公司(商業)登記立案證明文件，如為財團(社團)法\n人、大專院校、學術研究機構或團體者，應附登記\n證書。\n4.保險證明文件；每一核准進行測試之測試車輛應於\n測試期間應投保責任保險。\n5.測試車輛所有權或使用權證明文件。\n6.第九點第二款所規定之駕駛操控人員證明文件。\n(二)受理機關應就各項申請文件進行初步審查，審查內容\n應涵蓋下列要項：\n1.確認申請者所提出之文件及其簽署內容是否完整。\n2.評估測試車輛之數量、種類及其測試方法是否適合\n該測試範圍內之路線與環境。\n3.確認申請者所提出之國內外測試報告，其測試路線\n與環境、車輛條件以及行駛狀況與國內申請測試之\n內容具有相當程度之一致性與關聯性。\n\n4.評估申請者所提出之道路交通環境衝擊分析，並檢\n視申請者對其所提出之衝擊部分，是否已採取足夠\n之風險控管措施。\n5.檢視申請者所提出之保險規劃，並評估其保險種類\n(應至少含公共意外責任保險、強制汽車責任保險、\n乘客體傷責任保險、駕駛人傷害保險及第三人責任\n保險(含財損及傷害責任))及額度是否能補足風險缺\n口。\n(三)受理機關應於申請案經初步審查核可後，即將申請文\n件及審查報告函送交通部進行審查；初步審查結果若\n未通過，受理機關應通知申請者。\n(四)交通部於接獲受理機關所提文件後，若因審查作業需\n求，得以書面要求受理機關或申請者於指定日期內補\n正資料。審查內容應涵蓋下列要項：\n1.評估測試車輛之技術能力及其測試方法是否適合該\n測試範圍內之路線與環境。\n2.評估測試車輛之各項功能與設備(含駕駛模式切換及\n相關警示訊號、資訊紀錄器內容及車輛外觀標示等)。\n3.確認駕駛操控人員條件是否符合規定。\n4.評估申請者所提出之相關緊急應變措施是否完善。\n5.針對測試車輛及其測試環境，得要求申請者進行實\n地會勘與評估。\n(五)審查單位應於收到申請者或受理機關提報案件後六十\n日內作成決議。\n(六)審查結果，交通部應以書面通知受理機關及申請者核\n准或駁回測試之申請。審查通過後，應核發測試許可\n並轉請公路監理機關逐車核發試車牌照。\n三、核准期限應依下列規定：\n測試車輛申請道路測試，自核准之日起有效期限最長一年。\n四、申請費用應依下列規定：\n\n(一)審查費用：申請者應向受理機關繳交審查費用，每案\n新臺幣五萬元。\n(二)試車牌照規費：申請者請領試車牌照時應向公路監理\n機關繳交試車牌照相關規費。\n五、申請者應於申請測試時，向受理機關提出申請者承諾書\n(格式如附表二)並承諾遵守以下事項：\n(一)申請者應承諾為其所申請之道路測試的全權負責單位。\n(二)申請者應承諾投入測試之測試車輛已完成國內外封閉\n場域或國外一般道路測試。\n(三)申請者應承諾遵守受理機關及交通部後續增加及改變\n之所有規定，包括因規定改變或增補而隨時通知補正\n之文件或資料。\n(四)測試申請經核准後，任何因與所申請測試相關事項所\n導致之責任與損失，申請者應承諾自行負擔行政、民\n事及刑事所有責任，且不會要求受理機關及交通部負\n責。\n(五)申請者應承諾當有任何影響原申請測試時所提供資訊\n正確性之情況改變或新的發展時，將立即向受理機關\n及交通部提出補正說明文件。\n六、展延申請應依下列規定：\n(一)核准測試期限屆滿前，申請者如有繼續測試之需要，\n應於一個月前以書面檢具理由及自動駕駛道路測試申\n請書(格式如附表二)，向原受理機關申請展延，展延\n以一次為限，最長不得逾一年。\n(二)若測試目的、測試內容、測試範圍或測試車輛變更，\n應重新申請，不得辦理展延申請。\n(三)申請展延之測試車輛應遵守所有新增或改變之規定。\n(四)受理機關核准申請者之展延申請後，應通知核發試車\n牌之公路監理機關及交通部。\n七、測試暫停與終止應依下列規定：\n\n(一)若測試車輛發生事故，申請者應立即暫停測試進行調\n查，並立即通知受理機關；事故發生後十日內應提出\n書面事故報告以及避免再發生之改善措施，經受理機\n關確認後方可恢復測試；若申請者未於期限內提出，\n受理機關得立即終止已核准之測試並副知相關主管機\n關。\n(二)公路監理機關、公路主管機關或警察機關基於管理或\n安全考量，得以書面或其他方式通知申請者暫停或終\n止測試並副知相關主管機關，並立即生效。\n(三)申請者應於測試期限屆滿之日起三日內將試車牌照繳\n還至原發照機關，三十日內提供測試報告予受理機關。\n測試報告至少應包含測試歷程與結果、所蒐集及分析\n之資料、風險發生及事故通報紀錄、人為介入測試車\n輛控制權次數及原因紀錄、所發生之技術問題等。\n八、測試車輛應依下列規定：\n(一)測試車輛操作模式\n1.測試車輛應具備人工操作模式與自動駕駛模式切換\n功能，並可讓駕駛操控人員於測試車輛上的監控位\n置即可容易的進行模式切換。\n2.測試車輛應容許駕駛操控人員在緊急狀況下立即接\n管並進行必要之操作。\n3.測試車輛應於自動駕駛系統失效時，提供明確警示\n訊號予駕駛操控人員。\n4.自動駕駛模式開啟與結束時，應提醒駕駛操控人員；\n而駕駛操控人員接管操作時，其自動駕駛系統亦應\n明確告知駕駛操控人員車輛控制權限是否已完成移\n轉。\n(二)資料紀錄器及資料提供\n1.測試車輛應裝設資料紀錄器，並持續記錄及儲存以\n下測試資訊：日期、時間、經緯度座標、車速、自\n\n動駕駛狀態(開啟或關閉)、轉向控制、煞車、加速\n度、自動駕駛期間駕駛操控人員介入之資訊以及測\n試車輛行進間內部(含駕駛操控人員及駕駛操作介面\n狀態)與外部之影像；若測試車輛具備與路側設施或\n車輛聯網設備溝通之功能，其所接收之相關資訊亦\n應予記錄及儲存。\n2.事故及故障(以下簡稱事件)發生時，應保留事件發\n生前六分鐘之行車影像以及前三十秒、後十秒之其\n他資訊，相關紀錄資訊應自事件發生日起保留三年。\n3.資料紀錄器應以唯讀格式擷取及儲存資料，並具備\n防止擅改之設計。\n4.相關主管機關得索取資料紀錄器之資料及其讀取程\n式，申請者應主動無償提供。\n(三)試車牌照及車身標示\n1.經核准測試之測試車輛，申請者應依規定將試車牌\n照懸掛於測試車輛上。試車牌照之使用事宜應依相\n關規定辦理。\n2.測試車輛除懸掛試車牌照外，應於車身明顯處有自\n動駕駛測試車之標示，其車身標示資訊應符合下列\n需求：\n(1)標示內容：應明確具備「自動駕駛測試車」等文\n字內容，每個字體至少十六公分見方\n且應以正楷字體標明。車身側應標示\n測試申請者之緊急聯絡電話。\n(2)標示位置：車身四周；必要時得另於車頂裝設相\n關標示。\n(3)標示方式：標示內容得以平面漆繪或穩固黏貼方\n式張貼，並採用與車身顏色明顯對\n比且合乎規定之反光識別材料。\n(四)測試車輛安全維護\n\n申請者應在基於安全測試之原則下，於每日測試前對\n測試車輛及其自動駕駛系統進行檢查，確認各系統功能正\n常，檢查紀錄應留存備查。\n九、駕駛操控人員應依下列規定：\n(一)測試車輛於道路上測試時，每輛車內應至少配置一名\n駕駛操控人員，該名人員應於駕駛座上或可直接操作\n測試車輛之位置，以進行監控及緊急應變措施；另受\n理機關得依實際測試之複雜程度要求增加駕駛操控人\n員。\n(二)前款所規定之駕駛操控人員應符合下列條件：\n1.應為申請者或系統供應商授權符合資格之人員。\n2.應持有測試車輛所對應之適當種類駕駛執照達至少\n三年，且三年內無違反道路交通管理處罰條例第三\n十五條規定及無重大交通事故(道路交通事故處理辦\n法第二條第二款)紀錄。\n3.已完成申請者之自動駕駛訓練課程，充分瞭解所駕\n駛之測試車輛的自動駕駛技術之限制、功能與特性，\n並具備在道路上測試時均可安全操作測試車輛之能\n力。\n十、測試環境安全應依下列規定：\n(一)申請者應就其測試路線、時間、車速以及天氣限制條\n件提出說明，要求如下：\n1.應依照其測試車輛所設計能啟動自動駕駛模式之道\n路類型安排測試路線，並說明啟用自動駕駛模式測\n試行駛之路段。\n2.應說明測試時間(如白天或夜晚)。\n3.應說明測試時預計行駛之車速範圍。\n4.應說明測試車輛(輔助)自動駕駛系統可執行測試之\n天氣條件。\n(二)申請者在基於公眾安全為優先之前提下，應有以下安\n\n全措施：\n1.應於測試場域周圍設立警示標語，說明該路段進行\n自動駕駛車輛測試。\n2.應透過報章雜誌或媒體，公布其所進行之測試路線\n及時間，讓其它道路使用者清楚了解。\n十一、乘客與隱私應依下列規定：\n(一)乘客：申請者應於申請測試時說明測試車輛是否開\n放供一般民眾搭乘；如開放一般民眾於測試\n期間搭乘，不得有營利行為。\n(二)乘客隱私：當載運駕駛操控人員以外之乘客時，若\n有收集乘客相關個人資訊，應遵守個人\n資料保護法相關規定。\n十二、道路使用應依下列規定：\n(一)未經公路主管機關同意前，申請者不得建置或改造\n測試區域內之任何道路設施。如有建置或改造，測\n試終止後應依公路主管機關規定期限內復原。\n(二)公路主管機關得依據申請測試所需進行道路設施之\n建置或改造程度，要求申請者繳納保證金，並應於\n測試前繳足始可進行測試。測試終止、完成復原並\n經公路主管機關確認後無息退還；倘未依規定期限\n復原，公路主管機關得逕派工復原並沒收保證金。\n(三)測試車輛於測試時，應遵守道路交通管理處罰條例\n道路交通安全規則、道路交通標誌標線號誌設置規\n則以及道路交通事故處理辦法等相關交通規定。\n(四)申請者應依其申請之道路範圍執行自動駕駛系統測\n試，於申請範圍以外之區域，應由其他車輛載運。\n十三、資訊揭露應依下列規定：\n申請者應依受理機關所訂之期限內，定期透過書面報告或\n網路等方式揭露其申請試驗成果及相關資訊(包含事故及故障\n等相關訊息)。"},{"file_id":"0000238127","name":"附件二十一自動駕駛車輛申請道路測試作業規定.ODT","format":"ODT","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000238127&lan=C","fetched":true,"bytes":24209},{"file_id":"0000238128","name":"附件二十一之附表一自動駕駛車輛道路測試申請書.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000238128&lan=C","fetched":true,"bytes":182081,"pages":2,"text":"自動駕駛車輛道路測試申請書\n申請類型\n☐新申請\n☐展延\n\n申請者資料\n申請者名稱：\n申請者住址：\n聯絡人姓名：\n職稱：\n聯絡人電話：\n聯絡人傳真：\n聯絡人E-mail：\n統一編號：\n測試車輛資料\n車輛出廠年份車輛製造國家\n車輛廠牌\n車輛型式\n車身號碼\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n申請者名稱(章)：\n\n\n\n\n負責人(章)：\n\n\n\n\n\n\n\n\n中華民國       年       月       日"},{"file_id":"0000238129","name":"附件二十一之附表二申請者承諾書.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000238129&lan=C","fetched":true,"bytes":179958,"pages":2,"text":"申請者承諾書\n申請者                              ，謹依「自動駕駛車輛申請道\n路測試作業規定」向受理機關申請自動駕駛車輛道路測試，承諾遵守下\n列事項：\n1.為其所申請之道路測試的全權負責單位。\n2.投入測試之測試車輛已完成國內外封閉場域或國外一般道路測試。\n3.遵守受理機關及交通部隨時增加之所有規定，包括因規定改變或增補\n而隨時通知補正之文件或資料。\n4.測試申請經核准後，任何因與所申請測試相關事項所導致之責任與損\n失，應自行負擔行政、民事及刑事所有責任，且不會要求受理機關\n及交通部負責。\n5.當有任何影響原申請測試時所提供資訊正確性之情況改變或新的發展\n時，將立即向受理機關及交通部提出補正說明文件。\n\n\n申請者名稱(章)：\n\n\n\n負責人(章)：\n\n\n\n中華民國      年      月      日"},{"file_id":"0000264875","name":"附件二十二 裝載砂石土方車輛使用專用車輛或專用車廂規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000264875&lan=C","fetched":true,"bytes":178525,"pages":2,"text":"附件二十二 裝載砂石土方車輛使用專用車輛或專用車\n廂規定\n一、裝載砂石、土方之傾卸框式大貨車及傾卸框式半拖車，應依本規定使用專用車輛。\n二、經公路監理機關檢驗查核，依規定裝設下列裝置及標示者，登檢為砂石專用車：\n（一）裝設符合第三十九條或第三十九條之一規定之載重計、轉彎及倒車警報裝置、行\n車紀錄器、左右兩側之防止捲入裝置與後方之安全防護裝置（或保險槓）等設備。\n（二）貨廂容積應合於下列規定：\n  1.已登檢合格之砂石標示車：於九十一年六月一日以前，前單軸後雙軸式大貨車，\n貨廂容積以七立方公尺為上限；後雙軸式半拖車，貨廂容積以十四點七立方公尺\n為上限；前單軸後單軸式大貨車，貨廂容積以核定總重噸數除以三所得數為立方\n公尺為上限。\n  2.其他砂石專用車輛(包含前目繳、註、吊銷牌照者)：大貨車為其核定總重扣除核\n定空重所得之核定載重量，除以規定比重一點五，所得之數值為貨廂容積之立方\n數；半拖車為其核定聯結總重減去半拖車車重與六點五公噸所得之核定載重量，\n除以規定比重一點五，所得之數值為貨廂容積之立方數。\n  3.港區作業及總重八公噸以下混合裝載砂石、土方車輛：貨廂容積得不受前二目規\n定之限制。\n（三）貨廂外框顏色符合第四十二條第一項第十五款規定(港區作業及總重八公噸以下專\n用車輛除外)。\n（四）裝設機械式可密覆裝置或備有帆布能緊密覆蓋貨廂。\n（五）貨廂正後方，以黑色字體加漆號牌二點五倍之車輛牌照號碼。\n（六）除活動式尾門絞鏈外，貨廂後方活動式尾門高度不得超過貨廂側邊高度二十公分。\n三、港區作業為由登檢為砂石專用車時，應併同出具相關貨運公會或港區主管單位出具之證\n明（如工作證、通行證等），俾供公路監理機關查核登記。\n四、登檢為砂石專用車之車輛，公路監理資訊系統及行車執照或拖車使用證，應加註貨廂內\n框長、寬、高(貨廂容積不受第二點限制之車輛除外)及砂石專用車，另原砂石標示車、\n港區作業及總重八公噸以下混合裝載砂石、土方車輛，於砂石專用車字樣後，另行標示\n（標）、（港）、（混）以資識別。\n18\n\n五、依前二點登記為砂石專用車(港)之車輛，限自港區駛出且出具港區過磅單始得裝載砂石、\n土方。\n19"},{"file_id":"0000264876","name":"附件二十三 附載幼童之腳踏自行車、電動輔助自行車、自行車兒童座椅申請測試及合格標章作業規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000264876&lan=C","fetched":true,"bytes":3807782,"pages":8,"text":""},{"file_id":"0000329394","name":"附件二十四 申領汽車試車牌照審核作業規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000329394&lan=C","fetched":true,"bytes":240590,"pages":1,"text":"附件二十四 申領汽車試車牌照審核作業規定\n一、請領汽車試車牌照，應檢具下列資料向公路監理機關申請：\n(一)公司、行號主管機關核准公文(公司含登記表)影本或核發之證明\n書或研究機構法人證書。\n(二)汽車試車牌照登記書。\n(三)汽車試車計畫書。\n二、試車牌照之種類及使用規範如下：\n(一)第一類試車牌照：可懸掛於各式製造、研究或買賣試行汽車之試\n車牌照。\n(二)第二類試車牌照：限汽車買賣業領用之試車牌照，應懸掛於取得\n車輛型式安全審驗合格證明或已領過牌照之車輛；並按汽缸總排\n氣量分類為限懸掛於四千二百立方公分(或馬達馬力四百十四HP)\n以下汽車，及可懸掛於不限排氣量(或馬達馬力)汽車之試車牌照\n二種。\n三、汽車買賣業領用及續用試車牌照數量，以最近一年內買賣車輛數計算，\n申請第一付試車牌照至少一輛以上，申請第二付至少一百零一輛以上，\n申請第三付則需六百零一輛以上，同一領用主體以三付為限，並應檢\n具買賣相關證明文件(如:發票、交易紀錄等)。\n四、申請領用或續用汽車試車牌照時，經查領用人及名下登記之試車牌照，\n有下列情形之一者，應不予核發：\n(一)試車牌照逾期未繳還。\n(二)最近一年內違反道路交通安全規則第二十條第一項第一款、第二\n款、第六款規定達二次以上。"},{"file_id":"0000420183","name":"附件二十五 汽車用隔熱紙申請合格標識作業規定.PDF","format":"PDF","url":"https://law.moj.gov.tw/LawClass/LawGetFile.ashx?FileId=0000420183&lan=C","fetched":true,"bytes":260102,"pages":4,"text":"第三十九條、第三十九條之一、第三十九條之二附件二\n十五修正規定\n附件二十五 汽車用隔熱紙申請合格標識作業規定\n一、檢測項目及標準\n(一) 隔熱紙應使用符合中華民國國家標準CNS 12381「平板玻璃之透射率、\n反射率、發射率試驗法及建築用平板玻璃太陽能總透射率之計算」之\n可見光透射率與可見光反射率之計算規定、ISO 9050 「Glass in build-\ning－Determination of light transmittance, solar direct transmittance, total\nsolar energy transmittance, ultraviolet transmittance and related glazing fac-\ntors」之Light transmittance 規定，或車輛安全檢測基準「安全玻璃」\n之可見光透過率試驗規定，隔熱紙之可見光透過率應符合百分之七十\n或百分之四十。\n(二) 前款檢測項目及標準應符合申請時所對應最新版次，並經交通部指定\n之檢測機構檢測後出具檢測報告，另申請者得出具符合或等同前款中\n華民國國家標準、ISO 或車輛安全檢測基準之合格檢測報告，且經交\n通部指定之專業機構確認後替代之。\n二、申請合格標識與應檢附資料\n(一) 隔熱紙之國內製造廠、進口商（以下簡稱「申請者」）檢具下列資料\n向專業機構申請同型號規格隔熱紙之合格標識，申請資料並應加蓋申\n請者及其負責人印章，經專業機構確認申請者宣告檢測報告符合性後，\n出具汽車車窗及擋風玻璃黏貼隔熱紙合格報告（以下簡稱「合格報\n告」）並同意依第四點發放合格標識。\n1. 申請資格證明文件影本\n(1) 國內製造廠應檢附公司登記證明文件或商業登記證明文件，及工\n廠登記證明文件。\n(2) 進口商應檢附公司登記證明文件或商業登記證明文件；取得國外\n原製造廠授權資格者(以下簡稱「代理商」），另應檢附其授權\n證明文件。\n2. 規格技術資料\n(1) 基本資料（內容包含申請者名稱、廠牌、型號、製造工廠地址、\n檢測標準、檢測報告編號、可見光透過率、經銷商施工地點清冊\n等資訊）。\n(2) 自行烙印隔熱紙合格標識者，應檢附合格標識格式樣張說明資料\n（應包含廠牌、型號、可見光透過率）及標示位置與方式。\n\n\n(3) 第一點檢測項目及標準所規範之檢測報告。\n(二) 合格報告及其檢附文件登載內容有新增、變更或檢測項目版次更新時，\n申請者應檢附變更或新增內容之相關資料，經專業機構判定應重新檢\n測項目後，依第一點規定申請檢測，且依第二點規定經專業機構確認\n後變更合格報告與合格標識。\n(三) 合格報告遺失或毀損者，原申請者得檢附相關資料向專業機構申請補\n發。\n三、合格標識格式規定\n(一) 申請者應向專業機構申請合格標識。但國內製造廠或取得國外原製造\n廠授權資格之代理商於生產過程中或於國內加工烙印可將合格標識烙\n印於產品者，得自行烙印合格標識。\n(二) 申請者自行烙印之合格標識其格式得由申請者訂定，其內容至少應包\n含廠牌、型號及可見光透過率，每一字體大小至少0.3公分，並具備防\n偽功能。\n(三) 專業機構印製之合格標識，如下表格式範例。\n(四) 隔熱紙之合格標識應標示於可明顯辨識處。\n表一、專業機構印製合格標識範例\n樣式\n說明\n範例一：可見光透過率40% Min\n範例二：可見光透過率70% Min\n1. 合格標識顏色為黑字、黑框。\n2. 每一字體大小至少0.3公分。\n3. 合格標識序號為十碼，得以英\n文、數字混合排列組合。\n\n四、合格標識管理\n(一) 申請者應確保及聲明生產製造之產品與申請合格標識之產品原型號一\n致，並依下列規定標示合格標識：\n1. 申請者自行烙印：申請者應於生產過程中將具有防偽功能之合格標識\n逐一烙印於產品上，合格標識應使用不易變質之材質製作，內容清晰\n\n\n可辨且不易磨滅，並以永久固定方式標示，且應對其自行烙印之合格\n標識負保管責任，必要時專業機構得辦理工廠查核；其生產地點有增\n加、變更、遷移或合格標識變更時亦同。\n2. 專業機構印製：申請者應檢具申請合格標識之產品清冊向專業機構申\n請合格標識，專業機構受理申請後應派員至申請者指定地點進行抽樣\n比對，經比對或抽樣檢測產品符合合格報告所載之相關規格、產品數\n量與申請合格標識數量一致且符合最新版次之檢測項目及標準後發放\n之。申請者取得合格標識後應依公路監理機關規定逐一標示於產品上，\n且應妥善保存合格標識使用紀錄，以供備查。\n(二) 專業機構得辦理通路查核或現場查核確認其生產之一致性與合格標識\n標示、保存情況及使用紀錄。申請者應依專業機構要求配合辦理查核\n作業，拒絕配合辦理者，專業機構得宣告其合格報告及合格標識失效，\n申請者並應依專業機構規定期限繳回尚未使用之合格標識。\n1. 通路查核地點包括在倉儲或經銷商營業場所。\n2. 現場查核地點包括製造廠或使用該產品之施作現場。\n(三) 申請自行烙印之申請者應依專業機構要求提報合格標識使用紀錄及產\n品存放地點，專業機構得不定期辦理產品抽驗，確認產品是否符合合\n格報告所載之相關規格、合格標識樣式與標示位置，且符合最新版次\n之檢測項目及標準。\n(四) 如有申請資格不符、未依專業機構要求提報合格標識使用情況、工廠\n查核不合格、合格標識標示於非核准之產品上、其產品抽驗不合格或\n其他不符合事項者，經專業機構查明屬實後應停止其使用合格標識。\n申請者提出並完成改善措施後，由專業機構查核確認後，始得恢復；\n若申請者未提出改善措施或所提改善措施經專業機構查核仍不合格者，\n專業機構應宣告其合格報告及合格標識失效，申請者並應依專業機構\n規定期限繳回尚未使用之合格標識。\n(五) 產品有不符合第一點檢測項目及標準之情事，或於有事實足認其提供\n產品有危害消費者安全與健康之虞時，申請者應依消費者保護法第七\n條及第十條等規定辦理；相關召回改正實務作業，參照交通部所訂汽\n車安全性調查召回改正及監督管理辦法及依汽車安全性調查及召回改\n正成效查核作業原則規定，對國內使用同一批號產品辦理召回改正作\n業。\n五、附則\n(一) 本作業規定發布前，申請者已取得符合本作業規定之檢測報告，得於\n本作業規定發布實施後十二個月內，依本作業相關規定向專業機構申\n\n\n請合格報告與合格標識。\n(二) 由專業機構印製之合格標識，如因故損壞致不堪使用或遺失，應由\n申請者向專業機構申請補發。\n(三) 交通部得視需要辦理產品抽驗，經查有未符合規定者，依本附件規定\n辦理。\n(四) 專業機構辦理本作業遇有疑義時，得邀集公路監理機關、專家學者及\n公會等相關代表，共同處理疑義案件、研議申請測試及合格標識作業\n相關事宜，且其會議結論或紀錄經交通部同意後，併同作為辦理隔熱\n紙申請測試及合格標識作業之依據"}]};
